1	/**
2	 * pi-tool-search — defer fat/situational tool descriptions behind a
3	 * `tool_search` discovery tool.
4	 *
5	 * Lifecycle:
6	 *
7	 *   load              register tool_search, hooks
8	 *   session_start     read config, build catalog of deferrable tools,
9	 *                     scan branch for previously-discovered tools, compute
10	 *                     final active set, call setActiveTools()
11	 *   before_agent_start  inject <deferred-tools> hint block into the prompt
12	 *   tool_search call  rank against catalog, activate matches, persist
13	 *                     discoveries via appendEntry()
14	 *
15	 * See ../../../PLAN.md for the full design.
16	 */
17	import { Type } from "@sinclair/typebox";
18	import type { ExtensionAPI } from "@valkyriweb/pi-coding-agent";
19	
20	import { loadConfig, type ToolSearchConfig } from "./config.ts";
21	import { buildCatalog, computeActiveTools, hasToolName, normalizeToolName, type CatalogEntry, type DeferredToolMode } from "./catalog.ts";
22	import { canonicalToolKey, parseSelectNames, search } from "./search.ts";
23	import { recordDiscovery, scanDiscoveredTools } from "./persistence.ts";
24	
25	/** Per-session state. Refreshed on every session_start and model boundary. */
26	interface SessionState {
27	  config: ToolSearchConfig;
28	  catalog: CatalogEntry[];
29	  /** Model selected for this request. Used only for deterministic provider wire-name mapping. */
30	  model: unknown;
31	  /** How this model keeps deferred tool schemas available without mutating tools[] after search. */
32	  deferredToolMode: DeferredToolMode;
33	  /** Set of tool names already activated this session (incl. previously-discovered). */
34	  discovered: Set<string>;
35	}
36	
37	const SearchParams = Type.Object({
38	  query: Type.String({
39	    description:
40	      "Search query. Plain keywords for ranked search (e.g. 'click ui'). " +
41	      "'select:Name1,Name2' for direct activation by exact tool name. " +
42	      "Prefix any token with '+' to require it (e.g. '+screenshot click').",
43	  }),
44	  max_results: Type.Optional(
45	    Type.Number({
46	      description: "Maximum number of tools to return and activate. Default 5.",
47	      default: 5,
48	    }),
49	  ),
50	});
51	
52	const DEFERRED_BLOCK_OPEN = "<deferred-tools>";
53	const DEFERRED_BLOCK_CLOSE = "</deferred-tools>";
54	const PI_GOAL_CUSTOM_ENTRY_TYPE = "pi-codex-goal";
55	const PI_GOAL_ACTIVE_TOOLS = ["get_goal", "update_goal", "goal_wait", "rewrite_goal_objective"];
56	
57	export default function (pi: ExtensionAPI): void {
58	  // Per-session state keyed by session id.
59	  //
60	  // CACHE CRITICAL: parent + sub-agent Pi sessions share the same extension
61	  // closure in one process. A single `state` variable lets a sub-agent's
62	  // `session_start` overwrite the parent's `discovered` set; the parent's
63	  // next `before_agent_start` then rebuilds its active tools from the wrong
64	  // discovery state and silently drops tools that were previously active
65	  // (e.g. WebFetch disappears when sub-agent loaded WebSearch). The bridge
66	  // sees `tools added/removed` and busts the prefix.
67	  //
68	  // Keying by session id isolates parent/child cleanly. Sub-agents that want
69	  // to inherit parent's discovered set still do so via `scanDiscoveredTools`
70	  // (persisted custom session entries) at their own session_start.
71	  const stateBySession = new Map<string, SessionState>();
72	  // Fallback slot for contexts that don't expose a session id. Mirrors the
73	  // pre-keying single-slot semantics.
74	  let legacyState: SessionState | null = null;
75	
76	  function resolveSessionId(ctx: unknown): string | null {
77	    const sm = (ctx as { sessionManager?: { getSessionId?: () => string | undefined } })?.sessionManager;
78	    return sm?.getSessionId?.() ?? null;
79	  }
80	
81	  function readState(ctx: unknown): SessionState | null {
82	    const id = resolveSessionId(ctx);
83	    if (id) return stateBySession.get(id) ?? null;
84	    return legacyState;
85	  }
86	
87	  function writeState(ctx: unknown, s: SessionState | null): void {
88	    const id = resolveSessionId(ctx);
89	    if (id) {
90	      if (s) stateBySession.set(id, s);
91	      else stateBySession.delete(id);
92	      return;
93	    }
94	    legacyState = s;
95	  }
96	
97	  // ─── tool_search tool ──────────────────────────────────────────────────
98	  pi.registerTool({
99	    name: "tool_search",
100	    label: "Tool Search",
101	    description:
102	      "Activate a tool listed in <deferred-tools> so its full schema loads and you can call it. " +
103	      "Pass `select:ExactName` (or comma list) to load by name, or plain keywords to search.",
104	    parameters: SearchParams,
105	    promptSnippet: "load deferred tool schemas by name (`select:Foo`) or keyword",
106	
107	    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
108	      const state = readState(ctx);
109	      if (!state) {
110	        return {
111	          content: [{ type: "text", text: "tool_search not initialised — session_start did not fire." }],
112	          details: { error: "no_state" },
113	          isError: true,
114	        };
115	      }
116	
117	      refreshModelState(state, ctx);
118	
119	      const query = rewriteProviderSpecificToolQuery(params.query, state);
120	      const matches = search(state.catalog, query, params.max_results ?? 5);
121	
122	      if (matches.length === 0) {
123	        // CC parity: `select:` for a tool that is already active is a harmless
124	        // no-op, not an error. Always-active capabilities are omitted from the
125	        // deferred catalog, so search() returns nothing for them. Resolve those
126	        // requested names against the active set without mutating tools[], the
127	        // catalog, or the deferred-tools block.
128	        const requested = parseSelectNames(query);
129	        if (requested && requested.length > 0) {
130	          const activeNames = pi.getActiveTools();
131	          const activeSet = new Set(activeNames);
132	          const alreadyActive: string[] = [];
133	          for (const name of requested) {
134	            if (hasToolName(activeSet, name)) {
135	              alreadyActive.push(name);
136	              continue;
137	            }
138	            const key = canonicalToolKey(name);
139	            if (key.length === 0) continue;
140	            const hits = activeNames.filter((activeName) => canonicalToolKey(activeName) === key);
141	            if (hits.length === 1) alreadyActive.push(name);
142	          }
143	          if (alreadyActive.length > 0) {
144	            return {
145	              content: [
146	                {
147	                  type: "text",
148	                  text:
149	                    `${alreadyActive.length} tool(s) already loaded: ${alreadyActive.join(", ")}\n\n` +
150	                    "These tools are already in your active tool list — call them directly.",
151	                },
152	              ],
153	              details: { query, originalQuery: params.query, matches: [], alreadyActive },
154	            };
155	          }
156	        }
157	
158	        const available = state.catalog.map((e) => e.name).join(", ");
159	        return {
160	          content: [
161	            {
162	              type: "text",
163	              text:
164	                `No deferred tools matched "${query}".\n\n` +
165	                (available
166	                  ? `Available deferred tools: ${available}`
167	                  : "No tools are currently deferred."),
168	            },
169	          ],
170	          details: { query, originalQuery: params.query, matches: [] },
171	        };
172	      }
173	
174	      // Native paths avoid mutating Pi's active native-tool list after search.
175	      // Anthropic discovers via appended `tool_reference` blocks. Codex keeps
176	      // tools[] byte-stable with `defer_loading:true`; the model can call the
177	      // matched tool directly after the search turn without a schema swap.
178	      const referenced: Array<{ catalogName: string; referenceName: string }> = [];
179	      const codexDeferred: string[] = [];
180	      const newlyActive: string[] = [];
181	      const current = new Set(pi.getActiveTools());
182	      const normalizedCurrent = new Set([...current].map(normalizeToolName));
183	      for (const m of matches) {
184	        if (state.deferredToolMode !== "none" && m.entry.deferLoading) {
185	          if (!hasToolName(state.discovered, m.entry.name)) {
186	            if (state.deferredToolMode === "anthropic_tool_reference") {
187	              referenced.push({
188	                catalogName: m.entry.name,
189	                // Emit pi's bare internal name. The provider tool-name
190	                // transform is owned entirely by pi-claude-bridge (see note
191	                // below) so the extension and bridge allowlists can never drift.
192	                referenceName: m.entry.name,
193	              });
194	            } else {
195	              codexDeferred.push(m.entry.name);
196	            }
197	            state.discovered.add(m.entry.name);
198	            if (state.config.rememberDiscovered) {
199	              recordDiscovery(pi, m.entry.name);
200	            }
201	          }
202	          continue;
203	        }
204	
205	        // Active-tool path: append-only activation for tools that do not use
206	        // native deferred references.
207	        if (!hasToolName(normalizedCurrent, m.entry.name)) {
208	          current.add(m.entry.name);
209	          normalizedCurrent.add(normalizeToolName(m.entry.name));
210	          newlyActive.push(m.entry.name);
211	          state.discovered.add(m.entry.name);
212	          if (state.config.rememberDiscovered) {
213	            recordDiscovery(pi, m.entry.name);
214	          }
215	        }
216	      }
217	      if (newlyActive.length > 0) {
218	        pi.setActiveTools([...current]);
219	      }
220	
221	      const lines = matches.map((m) => `- ${m.entry.name}: ${m.entry.description}`);
222	      const changed = referenced.length + codexDeferred.length + newlyActive.length;
223	      const summary =
224	        changed === matches.length
225	          ? `Loaded ${changed} deferred tool(s) for this session`
226	          : changed === 0
227	            ? `${matches.length} tool(s) already loaded`
228	            : `Loaded ${changed} new tool(s); ${matches.length - changed} already loaded`;
229	      const modeNote =
230	        referenced.length > 0
231	          ? "Loaded as appended tool_reference message blocks; native tool schemas were not mutated."
232	          : codexDeferred.length > 0
233	            ? "Matched tools are already present as stable Codex defer_loading schemas; native tool schemas were not mutated. Call them directly."
234	            : "Full schemas are now in your tool list. Call them directly.";
235	      const text = `${summary}:\n\n${lines.join("\n")}\n\n${modeNote}`;
236	
237	      return {
238	        content:
239	          referenced.length > 0
240	            ? referenced.map(({ referenceName }) => ({ type: "tool_reference" as const, name: referenceName }))
241	            : [{ type: "text" as const, text }],
242	        details: {
243	          query,
244	          originalQuery: params.query,
245	          matches: matches.map((m) => m.entry.name),
246	          newlyActivated: newlyActive,
247	          referenced: referenced.map(({ catalogName }) => catalogName),
248	          codexDeferred,
249	          referenceNames: referenced.map(({ referenceName }) => referenceName),
250	          mode: state.deferredToolMode,
251	          summary: text,
252	        },
253	      };
254	    },
255	  });
256	
257	  // ─── session_start: catalog build + active-tools enforcement ──────────
258	  pi.on("session_start", (_event, ctx) => {
259	    const config = withRuntimeAlwaysActive(loadConfig(), ctx);
260	    const deferSet = new Set(config.defer);
261	    const alwaysActiveSet = new Set(config.alwaysActive);
262	    const previouslyDiscovered = config.rememberDiscovered ? scanDiscoveredTools(ctx) : new Set<string>();
263	
264	    const next: SessionState = {
265	      config,
266	      catalog: buildCatalog(pi, deferSet, alwaysActiveSet, config.deferByDefault),
267	      model: ctx.model,
268	      deferredToolMode: getDeferredToolMode(ctx.model),
269	      discovered: new Set(previouslyDiscovered),
270	    };
271	    writeState(ctx, next);
272	
273	    // CACHE CRITICAL: flip deferred catalog tools that the provider can serve as
274	    // native `defer_loading` stubs into real deferLoading definitions, ONCE per
275	    // session (never per-turn). Without this the ~27 deferred-but-non-deferLoading
276	    // tools (computer_use, Workflow, AskUserQuestion, …) only live in the
277	    // <deferred-tools> text block, and discovery adds them to tools[] as FULL
278	    // schemas via setActiveTools — mutating the cached prefix and bursting the
279	    // prompt cache. After the override they are stable defer_loading stubs from
280	    // turn 1, and discovery appends a tool_reference block in the message tail
281	    // (anthropic_tool_reference) / stays byte-stable (codex) instead.
282	    applyNativeDeferralOverride(pi, next);
283	
284	    applyDeferral(pi, next);
285	  });
286	
287	  // Release the per-session slot so the map doesn't grow without bound.
288	  pi.on("session_shutdown", (_event, ctx) => {
289	    writeState(ctx, null);
290	  });
291	
292	  // ─── before_agent_start: enforce deferral + inject hints ──────────────
293	  pi.on("before_agent_start", (event, ctx) => {
294	    const s = readState(ctx);
295	    if (!s) return undefined;
296	    s.config = withRuntimeAlwaysActive(s.config, ctx);
297	    refreshModelState(s, ctx);
298	
299	    // CACHE CRITICAL: this hook rewrites the system prompt and active tool
300	    // list at the last safe point before the provider request. Keep it
301	    // deterministic and idempotent; prompt/schema churn here is a direct
302	    // cache-prefix bust.
303	    //
304	    // Some extensions register/refresh tools during startup and can re-expand
305	    // the active set after our session_start handler. Enforce the catalog at
306	    // the last safe point before the provider request, then render from Pi's
307	    // rebuilt prompt so context accounting and provider schemas agree.
308	    applyDeferral(pi, s);
309	
310	    const currentPrompt = typeof ctx?.getSystemPrompt === "function" ? ctx.getSystemPrompt() : event.systemPrompt;
311	
312	    if (!s.config.showDeferredHints) return { systemPrompt: currentPrompt };
313	    if (s.catalog.length === 0) return { systemPrompt: currentPrompt };
314	
315	    // Filter out eager active schemas only. Provider-native deferred tools may
316	    // appear in tools[] as `defer_loading: true`; they still need the stable
317	    // text index so the model can discover them without paying full schema cost.
318	    const activeNow = getEagerActiveCapabilities(pi);
319	    const stillDeferred = s.catalog.filter(
320	      (e) => !hasToolName(s.discovered, e.name) && !activeNow.has(normalizeToolName(e.name)),
321	    );
322	    if (stillDeferred.length === 0) return { systemPrompt: currentPrompt };
323	
324	    const block = renderDeferredBlock(stillDeferred);
325	    const updated = injectOrReplaceBlock(currentPrompt, block);
326	    if (updated === event.systemPrompt) return undefined;
327	    return { systemPrompt: updated };
328	  });
329	}
330	
331	function withRuntimeAlwaysActive(config: ToolSearchConfig, ctx: unknown): ToolSearchConfig {
332	  if (!hasNonCompletePiGoal(ctx)) return config;
333	
334	  // CACHE CRITICAL: pi-goal control tools are dynamic by session state. Keep
335	  // them out of ordinary sessions, but make them first-turn active when a
336	  // non-complete goal already exists so goal continuations do not churn the
337	  // tool schema list every turn.
338	  const alwaysActive = [...config.alwaysActive];
339	  for (const toolName of PI_GOAL_ACTIVE_TOOLS) {
340	    if (!alwaysActive.includes(toolName)) alwaysActive.push(toolName);
341	  }
342	  return { ...config, alwaysActive };
343	}
344	
345	function hasNonCompletePiGoal(ctx: unknown): boolean {
346	  const entries = getBranchEntries(ctx);
347	  let status: string | null = null;
348	
349	  for (const entry of entries) {
350	    if (!entry || typeof entry !== "object") continue;
351	    const candidate = entry as { type?: unknown; customType?: unknown; data?: unknown };
352	    if (candidate.type !== "custom" || candidate.customType !== PI_GOAL_CUSTOM_ENTRY_TYPE) continue;
353	    const data = candidate.data;
354	    if (!data || typeof data !== "object") continue;
355	    const goalEntry = data as { version?: unknown; kind?: unknown; goal?: unknown };
356	    if (goalEntry.version !== 1) continue;
357	    if (goalEntry.kind === "clear") {
358	      status = null;
359	      continue;
360	    }
361	    if (goalEntry.kind !== "set" || !goalEntry.goal || typeof goalEntry.goal !== "object") continue;
362	    const goal = goalEntry.goal as { status?: unknown };
363	    status = typeof goal.status === "string" ? goal.status : null;
364	  }
365	
366	  return status !== null && status !== "complete";
367	}
368	
369	function getBranchEntries(ctx: unknown): unknown[] {
370	  if (!ctx || typeof ctx !== "object") return [];
371	  const sessionManager = (ctx as { sessionManager?: unknown }).sessionManager;
372	  if (!sessionManager || typeof sessionManager !== "object") return [];
373	  const getBranch = (sessionManager as { getBranch?: unknown }).getBranch;
374	  if (typeof getBranch !== "function") return [];
375	  const entries = getBranch.call(sessionManager);
376	  return Array.isArray(entries) ? entries : [];
377	}
378	
379	/**
380	 * `pi.tools` widened with the optional post-registration deferral seam so this
381	 * extension compiles against both older cores (method absent) and newer cores
382	 * (method present). Runtime presence is checked before use.
383	 */
384	type DeferralCapableToolRegistry = ExtensionAPI["tools"] & {
385	  setDeferredOverrides?: (names: string[]) => void;
386	};
387	
388	/**
389	 * Force every deferred catalog tool that the provider can serve as a native
390	 * `defer_loading` stub to be a real `deferLoading` definition, via the core
391	 * `pi.tools.setDeferredOverrides` seam.
392	 *
393	 * CACHE CRITICAL + run ONCE per session (session_start only). The core method is
394	 * idempotent, but this must never run per-turn. After the override the catalog's
395	 * `deferLoading` reflects reality, so `computeActiveTools` keeps these tools
396	 * active as stubs and the execute() tool_reference / codex defer paths take over
397	 * from the cache-bursting full-schema activation path.
398	 */
399	function applyNativeDeferralOverride(pi: ExtensionAPI, state: SessionState): void {
400	  // Only providers that serve native deferred schemas benefit. In "none" mode
401	  // discovery falls back to full-schema activation regardless, and flipping
402	  // deferLoading would not change serialization — leave those sessions untouched.
403	  if (state.deferredToolMode === "none") return;
404	
405	  // Defensive access: older pi cores have no `setDeferredOverrides` on the tool
406	  // registry view. Optional-chain so the extension keeps working (the deferred
407	  // tools just stay text-only there) instead of crashing or failing to compile.
408	  const toolsView = pi.tools as DeferralCapableToolRegistry;
409	  const setDeferredOverrides = toolsView.setDeferredOverrides;
410	  if (typeof setDeferredOverrides !== "function") return;
411	
412	  // Catalog already excludes alwaysActive tools; pick those not yet deferLoading.
413	  const toOverride = state.catalog.filter((entry) => !entry.deferLoading).map((entry) => entry.name);
414	  if (toOverride.length === 0) return;
415	
416	  setDeferredOverrides.call(pi.tools, toOverride);
417	
418	  // Rebuild the catalog from the now-updated definitions and verify the
419	  // invariant: every deferred catalog tool should now be a defer_loading stub.
420	  // Anything still eager (e.g. a tool the core refused to override because it is
421	  // alwaysLoad) would still burst the cache on discovery — surface it once.
422	  const deferSet = new Set(state.config.defer);
423	  const alwaysActiveSet = new Set(state.config.alwaysActive);
424	  state.catalog = buildCatalog(pi, deferSet, alwaysActiveSet, state.config.deferByDefault);
425	  const stragglers = state.catalog.filter((entry) => !entry.deferLoading).map((entry) => entry.name);
426	  if (stragglers.length > 0) {
427	    console.warn(
428	      `[tool-search] ${stragglers.length} deferred tool(s) remain non-deferLoading in a native-deferred ` +
429	        `session and may burst the prompt cache on discovery: ${stragglers.join(", ")}`,
430	    );
431	  }
432	}
433	
434	function applyDeferral(pi: ExtensionAPI, state: SessionState): void {
435	  // CACHE CRITICAL: tools[] is a provider request parameter, and adding/removing
436	  // schemas mid-session changes the cached prefix. Only mutate when the
437	  // normalized catalog/discovery state actually changes.
438	  const deferSet = new Set(state.config.defer);
439	  const alwaysActiveSet = new Set(state.config.alwaysActive);
440	  const catalog = buildCatalog(pi, deferSet, alwaysActiveSet, state.config.deferByDefault);
441	  state.catalog = catalog;
442	  const finalActive = computeActiveTools(
443	    pi,
444	    deferSet,
445	    alwaysActiveSet,
446	    state.discovered,
447	    state.config.deferByDefault,
448	    state.deferredToolMode,
449	  );
450	  const current = pi.getActiveTools();
451	  if (sameNames(current, finalActive)) return;
452	  pi.setActiveTools(finalActive);
453	}
454	
455	function getEagerActiveCapabilities(pi: ExtensionAPI): Set<string> {
456	  const definitionsByCapability = new Map<string, { name: string; deferLoading?: boolean }>();
457	  for (const tool of pi.tools.definitions()) {
458	    if (!tool || typeof tool.name !== "string") continue;
459	    definitionsByCapability.set(normalizeToolName(tool.name), tool);
460	  }
461	
462	  const eager = new Set<string>();
463	  for (const name of pi.getActiveTools()) {
464	    if (typeof name !== "string") continue;
465	    const capability = normalizeToolName(name);
466	    const definition = definitionsByCapability.get(capability);
467	    if (definition?.deferLoading === true) continue;
468	    eager.add(capability);
469	  }
470	
471	  const activeDefinitions = pi.tools.active() as unknown[];
472	  for (const tool of activeDefinitions) {
473	    if (!tool || typeof tool !== "object") continue;
474	    const definitionLike = tool as { name?: unknown; deferLoading?: unknown };
475	    if (typeof definitionLike.name !== "string") continue;
476	    const capability = normalizeToolName(definitionLike.name);
477	    const definition = definitionsByCapability.get(capability);
478	    if (definitionLike.deferLoading === true || definition?.deferLoading === true) continue;
479	    eager.add(capability);
480	  }
481	  return eager;
482	}
483	
484	function sameNames(a: readonly string[], b: readonly string[]): boolean {
485	  if (a.length !== b.length) return false;
486	  return a.every((name, index) => name === b[index]);
487	}
488	
489	function refreshModelState(state: SessionState, ctx: unknown): void {
490	  if (!ctx || typeof ctx !== "object" || !("model" in ctx)) return;
491	  const model = (ctx as { model?: unknown }).model;
492	  const mode = getDeferredToolMode(model);
493	  if (state.model === model && state.deferredToolMode === mode) return;
494	  state.model = model;
495	  state.deferredToolMode = mode;
496	}
497	
498	function rewriteProviderSpecificToolQuery(query: string, state: SessionState): string {
499	  const requested = parseSelectNames(query);
500	  if (!requested || requested.length === 0) return query;
501	
502	  const names = requested.map((name) => rewriteProviderSpecificToolName(name, state));
503	  if (names.every((name, index) => name === requested[index])) return query;
504	  return `select:${names.join(",")}`;
505	}
506	
507	// Codex exposes provider-specific web tools through pi-codex-conversion under
508	// dotted names (`web.run` for search, `web.fetch` for the local Codex-only
509	// fetch). The Anthropic/Claude marker tools (`web_search`, `web_fetch`)
510	// otherwise canonical-match these `WebSearch`/`WebFetch` selections and leave
511	// the real Codex tools undiscovered. Under Codex deferral, redirect each
512	// canonical key to its Codex tool — but only when that tool is actually in the
513	// catalog, so Claude sessions keep selecting the Claude-native tools.
514	const CODEX_TOOL_ALIASES: Readonly<Record<string, string>> = {
515	  "search web": "web.run",
516	  "fetch web": "web.fetch",
517	};
518	
519	function rewriteProviderSpecificToolName(name: string, state: SessionState): string {
520	  if (state.deferredToolMode !== "openai_codex_defer_loading") return name;
521	  const target = CODEX_TOOL_ALIASES[canonicalToolKey(name)];
522	  if (target && state.catalog.some((entry) => entry.name === target)) return target;
523	  return name;
524	}
525	
526	function getDeferredToolMode(model: unknown): DeferredToolMode {
527	  if (!model || typeof model !== "object") return "none";
528	  const candidate = model as { api?: unknown; id?: unknown; compat?: unknown };
529	  if (candidate.api === "openai-codex-responses") return "openai_codex_defer_loading";
530	  if (candidate.api !== "anthropic-messages") return "none";
531	  if (typeof candidate.id === "string" && candidate.id.toLowerCase().includes("haiku")) return "none";
532	  const compat = candidate.compat as { supportsDeferredTools?: unknown } | undefined;
533	  return compat?.supportsDeferredTools === false ? "none" : "anthropic_tool_reference";
534	}
535	
536	// NOTE: the provider tool-name transform (mcp__ prefixing for the Anthropic
537	// OAuth wire format) lives entirely in pi-claude-bridge
538	// (prefixToolName / rewriteToolReferenceNames in pi-claude-bridge/index.js).
539	// This extension emits pi's bare internal names for tool_reference blocks; the
540	// bridge prefixes them on the wire and strips them on the response. Keeping the
541	// allowlist in one place (the bridge) is what prevents the drift that caused
542	// the historical "TodoWrite not found" 400.
543	
544	/**
545	 * Build the `<deferred-tools>` block. Keep startup discovery broker-first:
546	 * do not list every deferred name/description in the cached prefix. `tool_search`
547	 * owns search/listing and returns exact matches as appended tool results or
548	 * provider-native `tool_reference` blocks.
549	 */
550	function renderDeferredBlock(entries: readonly CatalogEntry[]): string {
551	  const webTools = entries
552	    .map((entry) => entry.name)
553	    .filter((name) => name === "web_search" || name === "web_fetch");
554	  const webHint = webTools.length
555	    ? `- Native web tools available: ${webTools.join(", ")}. For user requests to search/fetch the web, call tool_search({"query":"select:<ExactName>"}) and then call the discovered tool; do not load web-search/web-fetch skill refs as a substitute.\n`
556	    : "";
557	  return `\n\n${DEFERRED_BLOCK_OPEN}\n- ${entries.length} deferred tools available. Use tool_search({"query":"<capability>"}) or tool_search({"query":"select:<ExactName>"}) to discover/load exact tools on demand.\n${webHint}${DEFERRED_BLOCK_CLOSE}`;
558	}
559	
560	function truncate(s: string, max: number): string {
561	  if (s.length <= max) return s;
562	  return s.slice(0, max - 1) + "…";
563	}
564	
565	/**
566	 * Insert (or replace) the deferred-tools block in the system prompt.
567	 *
568	 * Idempotent: if the block already exists, swap its contents in place.
569	 * Otherwise append at the end. Either way the cache breakpoint is at most
570	 * one place changed per turn.
571	 */
572	function injectOrReplaceBlock(prompt: string, block: string): string {
573	  const openIdx = prompt.indexOf(DEFERRED_BLOCK_OPEN);
574	  if (openIdx < 0) {
575	    return prompt + block;
576	  }
577	  const closeIdx = prompt.indexOf(DEFERRED_BLOCK_CLOSE, openIdx);
578	  if (closeIdx < 0) {
579	    // Malformed prior block — just append a new one. Old fragment becomes orphan text.
580	    return prompt + block;
581	  }
582	  // Replace the whole block including the leading "\n\n" we inserted before it.
583	  // Walk back over up to 2 leading newlines to avoid blank-line buildup.
584	  let start = openIdx;
585	  if (start >= 2 && prompt.slice(start - 2, start) === "\n\n") start -= 2;
586	  return prompt.slice(0, start) + block + prompt.slice(closeIdx + DEFERRED_BLOCK_CLOSE.length);
587	}
588

