/**
 * pi-tool-search — defer fat/situational tool descriptions behind a
 * `tool_search` discovery tool.
 *
 * Lifecycle:
 *
 *   load              register tool_search, hooks
 *   session_start     read config, build catalog of deferrable tools,
 *                     scan branch for previously-discovered tools, compute
 *                     final active set, call setActiveTools()
 *   before_agent_start  inject <deferred-tools> hint block into the prompt
 *   tool_search call  rank against catalog, activate matches, persist
 *                     discoveries via appendEntry()
 *
 * See ../../../PLAN.md for the full design.
 */
import { Type } from "@sinclair/typebox";
import type { ExtensionAPI } from "@valkyriweb/pi-coding-agent";

import { loadConfig, type ToolSearchConfig } from "./config.ts";
import { buildCatalog, computeActiveTools, hasToolName, normalizeToolName, type CatalogEntry, type DeferredToolMode } from "./catalog.ts";
import { canonicalToolKey, parseSelectNames, search } from "./search.ts";
import { recordDiscovery, scanDiscoveredTools } from "./persistence.ts";

/** Per-session state. Refreshed on every session_start and model boundary. */
interface SessionState {
  config: ToolSearchConfig;
  catalog: CatalogEntry[];
  /** Model selected for this request. Used only for deterministic provider wire-name mapping. */
  model: unknown;
  /** How this model keeps deferred tool schemas available without mutating tools[] after search. */
  deferredToolMode: DeferredToolMode;
  /** Set of tool names already activated this session (incl. previously-discovered). */
  discovered: Set<string>;
}

const SearchParams = Type.Object({
  query: Type.String({
    description:
      "Search query. Plain keywords for ranked search (e.g. 'click ui'). " +
      "'select:Name1,Name2' for direct activation by exact tool name. " +
      "Prefix any token with '+' to require it (e.g. '+screenshot click').",
  }),
  max_results: Type.Optional(
    Type.Number({
      description: "Maximum number of tools to return and activate. Default 5.",
      default: 5,
    }),
  ),
});

const DEFERRED_BLOCK_OPEN = "<deferred-tools>";
const DEFERRED_BLOCK_CLOSE = "</deferred-tools>";
const PI_GOAL_CUSTOM_ENTRY_TYPE = "pi-codex-goal";
const PI_GOAL_ACTIVE_TOOLS = ["get_goal", "update_goal", "goal_wait", "rewrite_goal_objective"];

export default function (pi: ExtensionAPI): void {
  // Per-session state keyed by session id.
  //
  // CACHE CRITICAL: parent + sub-agent Pi sessions share the same extension
  // closure in one process. A single `state` variable lets a sub-agent's
  // `session_start` overwrite the parent's `discovered` set; the parent's
  // next `before_agent_start` then rebuilds its active tools from the wrong
  // discovery state and silently drops tools that were previously active
  // (e.g. WebFetch disappears when sub-agent loaded WebSearch). The bridge
  // sees `tools added/removed` and busts the prefix.
  //
  // Keying by session id isolates parent/child cleanly. Sub-agents that want
  // to inherit parent's discovered set still do so via `scanDiscoveredTools`
  // (persisted custom session entries) at their own session_start.
  const stateBySession = new Map<string, SessionState>();
  // Fallback slot for contexts that don't expose a session id. Mirrors the
  // pre-keying single-slot semantics.
  let legacyState: SessionState | null = null;

  function resolveSessionId(ctx: unknown): string | null {
    const sm = (ctx as { sessionManager?: { getSessionId?: () => string | undefined } })?.sessionManager;
    return sm?.getSessionId?.() ?? null;
  }

  function readState(ctx: unknown): SessionState | null {
    const id = resolveSessionId(ctx);
    if (id) return stateBySession.get(id) ?? null;
    return legacyState;
  }

  function writeState(ctx: unknown, s: SessionState | null): void {
    const id = resolveSessionId(ctx);
    if (id) {
      if (s) stateBySession.set(id, s);
      else stateBySession.delete(id);
      return;
    }
    legacyState = s;
  }

  // ─── tool_search tool ──────────────────────────────────────────────────
  pi.registerTool({
    name: "tool_search",
    label: "Tool Search",
    description:
      "Activate a tool listed in <deferred-tools> so its full schema loads and you can call it. " +
      "Pass `select:ExactName` (or comma list) to load by name, or plain keywords to search.",
    parameters: SearchParams,
    promptSnippet: "load deferred tool schemas by name (`select:Foo`) or keyword",

    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const state = readState(ctx);
      if (!state) {
        return {
          content: [{ type: "text", text: "tool_search not initialised — session_start did not fire." }],
          details: { error: "no_state" },
          isError: true,
        };
      }

      refreshModelState(state, ctx);

      const query = rewriteProviderSpecificToolQuery(params.query, state);
      const matches = search(state.catalog, query, params.max_results ?? 5);

      if (matches.length === 0) {
        // CC parity: `select:` for a tool that is already active is a harmless
        // no-op, not an error. Always-active capabilities are omitted from the
        // deferred catalog, so search() returns nothing for them. Resolve those
        // requested names against the active set without mutating tools[], the
        // catalog, or the deferred-tools block.
        const requested = parseSelectNames(query);
        if (requested && requested.length > 0) {
          const activeNames = pi.getActiveTools();
          const activeSet = new Set(activeNames);
          const alreadyActive: string[] = [];
          for (const name of requested) {
            if (hasToolName(activeSet, name)) {
              alreadyActive.push(name);
              continue;
            }
            const key = canonicalToolKey(name);
            if (key.length === 0) continue;
            const hits = activeNames.filter((activeName) => canonicalToolKey(activeName) === key);
            if (hits.length === 1) alreadyActive.push(name);
          }
          if (alreadyActive.length > 0) {
            return {
              content: [
                {
                  type: "text",
                  text:
                    `${alreadyActive.length} tool(s) already loaded: ${alreadyActive.join(", ")}\n\n` +
                    "These tools are already in your active tool list — call them directly.",
                },
              ],
              details: { query, originalQuery: params.query, matches: [], alreadyActive },
            };
          }
        }

        const available = state.catalog.map((e) => e.name).join(", ");
        return {
          content: [
            {
              type: "text",
              text:
                `No deferred tools matched "${query}".\n\n` +
                (available
                  ? `Available deferred tools: ${available}`
                  : "No tools are currently deferred."),
            },
          ],
          details: { query, originalQuery: params.query, matches: [] },
        };
      }

      // Native paths avoid mutating Pi's active native-tool list after search.
      // Anthropic discovers via appended `tool_reference` blocks. Codex keeps
      // tools[] byte-stable with `defer_loading:true`; the model can call the
      // matched tool directly after the search turn without a schema swap.
      const referenced: Array<{ catalogName: string; referenceName: string }> = [];
      const codexDeferred: string[] = [];
      const newlyActive: string[] = [];
      const current = new Set(pi.getActiveTools());
      const normalizedCurrent = new Set([...current].map(normalizeToolName));
      for (const m of matches) {
        if (state.deferredToolMode !== "none" && m.entry.deferLoading) {
          if (!hasToolName(state.discovered, m.entry.name)) {
            if (state.deferredToolMode === "anthropic_tool_reference") {
              referenced.push({
                catalogName: m.entry.name,
                // Emit pi's bare internal name. The provider tool-name
                // transform is owned entirely by pi-claude-bridge (see note
                // below) so the extension and bridge allowlists can never drift.
                referenceName: m.entry.name,
              });
            } else {
              codexDeferred.push(m.entry.name);
            }
            state.discovered.add(m.entry.name);
            if (state.config.rememberDiscovered) {
              recordDiscovery(pi, m.entry.name);
            }
          }
          continue;
        }

        // Active-tool path: append-only activation for tools that do not use
        // native deferred references.
        if (!hasToolName(normalizedCurrent, m.entry.name)) {
          current.add(m.entry.name);
          normalizedCurrent.add(normalizeToolName(m.entry.name));
          newlyActive.push(m.entry.name);
          state.discovered.add(m.entry.name);
          if (state.config.rememberDiscovered) {
            recordDiscovery(pi, m.entry.name);
          }
        }
      }
      if (newlyActive.length > 0) {
        pi.setActiveTools([...current]);
      }

      const lines = matches.map((m) => `- ${m.entry.name}: ${m.entry.description}`);
      const changed = referenced.length + codexDeferred.length + newlyActive.length;
      const summary =
        changed === matches.length
          ? `Loaded ${changed} deferred tool(s) for this session`
          : changed === 0
            ? `${matches.length} tool(s) already loaded`
            : `Loaded ${changed} new tool(s); ${matches.length - changed} already loaded`;
      const modeNote =
        referenced.length > 0
          ? "Loaded as appended tool_reference message blocks; native tool schemas were not mutated."
          : codexDeferred.length > 0
            ? "Matched tools are already present as stable Codex defer_loading schemas; native tool schemas were not mutated. Call them directly."
            : "Full schemas are now in your tool list. Call them directly.";
      const text = `${summary}:\n\n${lines.join("\n")}\n\n${modeNote}`;

      return {
        content:
          referenced.length > 0
            ? referenced.map(({ referenceName }) => ({ type: "tool_reference" as const, name: referenceName }))
            : [{ type: "text" as const, text }],
        details: {
          query,
          originalQuery: params.query,
          matches: matches.map((m) => m.entry.name),
          newlyActivated: newlyActive,
          referenced: referenced.map(({ catalogName }) => catalogName),
          codexDeferred,
          referenceNames: referenced.map(({ referenceName }) => referenceName),
          mode: state.deferredToolMode,
          summary: text,
        },
      };
    },
  });

  // ─── session_start: catalog build + active-tools enforcement ──────────
  pi.on("session_start", (_event, ctx) => {
    const config = withRuntimeAlwaysActive(loadConfig(), ctx);
    const deferSet = new Set(config.defer);
    const alwaysActiveSet = new Set(config.alwaysActive);
    const previouslyDiscovered = config.rememberDiscovered ? scanDiscoveredTools(ctx) : new Set<string>();

    const next: SessionState = {
      config,
      catalog: buildCatalog(pi, deferSet, alwaysActiveSet, config.deferByDefault),
      model: ctx.model,
      deferredToolMode: getDeferredToolMode(ctx.model),
      discovered: new Set(previouslyDiscovered),
    };
    writeState(ctx, next);

    // CACHE CRITICAL: flip deferred catalog tools that the provider can serve as
    // native `defer_loading` stubs into real deferLoading definitions, ONCE per
    // session (never per-turn). Without this the ~27 deferred-but-non-deferLoading
    // tools (computer_use, Workflow, AskUserQuestion, …) only live in the
    // <deferred-tools> text block, and discovery adds them to tools[] as FULL
    // schemas via setActiveTools — mutating the cached prefix and bursting the
    // prompt cache. After the override they are stable defer_loading stubs from
    // turn 1, and discovery appends a tool_reference block in the message tail
    // (anthropic_tool_reference) / stays byte-stable (codex) instead.
    applyNativeDeferralOverride(pi, next);

    applyDeferral(pi, next);
  });

  // Release the per-session slot so the map doesn't grow without bound.
  pi.on("session_shutdown", (_event, ctx) => {
    writeState(ctx, null);
  });

  // ─── before_agent_start: enforce deferral + inject hints ──────────────
  pi.on("before_agent_start", (event, ctx) => {
    const s = readState(ctx);
    if (!s) return undefined;
    s.config = withRuntimeAlwaysActive(s.config, ctx);
    refreshModelState(s, ctx);

    // CACHE CRITICAL: this hook rewrites the system prompt and active tool
    // list at the last safe point before the provider request. Keep it
    // deterministic and idempotent; prompt/schema churn here is a direct
    // cache-prefix bust.
    //
    // Some extensions register/refresh tools during startup and can re-expand
    // the active set after our session_start handler. Enforce the catalog at
    // the last safe point before the provider request, then render from Pi's
    // rebuilt prompt so context accounting and provider schemas agree.
    applyDeferral(pi, s);

    const currentPrompt = typeof ctx?.getSystemPrompt === "function" ? ctx.getSystemPrompt() : event.systemPrompt;

    if (!s.config.showDeferredHints) return { systemPrompt: currentPrompt };
    if (s.catalog.length === 0) return { systemPrompt: currentPrompt };

    // Filter out eager active schemas only. Provider-native deferred tools may
    // appear in tools[] as `defer_loading: true`; they still need the stable
    // text index so the model can discover them without paying full schema cost.
    const activeNow = getEagerActiveCapabilities(pi);
    const stillDeferred = s.catalog.filter(
      (e) => !hasToolName(s.discovered, e.name) && !activeNow.has(normalizeToolName(e.name)),
    );
    if (stillDeferred.length === 0) return { systemPrompt: currentPrompt };

    const block = renderDeferredBlock(stillDeferred);
    const updated = injectOrReplaceBlock(currentPrompt, block);
    if (updated === event.systemPrompt) return undefined;
    return { systemPrompt: updated };
  });
}

function withRuntimeAlwaysActive(config: ToolSearchConfig, ctx: unknown): ToolSearchConfig {
  if (!hasNonCompletePiGoal(ctx)) return config;

  // CACHE CRITICAL: pi-goal control tools are dynamic by session state. Keep
  // them out of ordinary sessions, but make them first-turn active when a
  // non-complete goal already exists so goal continuations do not churn the
  // tool schema list every turn.
  const alwaysActive = [...config.alwaysActive];
  for (const toolName of PI_GOAL_ACTIVE_TOOLS) {
    if (!alwaysActive.includes(toolName)) alwaysActive.push(toolName);
  }
  return { ...config, alwaysActive };
}

function hasNonCompletePiGoal(ctx: unknown): boolean {
  const entries = getBranchEntries(ctx);
  let status: string | null = null;

  for (const entry of entries) {
    if (!entry || typeof entry !== "object") continue;
    const candidate = entry as { type?: unknown; customType?: unknown; data?: unknown };
    if (candidate.type !== "custom" || candidate.customType !== PI_GOAL_CUSTOM_ENTRY_TYPE) continue;
    const data = candidate.data;
    if (!data || typeof data !== "object") continue;
    const goalEntry = data as { version?: unknown; kind?: unknown; goal?: unknown };
    if (goalEntry.version !== 1) continue;
    if (goalEntry.kind === "clear") {
      status = null;
      continue;
    }
    if (goalEntry.kind !== "set" || !goalEntry.goal || typeof goalEntry.goal !== "object") continue;
    const goal = goalEntry.goal as { status?: unknown };
    status = typeof goal.status === "string" ? goal.status : null;
  }

  return status !== null && status !== "complete";
}

function getBranchEntries(ctx: unknown): unknown[] {
  if (!ctx || typeof ctx !== "object") return [];
  const sessionManager = (ctx as { sessionManager?: unknown }).sessionManager;
  if (!sessionManager || typeof sessionManager !== "object") return [];
  const getBranch = (sessionManager as { getBranch?: unknown }).getBranch;
  if (typeof getBranch !== "function") return [];
  const entries = getBranch.call(sessionManager);
  return Array.isArray(entries) ? entries : [];
}

/**
 * `pi.tools` widened with the optional post-registration deferral seam so this
 * extension compiles against both older cores (method absent) and newer cores
 * (method present). Runtime presence is checked before use.
 */
type DeferralCapableToolRegistry = ExtensionAPI["tools"] & {
  setDeferredOverrides?: (names: string[]) => void;
};

/**
 * Force every deferred catalog tool that the provider can serve as a native
 * `defer_loading` stub to be a real `deferLoading` definition, via the core
 * `pi.tools.setDeferredOverrides` seam.
 *
 * CACHE CRITICAL + run ONCE per session (session_start only). The core method is
 * idempotent, but this must never run per-turn. After the override the catalog's
 * `deferLoading` reflects reality, so `computeActiveTools` keeps these tools
 * active as stubs and the execute() tool_reference / codex defer paths take over
 * from the cache-bursting full-schema activation path.
 */
function applyNativeDeferralOverride(pi: ExtensionAPI, state: SessionState): void {
  // Only providers that serve native deferred schemas benefit. In "none" mode
  // discovery falls back to full-schema activation regardless, and flipping
  // deferLoading would not change serialization — leave those sessions untouched.
  if (state.deferredToolMode === "none") return;

  // Defensive access: older pi cores have no `setDeferredOverrides` on the tool
  // registry view. Optional-chain so the extension keeps working (the deferred
  // tools just stay text-only there) instead of crashing or failing to compile.
  const toolsView = pi.tools as DeferralCapableToolRegistry;
  const setDeferredOverrides = toolsView.setDeferredOverrides;
  if (typeof setDeferredOverrides !== "function") return;

  // Catalog already excludes alwaysActive tools; pick those not yet deferLoading.
  const toOverride = state.catalog.filter((entry) => !entry.deferLoading).map((entry) => entry.name);
  if (toOverride.length === 0) return;

  setDeferredOverrides.call(pi.tools, toOverride);

  // Rebuild the catalog from the now-updated definitions and verify the
  // invariant: every deferred catalog tool should now be a defer_loading stub.
  // Anything still eager (e.g. a tool the core refused to override because it is
  // alwaysLoad) would still burst the cache on discovery — surface it once.
  const deferSet = new Set(state.config.defer);
  const alwaysActiveSet = new Set(state.config.alwaysActive);
  state.catalog = buildCatalog(pi, deferSet, alwaysActiveSet, state.config.deferByDefault);
  const stragglers = state.catalog.filter((entry) => !entry.deferLoading).map((entry) => entry.name);
  if (stragglers.length > 0) {
    console.warn(
      `[tool-search] ${stragglers.length} deferred tool(s) remain non-deferLoading in a native-deferred ` +
        `session and may burst the prompt cache on discovery: ${stragglers.join(", ")}`,
    );
  }
}

function applyDeferral(pi: ExtensionAPI, state: SessionState): void {
  // CACHE CRITICAL: tools[] is a provider request parameter, and adding/removing
  // schemas mid-session changes the cached prefix. Only mutate when the
  // normalized catalog/discovery state actually changes.
  const deferSet = new Set(state.config.defer);
  const alwaysActiveSet = new Set(state.config.alwaysActive);
  const catalog = buildCatalog(pi, deferSet, alwaysActiveSet, state.config.deferByDefault);
  state.catalog = catalog;
  const finalActive = computeActiveTools(
    pi,
    deferSet,
    alwaysActiveSet,
    state.discovered,
    state.config.deferByDefault,
    state.deferredToolMode,
  );
  const current = pi.getActiveTools();
  if (sameNames(current, finalActive)) return;
  pi.setActiveTools(finalActive);
}

function getEagerActiveCapabilities(pi: ExtensionAPI): Set<string> {
  const definitionsByCapability = new Map<string, { name: string; deferLoading?: boolean }>();
  for (const tool of pi.tools.definitions()) {
    if (!tool || typeof tool.name !== "string") continue;
    definitionsByCapability.set(normalizeToolName(tool.name), tool);
  }

  const eager = new Set<string>();
  for (const name of pi.getActiveTools()) {
    if (typeof name !== "string") continue;
    const capability = normalizeToolName(name);
    const definition = definitionsByCapability.get(capability);
    if (definition?.deferLoading === true) continue;
    eager.add(capability);
  }

  const activeDefinitions = pi.tools.active() as unknown[];
  for (const tool of activeDefinitions) {
    if (!tool || typeof tool !== "object") continue;
    const definitionLike = tool as { name?: unknown; deferLoading?: unknown };
    if (typeof definitionLike.name !== "string") continue;
    const capability = normalizeToolName(definitionLike.name);
    const definition = definitionsByCapability.get(capability);
    if (definitionLike.deferLoading === true || definition?.deferLoading === true) continue;
    eager.add(capability);
  }
  return eager;
}

function sameNames(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  return a.every((name, index) => name === b[index]);
}

function refreshModelState(state: SessionState, ctx: unknown): void {
  if (!ctx || typeof ctx !== "object" || !("model" in ctx)) return;
  const model = (ctx as { model?: unknown }).model;
  const mode = getDeferredToolMode(model);
  if (state.model === model && state.deferredToolMode === mode) return;
  state.model = model;
  state.deferredToolMode = mode;
}

function rewriteProviderSpecificToolQuery(query: string, state: SessionState): string {
  const requested = parseSelectNames(query);
  if (!requested || requested.length === 0) return query;

  const names = requested.map((name) => rewriteProviderSpecificToolName(name, state));
  if (names.every((name, index) => name === requested[index])) return query;
  return `select:${names.join(",")}`;
}

// Codex exposes provider-specific web tools through pi-codex-conversion under
// dotted names (`web.run` for search, `web.fetch` for the local Codex-only
// fetch). The Anthropic/Claude marker tools (`web_search`, `web_fetch`)
// otherwise canonical-match these `WebSearch`/`WebFetch` selections and leave
// the real Codex tools undiscovered. Under Codex deferral, redirect each
// canonical key to its Codex tool — but only when that tool is actually in the
// catalog, so Claude sessions keep selecting the Claude-native tools.
const CODEX_TOOL_ALIASES: Readonly<Record<string, string>> = {
  "search web": "web.run",
  "fetch web": "web.fetch",
};

function rewriteProviderSpecificToolName(name: string, state: SessionState): string {
  if (state.deferredToolMode !== "openai_codex_defer_loading") return name;
  const target = CODEX_TOOL_ALIASES[canonicalToolKey(name)];
  if (target && state.catalog.some((entry) => entry.name === target)) return target;
  return name;
}

function getDeferredToolMode(model: unknown): DeferredToolMode {
  if (!model || typeof model !== "object") return "none";
  const candidate = model as { api?: unknown; id?: unknown; compat?: unknown };
  if (candidate.api === "openai-codex-responses") return "openai_codex_defer_loading";
  if (candidate.api !== "anthropic-messages") return "none";
  if (typeof candidate.id === "string" && candidate.id.toLowerCase().includes("haiku")) return "none";
  const compat = candidate.compat as { supportsDeferredTools?: unknown } | undefined;
  return compat?.supportsDeferredTools === false ? "none" : "anthropic_tool_reference";
}

// NOTE: the provider tool-name transform (mcp__ prefixing for the Anthropic
// OAuth wire format) lives entirely in pi-claude-bridge
// (prefixToolName / rewriteToolReferenceNames in pi-claude-bridge/index.js).
// This extension emits pi's bare internal names for tool_reference blocks; the
// bridge prefixes them on the wire and strips them on the response. Keeping the
// allowlist in one place (the bridge) is what prevents the drift that caused
// the historical "TodoWrite not found" 400.

/**
 * Build the `<deferred-tools>` block. Keep startup discovery broker-first:
 * do not list every deferred name/description in the cached prefix. `tool_search`
 * owns search/listing and returns exact matches as appended tool results or
 * provider-native `tool_reference` blocks.
 */
function renderDeferredBlock(entries: readonly CatalogEntry[]): string {
  const webTools = entries
    .map((entry) => entry.name)
    .filter((name) => name === "web_search" || name === "web_fetch");
  const webHint = webTools.length
    ? `- Native web tools available: ${webTools.join(", ")}. For user requests to search/fetch the web, call tool_search({"query":"select:<ExactName>"}) and then call the discovered tool; do not load web-search/web-fetch skill refs as a substitute.\n`
    : "";
  return `\n\n${DEFERRED_BLOCK_OPEN}\n- ${entries.length} deferred tools available. Use tool_search({"query":"<capability>"}) or tool_search({"query":"select:<ExactName>"}) to discover/load exact tools on demand.\n${webHint}${DEFERRED_BLOCK_CLOSE}`;
}

function truncate(s: string, max: number): string {
  if (s.length <= max) return s;
  return s.slice(0, max - 1) + "…";
}

/**
 * Insert (or replace) the deferred-tools block in the system prompt.
 *
 * Idempotent: if the block already exists, swap its contents in place.
 * Otherwise append at the end. Either way the cache breakpoint is at most
 * one place changed per turn.
 */
function injectOrReplaceBlock(prompt: string, block: string): string {
  const openIdx = prompt.indexOf(DEFERRED_BLOCK_OPEN);
  if (openIdx < 0) {
    return prompt + block;
  }
  const closeIdx = prompt.indexOf(DEFERRED_BLOCK_CLOSE, openIdx);
  if (closeIdx < 0) {
    // Malformed prior block — just append a new one. Old fragment becomes orphan text.
    return prompt + block;
  }
  // Replace the whole block including the leading "\n\n" we inserted before it.
  // Walk back over up to 2 leading newlines to avoid blank-line buildup.
  let start = openIdx;
  if (start >= 2 && prompt.slice(start - 2, start) === "\n\n") start -= 2;
  return prompt.slice(0, start) + block + prompt.slice(closeIdx + DEFERRED_BLOCK_CLOSE.length);
}

