import fs from "node:fs";
const log = fs.readFileSync(process.argv[1], "utf8").split("\n");
// request lines: [ts] request=ID model msgs=N tools=N ... piSessionId=019ea645...
// cache lines: [CACHE] request=ID read=R write=W (1h=.. 5m=..) input=I
const reqRe = /^\[([^\]]+)\] request=([0-9a-f-]+) (\S+) msgs=(\d+) tools=(\d+).*?piSessionId=([0-9a-f-]+)/;
const cacheRe = /^\[CACHE\] request=([0-9a-f-]+) read=(\d+) write=(\d+) \(1h=(\d+) 5m=(\d+)\) input=(\d+)/;
const reqs = new Map(); // id -> {ts,model,msgs,tools,sid}
const order = [];
for (const l of log) {
  let m = reqRe.exec(l);
  if (m) { reqs.set(m[2], {ts:m[1],model:m[3],msgs:+m[4],tools:+m[5],sid:m[6]}); order.push(m[2]); continue; }
  m = cacheRe.exec(l);
  if (m && reqs.has(m[1])) { const r = reqs.get(m[1]); r.read=+m[2]; r.write=+m[3]; r.input=+m[6]; }
}
const want = "019ea645";
const rows = order.filter(id => reqs.get(id)?.sid?.startsWith(want)).map(id => ({id, ...reqs.get(id)}));
const out = ["ts\ttools\tmsgs\tread\twrite\tinput\ttotal\trequest"];
for (const r of rows) {
  const total = (r.read||0)+(r.write||0)+(r.input||0);
  out.push(`${r.ts}\t${r.tools}\t${r.msgs}\t${r.read??"-"}\t${r.write??"-"}\t${r.input??"-"}\t${total}\t${r.id.slice(0,8)}`);
}
fs.writeFileSync("/tmp/burst-bridge-timeline.tsv", out.join("\n"));
console.log(`session 019ea645: ${rows.length} requests`);
' "$LOG"

