1	/**
2	 * active-memory v1 — bounded-blocking recall sub-agent.
3	 *
4	 * Called from `src/extension.ts` as a per-turn prefetch. Opt in via
5	 * `~/.dream-memory/recall.toml` `enabled = true` or `DREAM_ACTIVE_RECALL=1`.
6	 * `DREAM_ACTIVE_RECALL=0` remains the kill switch.
7	 * Modelled on OpenClaw's
8	 * memory tools (extensions/memory-core/src/tools.ts) but we deliberately
9	 * narrow the surface:
10	 *
11	 *   - The LLM does not actually invoke `qmd query` as a tool. Instead we
12	 *     pre-fetch top-K hits with the user's prompt as the query, hand
13	 *     their metadata/snippets to a haiku-class selector, and ask it to
14	 *     return selected permalinks only. We inject the original selected
15	 *     snippets, not haiku-written memory prose. One LLM call per turn,
16	 *     bounded by recall.toml. The "tools: only qmd query (read-only)"
17	 *     spec is satisfied by us doing the query — the LLM never gets a tool
18	 *     that can do anything else.
19	 *
20	 *   - Returns a custom-message payload, but extension.ts delivers it only
21	 *     through the `context` hook tail, never from `before_agent_start` or
22	 *     `systemPrompt`. (Prompt-cache safety — see
23	 *     references/explore-pi-qmd-openclaw.md §A4.)
24	 *
25	 *   - Budgets, circuit breaker, model alias all come from
26	 *     `~/.dream-memory/recall.toml`; defaults are baked in so the file
27	 *     is purely overrides.
28	 *
29	 * Returned shape matches `BeforeAgentStartEventResult.message`:
30	 *   { customType: "dream-memory.active-recall", content: string,
31	 *     display: false, details?: { hits, latencyMs, model } }
32	 *
33	 * On any failure (auth, qmd, LLM, abort, breaker open) we return
34	 * `undefined` and do nothing. Per locked decision: active-memory must
35	 * NEVER block the user's turn.
36	 */
37	
38	import { mkdir, readFile, rename, stat, writeFile } from "node:fs/promises";
39	import { existsSync } from "node:fs";
40	import { homedir } from "node:os";
41	import { dirname, join } from "node:path";
42	import { randomBytes } from "node:crypto";
43	
44	import {
45		callPiModel,
46		createPiRegistry,
47		pickModel,
48		PiModelAbortError,
49		PiModelAuthError,
50		PiModelError,
51		type PiCompleteFn,
52	} from "./lib/pi-model.ts";
53	// Lazy-load telemetry to avoid pulling opik → ai-sdk → js-tiktoken at boot.
54	let _amTelModule: Promise<typeof import("./telemetry.ts")> | null = null;
55	function getAMTel() {
56		if (!_amTelModule) _amTelModule = import("./telemetry.ts");
57		return _amTelModule;
58	}
59	import { appendEvent, resolveProjectSlug, searchMemory, searchMemoryQmd, type SearchHit } from "./store.ts";
60	import { decayWeightForPath, loadDecayConfig, openPiMemorySidecar } from "./memory-decay.ts";
61	import { randomUUID } from "node:crypto";
62	
63	
64	/**
65	 * Active-recall collections: pi-memory (live MEMORY.md, daily logs),
66	 * scars (durable failure patterns), and changes (dated history of
67	 * agent-scripts changes). Federating across all three on every prompt
68	 * gives the haiku-curator full context without forcing the user to
69	 * remember which kind of note they wrote.
70	 *
71	 * NOT included: `dream-memory-profile` and `dream-memory-project`. Those are
72	 * already injected deterministically every session — profile/** via the
73	 * systemPrompt:build base filter, project/<slug>/** via the SessionStart tail.
74	 * Recalling them here double-bills the same tokens and (because recall hits
75	 * land in the volatile region) hurts cross-session cache. Recall should surface
76	 * memory that is NOT otherwise in the prompt.
77	 */
78	export const DEFAULT_ACTIVE_RECALL_COLLECTIONS: readonly string[] = [
79		"pi-memory",
80		"scars",
81		"changes",
82	] as const;
83	
84	/** @deprecated single-collection accessor; use {@link activeRecallCollections}. */
85	export const DEFAULT_ACTIVE_RECALL_COLLECTION: string = DEFAULT_ACTIVE_RECALL_COLLECTIONS[0] ?? "pi-memory";
86	
87	/**
88	 * Resolve the collection list for active recall.
89	 *
90	 * Override priority:
91	 *   1. `DREAM_ACTIVE_RECALL_COLLECTIONS` (comma-separated list, plural)
92	 *   2. `DREAM_ACTIVE_RECALL_COLLECTION` (single, back-compat)
93	 *   3. `PI_MEMORY_QMD_COLLECTION` (legacy, single)
94	 *   4. {@link DEFAULT_ACTIVE_RECALL_COLLECTIONS}
95	 */
96	/**
97	 * Generic multi-topic decomposition for two-pass retrieval. Splits the prompt
98	 * on conjunctions (" and ", " plus ", " & ", "/") when the prompt has ≥6
99	 * words and ≥2 sub-parts of ≥2 words each. Returns the sub-parts to be used
100	 * as additional QMD sub-queries (excluding the full query, which the caller
101	 * still issues). Returns [] for single-topic prompts.
102	 *
103	 * Heuristic only — never overfits to specific test cases.
104	 */
105	export function decomposeMultiTopic(prompt: string): string[] {
106		const trimmed = prompt.trim();
107		if (trimmed.split(/\s+/).length < 6) return [];
108		const parts = trimmed
109			.split(/\s+and\s+|\s+plus\s+|\s+&\s+|\s*\/\s*|\s*,\s*/i)
110			.map((p) => p.replace(/[?.!]+$/, "").trim())
111			.filter((p) => p.split(/\s+/).length >= 2);
112		if (parts.length < 2) return [];
113		return parts.slice(0, 4);
114	}
115	
116	/**
117	 * Build anchored follow-up queries for QMD. Smoke prompts and user asks often
118	 * contain policy prose plus exact file/repo tokens; BM25 can miss the useful
119	 * docs when everything is searched as one long sentence. Keep the full query,
120	 * then add short evidence-shaped anchors.
121	 */
122	export function buildActiveRecallExtraQueries(prompt: string): string[] {
123		const queries: string[] = [];
124		const add = (q: string | undefined) => {
125			const cleaned = q?.replace(/\s+/g, " ").replace(/[?.!]+$/, "").trim();
126			if (!cleaned || cleaned.length < 3) return;
127			if (cleaned === prompt.trim()) return;
128			if (!queries.includes(cleaned)) queries.push(cleaned);
129		};
130	
131		const question = /\bQuestion:\s*([\s\S]*?)(?:\n\s*\n|\bExpected\b|\bAnswer\b|$)/i.exec(prompt)?.[1];
132		const corePrompt = question ?? prompt;
133		add(question);
134		add(corePrompt
135			.replace(/\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|stored|local|the|is|are|do|does|can|you|please)\b/gi, " ")
136			.replace(/\bsrc\b/gi, "src source")
137		);
138		for (const q of decomposeMultiTopic(corePrompt)) add(q);
139	
140		for (const m of prompt.matchAll(/`([^`]+)`/g)) add(m[1]);
141		for (const m of prompt.matchAll(/(?:^|\s)((?:[\w.-]+\/)+[\w.-]+\.md)\b/g)) add(m[1]);
142		for (const m of prompt.matchAll(/\b[a-z0-9]+(?:-[a-z0-9]+){2,}\b/gi)) add(m[0]);
143	
144		return queries.slice(0, 12);
145	}
146	
147	export function activeRecallCollections(): string[] {
148		const plural = process.env.DREAM_ACTIVE_RECALL_COLLECTIONS;
149		if (plural) {
150			const list = plural.split(",").map((s) => s.trim()).filter(Boolean);
151			if (list.length > 0) return list;
152		}
153		const single =
154			process.env.DREAM_ACTIVE_RECALL_COLLECTION ??
155			process.env.PI_MEMORY_QMD_COLLECTION;
156		if (single) return [single];
157		return [...DEFAULT_ACTIVE_RECALL_COLLECTIONS];
158	}
159	
160	export type RecallCollectionRoute = {
161		collections: string[];
162		/** Collections that should be guaranteed representation before global memory hits. */
163		primaryCollections?: string[];
164		/** Global memory collections appended after primary project/workspace hits. */
165		globalCollections?: string[];
166		/** Force BM25-only QMD for collections not covered by the vector sidecar. */
167		qmdMode?: "search" | "query";
168		reason: "explicit-env" | "workspace" | "project-docs" | "default-memory";
169	};
170	
171	function hasExplicitRecallCollectionsEnv(): boolean {
172		return Boolean(process.env.DREAM_ACTIVE_RECALL_COLLECTIONS || process.env.DREAM_ACTIVE_RECALL_COLLECTION || process.env.PI_MEMORY_QMD_COLLECTION);
173	}
174	
175	function looksLikeWorkspaceLookup(prompt: string): boolean {
176		return /\b(where|which|what|find|locate|path|repo|repository|project|workspace|checkout|source|src|directory|folder)\b/i.test(prompt);
177	}
178	
179	function looksLikeProjectDocsLookup(prompt: string): boolean {
180		return /\b(doc|docs|documentation|research|spec|prd|plan|proposal|design|runbook|architecture|decision|adr|notes?)\b/i.test(prompt);
181	}
182	
183	function projectDocsCollectionForSlug(slug: string | undefined): string | undefined {
184		if (!slug || slug === "unknown") return undefined;
185		return `project-docs-${slug}`;
186	}
187	
188	export function resolveActiveRecallRoute(prompt: string, projectSlug?: string): RecallCollectionRoute {
189		if (hasExplicitRecallCollectionsEnv()) {
190			return { collections: activeRecallCollections(), reason: "explicit-env" };
191		}
192		const projectDocs = projectDocsCollectionForSlug(projectSlug);
193		const globalMemory = activeRecallCollections();
194		if (looksLikeWorkspaceLookup(prompt)) {
195			const primaryCollections = ["workspace-index", "workspace-info", ...(projectDocs ? [projectDocs] : [])];
196			return {
197				collections: [...primaryCollections, ...globalMemory],
198				primaryCollections,
199				globalCollections: globalMemory,
200				qmdMode: "search",
201				reason: "workspace",
202			};
203		}
204		if (projectDocs && looksLikeProjectDocsLookup(prompt)) {
205			const primaryCollections = [projectDocs];
206			return {
207				collections: [...primaryCollections, ...globalMemory],
208				primaryCollections,
209				globalCollections: globalMemory,
210				qmdMode: "search",
211				reason: "project-docs",
212			};
213		}
214		return { collections: activeRecallCollections(), reason: "default-memory" };
215	}
216	
217	/** @deprecated returns only the first collection; use {@link activeRecallCollections}. */
218	export function activeRecallCollection(): string {
219		return activeRecallCollections()[0] ?? DEFAULT_ACTIVE_RECALL_COLLECTION;
220	}
221	
222	// Local subset of ModelRegistry shape we actually need. createPiRegistry
223	// returns the full ModelRegistry but we only call getAvailable / find /
224	// getApiKeyAndHeaders — narrowing the type avoids the full PiModelRegistryLike
225	// surface (getAll / hasConfiguredAuth).
226	interface RecallRegistry {
227		getAvailable(): Array<{ id: string; provider: string; api: string; [k: string]: unknown }>;
228		find(provider: string, modelId: string):
229			| { id: string; provider: string; api: string; [k: string]: unknown }
230			| undefined;
231		getApiKeyAndHeaders(model: { id: string; provider: string; api: string }): Promise<{
232			ok: boolean;
233			apiKey?: string;
234			headers?: Record<string, string>;
235			error?: string;
236		}>;
237	}
238	
239	// ---------------------------------------------------------------------------
240	// Config
241	
242	export interface RecallConfig {
243		enabled: boolean;
244		model_alias: "fast-class" | "haiku-class" | "sonnet-class";
245		budget_ms: number;
246		ceiling_ms: number;
247		breaker_threshold: number;
248		breaker_cooldown_ms: number;
249		max_hits: number;
250		model_override: string | undefined; // e.g. "anthropic/claude-haiku-4-5"
251		/** When false, memory components are injected silently (display:false). Default true. */
252		show_ui: boolean;
253		// --- autoresearch knobs (Phase 0d) ---
254		/** QMD recall mode. "search" = BM25 only; "query" = external hybrid HTTP path. */
255		qmd_mode: "search" | "query";
256		/** Prepend N prior assistant turns to the QMD query string (resolves ambiguous follow-ups). */
257		context_turns: number;
258		/** Recall system-prompt variant for the haiku curator. */
259		prompt_variant: "compact" | "terse" | "expanded" | "cot";
260		/** Filter QMD hits below this score before passing to the haiku. 0 = disabled. */
261		min_score: number;
262		/** Candidate pool size for external hybrid rerank. */
263		candidate_limit: number;
264		/** If the highest-scoring hit is below this threshold, return NONE immediately without calling haiku.
265		 *  Decouples ambiguous-NONE detection (deterministic) from specific-hit synthesis (haiku).
266		 *  0 = disabled. Env: RECALL_AUTO_NONE_THRESHOLD. */
267		auto_none_threshold: number;
268		/** If the trimmed prompt is shorter than this many characters, return NONE without QMD call.
269		 *  Short prompts (acknowledgments, single words) rarely benefit from memory recall.
270		 *  0 = disabled. Env: RECALL_MIN_PROMPT_LENGTH. */
271		min_prompt_length: number;
272		/** QMD HTTP daemon port (set via DREAM_QMD_HTTP_PORT or recall.toml).
273		 *  query mode requires this; 0 is only for explicit BM25 subprocess search. */
274		qmd_http_port: number;
275	}
