483	// Circuit breaker — persistent state at ~/.dream-memory/recall-breaker.json.
484	
485	export interface BreakerState {
486		consecutive_timeouts: number;
487		opened_at_ms: number | null;
488	}
489	
490	export const FRESH_BREAKER: BreakerState = { consecutive_timeouts: 0, opened_at_ms: null };
491	
492	export async function readBreakerState(): Promise<BreakerState> {
493		const p = recallBreakerPath();
494		if (!existsSync(p)) return { ...FRESH_BREAKER };
495		try {
496			const raw = JSON.parse(await readFile(p, "utf8")) as Partial<BreakerState>;
497			return {
498				consecutive_timeouts: Number(raw.consecutive_timeouts ?? 0),
499				opened_at_ms: raw.opened_at_ms == null ? null : Number(raw.opened_at_ms),
500			};
501		} catch {
502			return { ...FRESH_BREAKER };
503		}
504	}
505	
506	async function writeBreakerStateAtomic(state: BreakerState): Promise<void> {
507		const p = recallBreakerPath();
508		await mkdir(dirname(p), { recursive: true });
509		const tmp = `${p}.${randomBytes(6).toString("hex")}.tmp`;
510		await writeFile(tmp, JSON.stringify(state, null, 2));
511		await rename(tmp, p);
512	}
513	
514	/** Returns true if breaker is OPEN (call should be skipped). */
515	export function isBreakerOpen(state: BreakerState, cfg: RecallConfig, nowMs: number): boolean {
516		if (state.opened_at_ms === null) return false;
517		return nowMs - state.opened_at_ms < cfg.breaker_cooldown_ms;
518	}
519	
520	export async function recordBreakerOutcome(
521		state: BreakerState,
522		cfg: RecallConfig,
523		outcome: "success" | "timeout",
524		nowMs: number,
525	): Promise<BreakerState> {
526		let next: BreakerState;
527		if (outcome === "success") {
528			// Reset on any non-timeout. Even if the breaker is technically still
529			// open by clock, a successful call is the cleanest signal that
530			// upstream is healthy.
531			next = { consecutive_timeouts: 0, opened_at_ms: null };
532		} else {
533			const ct = state.consecutive_timeouts + 1;
534			const opened =
535				ct >= cfg.breaker_threshold
536					? state.opened_at_ms ?? nowMs
537					: state.opened_at_ms;
538			next = { consecutive_timeouts: ct, opened_at_ms: opened };
539		}
540		await writeBreakerStateAtomic(next);
541		return next;
542	}
