613	const LEAN_RECALL_SYSTEM_PROMPT = `You select memory hits for the current user prompt.
614	Return JSON only: {"selected":["permalink"]}.
615	Select up to 5 permalinks that clearly help answer or execute the prompt.
616	If none clearly help, return {"selected":[]}.
617	No prose, markdown, reasoning, or invented facts.`;
618	
619	const RECALL_PROMPT_VARIANTS: Record<RecallConfig["prompt_variant"], string> = {
620		compact: LEAN_RECALL_SYSTEM_PROMPT,
621		terse: LEAN_RECALL_SYSTEM_PROMPT,
622		expanded: LEAN_RECALL_SYSTEM_PROMPT,
623		cot: LEAN_RECALL_SYSTEM_PROMPT,
624	};
625	
626	const RECALL_SYSTEM_PROMPT = LEAN_RECALL_SYSTEM_PROMPT;
627	
628	/**
629	 * Strip a leading YAML frontmatter block (`---\n...\n---`) from a snippet.
630	 *
631	 * QMD's BM25 chunker treats the frontmatter block as the first searchable
632	 * chunk, so for queries that match a title keyword (e.g. "QMD chosen over
633	 * basic-memory") the highest-scoring snippet is YAML metadata, not prose.
634	 * The active-recall haiku then sees a wall of keys and colons and either
635	 * outputs NONE or hallucinates prose. This strip is a per-snippet defense:
636	 * if the matched chunk leads with frontmatter, drop it and use whatever
637	 * prose follows.
638	 *
639	 * Conservative: only strips when the snippet *starts* with `---` and the
640	 * closing fence is found. Pass-through otherwise. Internal `---` separators
641	 * mid-prose are untouched.
642	 */
643	export function stripFrontmatter(text: string): string {
644		if (!text.startsWith("---")) return text;
645		// Match leading frontmatter: --- (newline) ... (newline) ---
646		const m = /^---\r?\n[\s\S]*?\r?\n---\r?\n?/.exec(text);
647		if (!m) return text;
648		return text.slice(m[0].length).trim();
649	}
650	
651	function buildRecallPrompt(prompt: string, hits: SearchHit[], priorContext?: string): string {
652		const hitsBlock = hits
653			.slice(0, 10)
654			.map((h, i) => {
655				const raw = h.matched_chunk ?? h.content ?? "";
656				const body = stripFrontmatter(raw).slice(0, 500);
657				return `### hit_${i + 1}\npermalink: ${h.permalink}\ntitle: ${h.title}\nscore: ${h.score?.toFixed?.(3) ?? h.score}\nsnippet:\n${body}`;
658			})
659			.join("\n\n");
660		const contextBlock =
661			priorContext && priorContext.trim().length > 0
662				? `\nPrior conversation context (disambiguation only; latest user prompt wins):\n${priorContext.trim()}\n`
663				: "";
664		return `Latest user prompt:
665	${prompt}${contextBlock}
666	
667	Candidate memories:
668	${hitsBlock}
669	
670	Selection rules:
671	- Another model will answer the user; do not answer the user.
672	- Select a memory only if it clearly helps with the latest user prompt.
673	- Prefer NONE/empty selection for weak, broad, speculative, or merely topical matches.
674	- If the user asks to ignore memory, select nothing.
675	- Treat old code/path claims as context only; the answering model must verify current files.
676	
677	Return JSON only: {"selected":["permalink"]}. Use an empty array when nothing is clearly useful.`;
678	}
679	
680	function stripJsonFence(text: string): string {
681		return text
682			.trim()
683			.replace(/^```(?:json)?\s*/i, "")
684			.replace(/\s*```$/, "")
685			.trim();
686	}
687	
688	function normaliseSelectedPermalink(value: string): string {
689		return value
690			.trim()
691			.replace(/^qmd:\/\/[^/]+\//, "")
692			.replace(/\.md$/, "");
693	}
694	
695	export function parseSelectedPermalinks(text: string, validPermalinks: readonly string[]): string[] {
696		const valid = new Set(validPermalinks);
697		let parsed: unknown;
698		try {
699			parsed = JSON.parse(stripJsonFence(text));
700		} catch {
701			return [];
702		}
703		const raw = Array.isArray(parsed)
704			? parsed
705			: parsed && typeof parsed === "object"
706				? (parsed as { selected?: unknown; selected_memories?: unknown; permalinks?: unknown }).selected
707					?? (parsed as { selected_memories?: unknown }).selected_memories
708					?? (parsed as { permalinks?: unknown }).permalinks
709				: undefined;
710		if (!Array.isArray(raw)) return [];
711		const selected: string[] = [];
712		for (const item of raw) {
713			if (typeof item !== "string") continue;
714			const permalink = normaliseSelectedPermalink(item);
715			if (!valid.has(permalink) || selected.includes(permalink)) continue;
716			selected.push(permalink);
717			if (selected.length >= 5) break;
718		}
719		return selected;
720	}
721	
722	function selectedHitsFromText(text: string, hits: SearchHit[]): SearchHit[] {
723		const byPermalink = new Map(hits.map((h) => [h.permalink, h]));
724		return parseSelectedPermalinks(text, hits.map((h) => h.permalink))
725			.map((permalink) => byPermalink.get(permalink))
726			.filter((h): h is SearchHit => h !== undefined);
727	}
