729	function isPrimaryLookupHit(hit: SearchHit): boolean {
730		const key = `${hit.permalink}\n${hit.file_path ?? ""}`;
731		if (/\b(memory|profile|project|inbox|dream-memory-profile|dream-memory-project|scars|changes)\//.test(key)) return false;
732		return /(^|\n)(projects|workspace-info\/|docs\/|[a-z0-9._-]+)(\.md)?(\n|$)/i.test(key);
733	}
