852	export function isLikelyRecallEntityPrompt(input: string): boolean {
853		const prompt = input.trim();
854		if (prompt.length < 6 || prompt.length > 80) return false;
855		const tokens = prompt.split(/\s+/);
856		if (tokens.length > 3) return false;
857		return tokens.every((token) => {
858			if (isTrivialRecallPrompt(token)) return false;
859			return /^[a-z0-9][a-z0-9._-]{5,}$/i.test(token);
860		});
