// Config

export interface RecallConfig {
	enabled: boolean;
	model_alias: "fast-class" | "haiku-class" | "sonnet-class";
	budget_ms: number;
	ceiling_ms: number;
	breaker_threshold: number;
	breaker_cooldown_ms: number;
	max_hits: number;
	model_override: string | undefined; // e.g. "anthropic/claude-haiku-4-5"
	/** When false, memory components are injected silently (display:false). Default true. */
	show_ui: boolean;
	// --- autoresearch knobs (Phase 0d) ---
	/** QMD recall mode. "search" = BM25 only; "query" = external hybrid HTTP path. */
	qmd_mode: "search" | "query";
	/** Prepend N prior assistant turns to the QMD query string (resolves ambiguous follow-ups). */
	context_turns: number;
	/** Recall system-prompt variant for the haiku curator. */
	prompt_variant: "compact" | "terse" | "expanded" | "cot";
	/** Filter QMD hits below this score before passing to the haiku. 0 = disabled. */
	min_score: number;
	/** Candidate pool size for external hybrid rerank. */
	candidate_limit: number;
	/** If the highest-scoring hit is below this threshold, return NONE immediately without calling haiku.
	 *  Decouples ambiguous-NONE detection (deterministic) from specific-hit synthesis (haiku).
	 *  0 = disabled. Env: RECALL_AUTO_NONE_THRESHOLD. */
	auto_none_threshold: number;
	/** If the trimmed prompt is shorter than this many characters, return NONE without QMD call.
	 *  Short prompts (acknowledgments, single words) rarely benefit from memory recall.
	 *  0 = disabled. Env: RECALL_MIN_PROMPT_LENGTH. */
	min_prompt_length: number;
	/** QMD HTTP daemon port (set via DREAM_QMD_HTTP_PORT or recall.toml).
	 *  query mode requires this; 0 is only for explicit BM25 subprocess search. */
	qmd_http_port: number;
}

// Active recall stays OFF by default, but is opt-in again now that extension.ts
// delivers settled recall through the context hook tail and strips stale
// active-recall custom messages from provider context.
export const DEFAULT_RECALL_CONFIG: RecallConfig = {
	enabled: false,
	model_alias: "fast-class",
	budget_ms: 9_000,
	ceiling_ms: 15_000,
	breaker_threshold: 3,
	breaker_cooldown_ms: 60_000,
	max_hits: 5,
	model_override: undefined,
	show_ui: true,
	// Agents ask for recall through query, but query is our external hybrid HTTP path.
	qmd_mode: "query",
	context_turns: 1,
	prompt_variant: "terse",
	min_score: 0,
	candidate_limit: 80,
	auto_none_threshold: 0.4,
