	qmd_http_port: 8181,
};

export function recallStateRoot(): string {
	return process.env.DREAM_EVENTS_HOME ?? join(homedir(), ".dream-memory");
}

export function recallConfigPath(): string {
	return join(recallStateRoot(), "recall.toml");
}

export function recallBreakerPath(): string {
	return join(recallStateRoot(), "recall-breaker.json");
}

/**
 * Tiny hand-rolled TOML reader. We only need flat key=value pairs in this
 * file — no sections, no arrays, no inline tables. Buying a TOML dep for
 * this single config is overkill; if the format grows, swap in `@iarna/toml`.
 */
function parseFlatToml(src: string): Record<string, string> {
	const out: Record<string, string> = {};
	for (const raw of src.split(/\r?\n/)) {
		const line = raw.trim();
		if (!line || line.startsWith("#")) continue;
		if (line.startsWith("[")) continue; // section headers ignored
		const eq = line.indexOf("=");
		if (eq < 0) continue;
		const key = line.slice(0, eq).trim();
		let val = line.slice(eq + 1).trim();
		// Strip inline comment first: " #" (TOML allows # outside quoted strings).
		const hash = val.indexOf(" #");
		if (hash >= 0) val = val.slice(0, hash).trim();
		const stripOuterQuote = (s: string) => {
			if (s.length >= 2 && ((s.startsWith('"') && s.endsWith('"')) || (s.startsWith("'") && s.endsWith("'")))) {
				return s.slice(1, -1);
			}
			return s;
		};
		val = stripOuterQuote(val);
		val = stripOuterQuote(val);
		out[key] = val;
	}
	return out;
}

function asNumber(v: string | undefined, fallback: number): number {
	if (v === undefined) return fallback;
	const n = Number(v);
	return Number.isFinite(n) ? n : fallback;
}

function envNumber(name: string, fallback: number): number {
	return asNumber(process.env[name], fallback);
}

function asBool(v: string | undefined, fallback: boolean): boolean {
	if (v === undefined) return fallback;
	return /^(true|1|yes|on)$/i.test(v);
}

function stripWrappingQuotes(v: string | undefined): string | undefined {
	if (!v) return v;
	let out = v;
	while (
		out.length >= 2 &&
		((out.startsWith('"') && out.endsWith('"')) || (out.startsWith("'") && out.endsWith("'")))
	) {
		out = out.slice(1, -1);
	}
	return out;
}

/**
 * Load recall config from disk:
 *   - file at recallConfigPath() provides the persistent override
 *   - DREAM_ACTIVE_RECALL=1 forces enabled=true for explicit live opt-in
 *   - DREAM_ACTIVE_RECALL=0 forces enabled=false as a kill switch
 *   - missing file → DEFAULT_RECALL_CONFIG
 */
export async function loadRecallConfig(): Promise<RecallConfig> {
	const path = recallConfigPath();
	let parsed: Record<string, string> = {};
	if (existsSync(path)) {
		try {
			parsed = parseFlatToml(await readFile(path, "utf8"));
		} catch {
			// fall through to defaults
		}
	}
	const cfg: RecallConfig = {
		enabled: asBool(parsed.enabled, DEFAULT_RECALL_CONFIG.enabled),
		model_alias: ((parsed.model_alias as RecallConfig["model_alias"]) ??
			DEFAULT_RECALL_CONFIG.model_alias),
		budget_ms: asNumber(parsed.budget_ms, DEFAULT_RECALL_CONFIG.budget_ms),
		ceiling_ms: asNumber(parsed.ceiling_ms, DEFAULT_RECALL_CONFIG.ceiling_ms),
		breaker_threshold: asNumber(
			parsed.breaker_threshold,
			DEFAULT_RECALL_CONFIG.breaker_threshold,
		),
		breaker_cooldown_ms: asNumber(
			parsed.breaker_cooldown_ms,
			DEFAULT_RECALL_CONFIG.breaker_cooldown_ms,
		),
		max_hits: asNumber(parsed.max_hits, DEFAULT_RECALL_CONFIG.max_hits),
		model_override: parsed.model_override ?? undefined,
		show_ui: asBool(parsed.show_ui, DEFAULT_RECALL_CONFIG.show_ui),
		qmd_mode: ((stripWrappingQuotes(parsed.qmd_mode) as RecallConfig["qmd_mode"]) ??
			DEFAULT_RECALL_CONFIG.qmd_mode),
		context_turns: asNumber(parsed.context_turns, DEFAULT_RECALL_CONFIG.context_turns),
		prompt_variant: ((stripWrappingQuotes(parsed.prompt_variant) as RecallConfig["prompt_variant"]) ??
			DEFAULT_RECALL_CONFIG.prompt_variant),
		min_score: asNumber(parsed.min_score, DEFAULT_RECALL_CONFIG.min_score),
		candidate_limit: asNumber(parsed.candidate_limit, DEFAULT_RECALL_CONFIG.candidate_limit),
		auto_none_threshold: asNumber(parsed.auto_none_threshold, DEFAULT_RECALL_CONFIG.auto_none_threshold),
		min_prompt_length: asNumber(parsed.min_prompt_length, DEFAULT_RECALL_CONFIG.min_prompt_length),
		qmd_http_port: asNumber(parsed.qmd_http_port, DEFAULT_RECALL_CONFIG.qmd_http_port),
	};
	if (process.env.DREAM_ACTIVE_RECALL === "1") cfg.enabled = true;
	if (process.env.DREAM_ACTIVE_RECALL === "0") cfg.enabled = false;
	// Env overrides — autoresearch knobs (Phase 0c + 0d). Each is opt-in;
	// missing env vars leave the toml/default value in place.
	if (process.env.RECALL_MAX_HITS) cfg.max_hits = envNumber("RECALL_MAX_HITS", cfg.max_hits);
	if (process.env.RECALL_BUDGET_MS) cfg.budget_ms = envNumber("RECALL_BUDGET_MS", cfg.budget_ms);
	if (process.env.RECALL_MODEL_ALIAS) {
		cfg.model_alias = process.env.RECALL_MODEL_ALIAS as RecallConfig["model_alias"];
	}
	if (process.env.RECALL_MODEL_OVERRIDE) cfg.model_override = process.env.RECALL_MODEL_OVERRIDE;
	if (process.env.RECALL_QMD_MODE) {
		cfg.qmd_mode = process.env.RECALL_QMD_MODE as RecallConfig["qmd_mode"];
	}
	if (process.env.RECALL_CONTEXT_TURNS) cfg.context_turns = envNumber("RECALL_CONTEXT_TURNS", cfg.context_turns);
	if (process.env.RECALL_PROMPT_VARIANT) {
		cfg.prompt_variant = process.env.RECALL_PROMPT_VARIANT as RecallConfig["prompt_variant"];
	}
	if (process.env.RECALL_MIN_SCORE) cfg.min_score = envNumber("RECALL_MIN_SCORE", cfg.min_score);
	if (process.env.RECALL_CANDIDATE_LIMIT) {
		cfg.candidate_limit = envNumber("RECALL_CANDIDATE_LIMIT", cfg.candidate_limit);
	}
	if (process.env.RECALL_AUTO_NONE_THRESHOLD) {
		cfg.auto_none_threshold = envNumber("RECALL_AUTO_NONE_THRESHOLD", cfg.auto_none_threshold);
	}
	if (process.env.RECALL_MIN_PROMPT_LENGTH) {
		cfg.min_prompt_length = envNumber("RECALL_MIN_PROMPT_LENGTH", cfg.min_prompt_length);
	}
	if (process.env.DREAM_QMD_HTTP_PORT) {
		cfg.qmd_http_port = envNumber("DREAM_QMD_HTTP_PORT", cfg.qmd_http_port);
	}
	return cfg;
}

/** Serialise a RecallConfig as flat TOML — used by `dream recall config`. */
export function serialiseRecallConfig(cfg: RecallConfig): string {
	const lines: string[] = [
		"# ~/.dream-memory/recall.toml — active-memory v1 config.",
		"# Per-turn recall sub-agent. Off by default.",
		"# DREAM_ACTIVE_RECALL=1 enables explicit live opt-in; DREAM_ACTIVE_RECALL=0 remains a kill switch.",
		"",
		`enabled = ${cfg.enabled}`,
		`model_alias = "${cfg.model_alias}"`,
		`budget_ms = ${cfg.budget_ms}            # default budget for the haiku call`,
		`ceiling_ms = ${cfg.ceiling_ms}           # hard upper bound, even if budget is bumped at call site`,
		`breaker_threshold = ${cfg.breaker_threshold}     # consecutive timeouts that open the breaker`,
		`breaker_cooldown_ms = ${cfg.breaker_cooldown_ms}  # cooldown after open`,
		`max_hits = ${cfg.max_hits}              # recall top-N pre-fetched and shown to the haiku`,
	];
	if (cfg.model_override) {
		lines.push(`model_override = "${cfg.model_override}"`);
	}
	lines.push(`show_ui = ${cfg.show_ui}             # show memory components in the Pi TUI (toggle with /memory)`);
	lines.push("");
	// autoresearch-tuned knobs
	lines.push(`qmd_mode = "${cfg.qmd_mode}"          # "search" = qmd BM25 only, "query" = external hybrid HTTP path`);
	lines.push(`context_turns = ${cfg.context_turns}            # prepend N prior turns to QMD query (0 = disabled)`);
	lines.push(`prompt_variant = "${cfg.prompt_variant}"     # terse | compact | expanded | cot`);
	lines.push(`min_score = ${cfg.min_score}              # discard candidates below this score before haiku (0 = disabled)`);
	lines.push(`candidate_limit = ${cfg.candidate_limit}        # external hybrid candidate pool size`);
	lines.push(`auto_none_threshold = ${cfg.auto_none_threshold}       # return NONE without haiku if max hit score < this`);
	lines.push(`min_prompt_length = ${cfg.min_prompt_length}         # skip recall entirely for prompts shorter than this`);
	lines.push(`qmd_http_port = ${cfg.qmd_http_port}              # QMD HTTP daemon port (0 = BM25 subprocess only)`);
	lines.push("");
	return lines.join("\n");
}

// ---------------------------------------------------------------------------
// Circuit breaker — persistent state at ~/.dream-memory/recall-breaker.json.

export interface BreakerState {
	consecutive_timeouts: number;
	opened_at_ms: number | null;
}

export const FRESH_BREAKER: BreakerState = { consecutive_timeouts: 0, opened_at_ms: null };

export async function readBreakerState(): Promise<BreakerState> {
	const p = recallBreakerPath();
	if (!existsSync(p)) return { ...FRESH_BREAKER };
	try {
		const raw = JSON.parse(await readFile(p, "utf8")) as Partial<BreakerState>;
		return {
			consecutive_timeouts: Number(raw.consecutive_timeouts ?? 0),
			opened_at_ms: raw.opened_at_ms == null ? null : Number(raw.opened_at_ms),
		};
	} catch {
		return { ...FRESH_BREAKER };
	}
}

async function writeBreakerStateAtomic(state: BreakerState): Promise<void> {
	const p = recallBreakerPath();
	await mkdir(dirname(p), { recursive: true });
	const tmp = `${p}.${randomBytes(6).toString("hex")}.tmp`;
	await writeFile(tmp, JSON.stringify(state, null, 2));
	await rename(tmp, p);
}

/** Returns true if breaker is OPEN (call should be skipped). */
export function isBreakerOpen(state: BreakerState, cfg: RecallConfig, nowMs: number): boolean {
	if (state.opened_at_ms === null) return false;
	return nowMs - state.opened_at_ms < cfg.breaker_cooldown_ms;
}

export async function recordBreakerOutcome(
	state: BreakerState,
	cfg: RecallConfig,
	outcome: "success" | "timeout",
	nowMs: number,
): Promise<BreakerState> {
	let next: BreakerState;
	if (outcome === "success") {
		// Reset on any non-timeout. Even if the breaker is technically still
		// open by clock, a successful call is the cleanest signal that
		// upstream is healthy.
		next = { consecutive_timeouts: 0, opened_at_ms: null };
	} else {
		const ct = state.consecutive_timeouts + 1;
		const opened =
			ct >= cfg.breaker_threshold
				? state.opened_at_ms ?? nowMs
				: state.opened_at_ms;
		next = { consecutive_timeouts: ct, opened_at_ms: opened };
	}
	await writeBreakerStateAtomic(next);
	return next;
}

// ---------------------------------------------------------------------------
// Recall sub-agent

export interface ActiveRecallOptions {
	prompt: string;
	/**
	 * Prior conversation turns (last N messages), flattened to a single string
	 * with ' | ' separators. Used to resolve ambiguous follow-up prompts.
	 * When provided and cfg.context_turns > 0, prepended to the QMD query.
	 */
	priorContext?: string | undefined;
	cwd: string;
	/** Session id for event logging (from extension closure). */
	sessionId?: string;
	/** Harness client tag for event logging. */
	client?: string;
	/** Override config — tests. Defaults to loadRecallConfig(). */
	config?: RecallConfig;
	/** Override registry — tests. Defaults to createPiRegistry(). */
	registry?: RecallRegistry;
	/** Parent session model; used to resolve provider-relative fast-class. */
	parentModel?: { provider: string; id: string; api: string };
	/** Override completeFn — tests. Defaults to dynamic-imported pi-ai.complete. */
	completeFn?: PiCompleteFn;
	/** Override hits source — tests. Defaults to searchMemory(). */
	searchFn?: (q: string, opts: { topN: number; cwd: string }) => Promise<SearchHit[]>;
	/** Override now() — tests. */
	nowMs?: () => number;
	/** Hard upper-bound override; clamped to cfg.ceiling_ms. */
	budgetMs?: number;
	/** Test-only logger. */
	logger?: (msg: string) => void;
}

export interface ActiveRecallReturn {
	message: {
		customType: "dream-memory.active-recall";
		content: string;
		display: true;
		details: {
			hits: number;
			latency_ms: number;
			model: string;
			summary?: string;
			tokens_in: number;
			tokens_out: number;
			cost_usd?: number;
		};
	};
}

/**
 * Recall ran a real search but found nothing worth injecting — zero candidates,
 * all candidates below the relevance floor, or the selector chose none. Distinct
 * from `undefined`, which means recall was skipped/errored before searching
 * (disabled, too-short prompt, breaker open, model failure). The UI surfaces this
 * as a quiet "nothing relevant" footer hint so an enabled recall is never silent.
 */
export const RECALL_CONSIDERED_EMPTY = { consideredEmpty: true } as const;
export type ActiveRecallConsideredEmpty = typeof RECALL_CONSIDERED_EMPTY;
export type ActiveRecallOutcome = ActiveRecallReturn | ActiveRecallConsideredEmpty;

/** Narrow an outcome to the selected-hits case (has an injectable message). */
export function isActiveRecallSelected(
	outcome: ActiveRecallOutcome | undefined,
): outcome is ActiveRecallReturn {
	return !!outcome && "message" in outcome;
}

const LEAN_RECALL_SYSTEM_PROMPT = `You select memory hits for the current user prompt.
Return JSON only: {"selected":["permalink"]}.
Select up to 5 permalinks that clearly help answer or execute the prompt.
If none clearly help, return {"selected":[]}.
No prose, markdown, reasoning, or invented facts.`;

const RECALL_PROMPT_VARIANTS: Record<RecallConfig["prompt_variant"], string> = {
	compact: LEAN_RECALL_SYSTEM_PROMPT,
	terse: LEAN_RECALL_SYSTEM_PROMPT,
	expanded: LEAN_RECALL_SYSTEM_PROMPT,
	cot: LEAN_RECALL_SYSTEM_PROMPT,
};

const RECALL_SYSTEM_PROMPT = LEAN_RECALL_SYSTEM_PROMPT;

/**
 * Strip a leading YAML frontmatter block (`---\n...\n---`) from a snippet.
 *
 * QMD's BM25 chunker treats the frontmatter block as the first searchable
 * chunk, so for queries that match a title keyword (e.g. "QMD chosen over
 * basic-memory") the highest-scoring snippet is YAML metadata, not prose.
 * The active-recall haiku then sees a wall of keys and colons and either
 * outputs NONE or hallucinates prose. This strip is a per-snippet defense:
 * if the matched chunk leads with frontmatter, drop it and use whatever
 * prose follows.
 *
 * Conservative: only strips when the snippet *starts* with `---` and the
 * closing fence is found. Pass-through otherwise. Internal `---` separators
 * mid-prose are untouched.
 */
export function stripFrontmatter(text: string): string {
	if (!text.startsWith("---")) return text;
	// Match leading frontmatter: --- (newline) ... (newline) ---
	const m = /^---\r?\n[\s\S]*?\r?\n---\r?\n?/.exec(text);
	if (!m) return text;
	return text.slice(m[0].length).trim();
}

function buildRecallPrompt(prompt: string, hits: SearchHit[], priorContext?: string): string {
	const hitsBlock = hits
		.slice(0, 10)
		.map((h, i) => {
			const raw = h.matched_chunk ?? h.content ?? "";
			const body = stripFrontmatter(raw).slice(0, 500);
			return `### hit_${i + 1}\npermalink: ${h.permalink}\ntitle: ${h.title}\nscore: ${h.score?.toFixed?.(3) ?? h.score}\nsnippet:\n${body}`;
		})
		.join("\n\n");
	const contextBlock =
		priorContext && priorContext.trim().length > 0
			? `\nPrior conversation context (disambiguation only; latest user prompt wins):\n${priorContext.trim()}\n`
			: "";
	return `Latest user prompt:
${prompt}${contextBlock}

Candidate memories:
${hitsBlock}

Selection rules:
- Another model will answer the user; do not answer the user.
- Select a memory only if it clearly helps with the latest user prompt.
- Prefer NONE/empty selection for weak, broad, speculative, or merely topical matches.
- If the user asks to ignore memory, select nothing.
- Treat old code/path claims as context only; the answering model must verify current files.

Return JSON only: {"selected":["permalink"]}. Use an empty array when nothing is clearly useful.`;
}

function stripJsonFence(text: string): string {
	return text
		.trim()
		.replace(/^```(?:json)?\s*/i, "")
		.replace(/\s*```$/, "")
		.trim();
}

function normaliseSelectedPermalink(value: string): string {
	return value
		.trim()
		.replace(/^qmd:\/\/[^/]+\//, "")
		.replace(/\.md$/, "");
}

export function parseSelectedPermalinks(text: string, validPermalinks: readonly string[]): string[] {
	const valid = new Set(validPermalinks);
	let parsed: unknown;
	try {
		parsed = JSON.parse(stripJsonFence(text));
	} catch {
		return [];
	}
	const raw = Array.isArray(parsed)
		? parsed
		: parsed && typeof parsed === "object"
			? (parsed as { selected?: unknown; selected_memories?: unknown; permalinks?: unknown }).selected
				?? (parsed as { selected_memories?: unknown }).selected_memories
				?? (parsed as { permalinks?: unknown }).permalinks
			: undefined;
	if (!Array.isArray(raw)) return [];
	const selected: string[] = [];
	for (const item of raw) {
		if (typeof item !== "string") continue;
		const permalink = normaliseSelectedPermalink(item);
		if (!valid.has(permalink) || selected.includes(permalink)) continue;
		selected.push(permalink);
		if (selected.length >= 5) break;
	}
	return selected;
}

function selectedHitsFromText(text: string, hits: SearchHit[]): SearchHit[] {
	const byPermalink = new Map(hits.map((h) => [h.permalink, h]));
	return parseSelectedPermalinks(text, hits.map((h) => h.permalink))
		.map((permalink) => byPermalink.get(permalink))
		.filter((h): h is SearchHit => h !== undefined);
}

function isPrimaryLookupHit(hit: SearchHit): boolean {
	const key = `${hit.permalink}\n${hit.file_path ?? ""}`;
	if (/\b(memory|profile|project|inbox|dream-memory-profile|dream-memory-project|scars|changes)\//.test(key)) return false;
	return /(^|\n)(projects|workspace-info\/|docs\/|[a-z0-9._-]+)(\.md)?(\n|$)/i.test(key);
}

/**
 * v3 freshness warnings — mirrors Claude Code's `memdir/memoryAge.ts`.
 *
 * Tag each memory with an age-aware caveat before injection. Stale ≠ wrong,
 * but stale file:line citations get asserted as fact too often without one.
 *
 * Days are floor-rounded; <=1 day = no caveat (fresh enough); >=30 days =
 * stronger "historical only" tone. Wording copied verbatim from CC's MIT-
 * licensed memoryFreshnessText() for the canonical case.
 */
export function memoryAgeDays(mtimeMs: number, nowMs: number = Date.now()): number {
	return Math.max(0, Math.floor((nowMs - mtimeMs) / 86_400_000));
}

export function freshnessCaveat(days: number): string {
	if (days <= 1) return "";
	if (days >= 30) {
		return (
			`<system-reminder>This memory is ${days} days old and has not been refreshed since. ` +
			`Treat as historical only; verify against current code before asserting as fact.</system-reminder>`
		);
	}
	return (
		`<system-reminder>This memory is ${days} days old. ` +
		`Memories are point-in-time observations, not live state — ` +
		`claims about code behavior or file:line citations may be outdated. ` +
		`Verify against current code before asserting as fact.</system-reminder>`
	);
}

/** Best-effort mtime lookup. Returns undefined if path unknown or stat fails. */
async function hitMtimeMs(hit: SearchHit): Promise<number | undefined> {
	if (!hit.file_path) return undefined;
	try {
		const s = await stat(hit.file_path);
		return s.mtimeMs;
	} catch {
		return undefined;
	}
}

function selectedMemoryBlock(hit: SearchHit, caveat: string): string {
	const raw = hit.matched_chunk ?? hit.content ?? "";
	const body = stripFrontmatter(raw).trim().slice(0, 1200);
	const title = hit.title && hit.title !== hit.permalink ? `Title: ${hit.title}\n` : "";
	return [caveat, `Memory: ${hit.permalink}`, title ? title.trimEnd() : "", body].filter(Boolean).join("\n");
}

export interface FreshnessSummary {
	permalinks: string[];
	maxAgeDays: number;
}

export async function buildSelectedRecallContent(
	hits: SearchHit[],
	opts: { nowMs?: number; logger?: (m: string) => void } = {},
): Promise<{ content: string; freshness: FreshnessSummary }> {
	const now = opts.nowMs ?? Date.now();
	const withAges = await Promise.all(
		hits.map(async (h) => {
			const m = await hitMtimeMs(h);
			const days = m === undefined ? 0 : memoryAgeDays(m, now);
			return { hit: h, days, caveat: freshnessCaveat(days) };
		}),
	);
	const blocks = withAges.map(({ hit, caveat }) => selectedMemoryBlock(hit, caveat));
	const flagged = withAges.filter((w) => w.caveat.length > 0);
	const maxAgeDays = withAges.reduce((m, w) => Math.max(m, w.days), 0);
	if (flagged.length > 0 && opts.logger) {
		opts.logger(
			`[active-memory.freshness] permalinks=${flagged.map((w) => w.hit.permalink).join(",")} maxAgeDays=${maxAgeDays}`,
		);
	}
	return {
		content: `<active-recall>\n${blocks.join("\n\n")}\n</active-recall>`,
		freshness: { permalinks: flagged.map((w) => w.hit.permalink), maxAgeDays },
	};
}

/**
 * Back-compat guard for older selector prompts that returned a NONE sentinel.
 * Current selector output is JSON; if a model still emits NONE, treat it as
 * no selected memories rather than injecting prose.
 */
export function isNoRelevantRecall(text: string): boolean {
	const firstLine = text
		.trim()
		.split(/\r?\n/, 1)[0]
		?.trim()
		.replace(/[.!]+$/, "");
	return firstLine === "NONE";
}

const TRIVIAL_RECALL_PROMPTS = new Set([
	"?",
	"again",
	"continue",
	"push",
	"pull",
	"thanks",
	"thankyou",
	"please",
	"status",
	"debug",
	"deploy",
	"review",
	"merge",
	"done",
	"okay",
	"cool",
]);

export function isTrivialRecallPrompt(input: string): boolean {
	const normalised = input.trim().toLowerCase().replace(/[.!]+$/, "");
	return TRIVIAL_RECALL_PROMPTS.has(normalised);
}

export function isLikelyRecallEntityPrompt(input: string): boolean {
	const prompt = input.trim();
	if (prompt.length < 6 || prompt.length > 80) return false;
	const tokens = prompt.split(/\s+/);
	if (tokens.length > 3) return false;
	return tokens.every((token) => {
		if (isTrivialRecallPrompt(token)) return false;
		return /^[a-z0-9][a-z0-9._-]{5,}$/i.test(token);
	});
}

/**
 * Apply temporal decay (mem0-inspired) to recall candidate scores BEFORE the
 * curator selects. Stale / never-recalled memories sink in ranking; recently
 * recalled ones keep their weight. Usage STATE comes from pi-memory's
 * `memory_usage` sidecar — never the cached prefix. Mutates `hits[].score` in
 * place. Untracked hits (e.g. dream-memory's own wiki files) get a neutral 1.0
 * multiplier. Never throws — decay is best-effort ranking sugar.
 */
function applyDecayRanking(hits: SearchHit[], log: (m: string) => void, nowMs: number = Date.now()): void {
	const cfg = loadDecayConfig();
	if (!cfg.enabled) return;
	const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
	if (paths.length === 0) return;
	const sidecar = openPiMemorySidecar();
	if (!sidecar) return;
	try {
		const usage = sidecar.usageByPath(paths);
		if (usage.size === 0) return;
		let decayed = 0;
		for (const hit of hits) {
			if (!hit.file_path || typeof hit.score !== "number") continue;
			const w = decayWeightForPath(hit.file_path, usage, { now: nowMs, halfLifeDays: cfg.halfLifeDays });
			if (w < 1) {
				hit.score = hit.score * w;
				decayed++;
			}
		}
		if (decayed > 0) log(`[active-recall] decay applied to ${decayed}/${hits.length} candidates`);
	} catch (err) {
		log(`[active-recall] decay ranking skipped: ${(err as Error).message}`);
	} finally {
		sidecar.close();
	}
}

/**
 * Record recall usage for the selected memory paths in pi-memory's `memory_usage`
 * sidecar. This increments usage_count + refreshes last_used_at, which is what
 * protects a recalled memory from decay-driven auto-delete. Sidecar-only write —
 * cache-safe. Never throws.
 */
function recordRecallUsage(hits: SearchHit[], log: (m: string) => void): void {
	if (loadDecayConfig().enabled === false) return;
	const paths = hits.map((h) => h.file_path).filter((p): p is string => typeof p === "string" && p.length > 0);
	if (paths.length === 0) return;
	const sidecar = openPiMemorySidecar();
	if (!sidecar) return;
	try {
		sidecar.recordMemoryUsage(paths, randomUUID());
	} catch (err) {
		log(`[active-recall] usage record skipped: ${(err as Error).message}`);
	} finally {
		sidecar.close();
	}
}

/**
 * Run a single recall pass. Returns the message-injection or undefined.
 * NEVER throws — every failure path collapses to undefined + best-effort
 * logging. The user's turn must not be blocked.
 */
export async function runActiveRecall(
	opts: ActiveRecallOptions,
): Promise<ActiveRecallOutcome | undefined> {
	const log = opts.logger ?? (() => undefined);
	const now = opts.nowMs ?? Date.now;

	let cfg: RecallConfig;
	try {
		cfg = opts.config ?? (await loadRecallConfig());
	} catch (err) {
		log(`[active-recall] config load failed: ${(err as Error).message}`);
		return undefined;
	}

	if (!cfg.enabled) return undefined;

	// Sub-agent guard lives at the caller (extension.ts `input` /
	// `before_agent_start` short-circuit on `ctx.source === "child-agent"`
	// before they ever schedule recall). The redundant env-var check here
	// was removed alongside the `PI_MEMORY_SUBAGENT` contract — the CLI
	// (`dream` subcommand) is intentional ad-hoc invocation and must still
	// run.


	// Trim the prompt — empty/whitespace skips.
	const prompt = opts.prompt.trim();
	if (prompt.length < 3) return undefined;
	if (isTrivialRecallPrompt(prompt)) {
		void emitActiveRecallEvent(opts, { reason: "trivial_prompt", prompt }, "RecallSkipped");
		return undefined;
	}

	// min_prompt_length short-circuit: very short prompts (acknowledgments, single words)
	// almost never benefit from memory recall. Return NONE deterministically without
	// touching QMD — faster and avoids false positives on short generic commands.
	if (cfg.min_prompt_length > 0 && prompt.length < cfg.min_prompt_length && !isLikelyRecallEntityPrompt(prompt)) {
		log(`[active-recall] min_prompt_length short-circuit: prompt length ${prompt.length} < ${cfg.min_prompt_length}`);
		void emitActiveRecallEvent(opts, { reason: "min_prompt_length", prompt_length: prompt.length, threshold: cfg.min_prompt_length }, "RecallSkipped");
		return undefined;
	}

	// Build the effective QMD query: when context_turns > 0 and the caller
	// supplied prior context, prepend it so ambiguous follow-up prompts
	// ("what was that scar again?") resolve against a richer query signal.
	// Mirror the bench's buildEffectivePrompt logic: join with ' | ' so qmd's
	// query parser treats this as a single topic, not a DSL directive.
	const effectiveQuery =
		cfg.context_turns > 0 && opts.priorContext && opts.priorContext.trim().length > 0
			? `${opts.priorContext.trim()} | ${prompt}`
			: prompt;

	// Breaker check.
	const breaker = await readBreakerState();
	if (isBreakerOpen(breaker, cfg, now())) {
		log(`[active-recall] breaker OPEN; skip (consecutive_timeouts=${breaker.consecutive_timeouts})`);
		void getAMTel().then(({ recordCounter }) => recordCounter("dream_memory.active_memory.breaker_opens", 1));
		void emitActiveRecallEvent(opts, { reason: "breaker_open", consecutive_timeouts: breaker.consecutive_timeouts }, "RecallSkipped");
		return undefined;
	}

	const budgetMs = Math.min(opts.budgetMs ?? cfg.budget_ms, cfg.ceiling_ms);
	const recallStartedAt = now();

	// Pre-fetch hits from qmd. qmd may be unhealthy; we federate candidates and
	// let the selector choose permalinks from actual hits rather than bailing
	// when hits.length === 0.
	let qmdHits: SearchHit[] = [];
	let qmdDegraded = false;
	let isPrimaryLookupRoute = false;
	let primaryLookupReason: RecallCollectionRoute["reason"] = "default-memory";
	try {
		if (opts.searchFn) {
			qmdHits = await opts.searchFn(effectiveQuery, { topN: cfg.max_hits, cwd: opts.cwd });
		} else {
			const projectSlug = await resolveProjectSlug(opts.cwd ?? process.cwd()).catch(() => undefined);
			const qmdRoute = resolveActiveRecallRoute(effectiveQuery, projectSlug);
			isPrimaryLookupRoute = qmdRoute.reason === "workspace" || qmdRoute.reason === "project-docs";
			primaryLookupReason = qmdRoute.reason;
			const extras = buildActiveRecallExtraQueries(effectiveQuery);
			const baseSearchOpts = {
				timeoutMs: budgetMs,
				qmdMode: qmdRoute.qmdMode ?? cfg.qmd_mode,
				candidateLimit: cfg.candidate_limit,
				httpPort: isPrimaryLookupRoute ? 0 : cfg.qmd_http_port,
				...(qmdRoute.qmdMode === "search" ? { rerank: false } : {}),
				...(extras.length > 0 ? { extraQueries: extras } : {}),
			};
			const qmdSearch = isPrimaryLookupRoute ? searchMemoryQmd : searchMemory;
			const searchCollections = async (collections: string[], pageSize: number) => {
				const queries = [effectiveQuery, ...extras];
				const { extraQueries: _extraQueries, ...singleQueryOpts } = baseSearchOpts;
				const perQuery = await Promise.all(collections.flatMap((collection) =>
					queries.map((query) =>
						qmdSearch(query, {
							...singleQueryOpts,
							pageSize,
							collections: [collection],
						}),
					),
				));
				return {
					results: perQuery.flatMap((result) => result.results),
					timedOut: perQuery.some((result) => result.timedOut),
					error: perQuery.find((result) => result.error)?.error,
				};
			};
			const qmdPromise = qmdRoute.primaryCollections && qmdRoute.globalCollections
				? Promise.all([
					searchCollections(qmdRoute.primaryCollections, Math.max(3, Math.ceil(cfg.max_hits * 0.6))),
					searchCollections(qmdRoute.globalCollections, Math.max(2, Math.floor(cfg.max_hits * 0.4))),
				]).then(([primary, global]) => ({
					results: [...primary.results, ...global.results],
					timedOut: primary.timedOut || global.timedOut,
					error: primary.error ?? global.error,
				}))
				: qmdSearch(effectiveQuery, {
					...baseSearchOpts,
					pageSize: cfg.max_hits,
					collections: qmdRoute.collections,
				});
			const qmd = await qmdPromise.catch((err) => {
				log(`[active-recall] qmd query failed: ${(err as Error).message}`);
				return { results: [] as SearchHit[], timedOut: false, error: String(err) };
			});
			if (qmd.timedOut || qmd.error) {
				qmdDegraded = true;
				log(`[active-recall] qmd degraded: ${qmd.error ?? "timeout"}`);
			}
			qmdHits = qmd.results ?? [];
		}
	} catch (err) {
		log(`[active-recall] pre-fetch failed: ${(err as Error).message}`);
		// Fall through with empty hits — still let the haiku decide.
	}

	// Dedupe by permalink, then optionally filter by cfg.min_score
	// (autoresearch knob — 0 disables).
	const seen = new Set<string>();
	const hits: SearchHit[] = [];
	for (const h of qmdHits) {
		const key = h.permalink ?? `${h.title}\u0000${h.file_path ?? ""}`;
		if (seen.has(key)) continue;
		seen.add(key);
		if (cfg.min_score > 0 && typeof h.score === "number" && h.score < cfg.min_score) {
			continue;
		}
		hits.push(h);
		if (hits.length >= cfg.max_hits) break;
	}

	// Short-circuit: if both backends returned nothing, skip the haiku call
	// entirely. In practice claude-haiku-4-5 does not reliably output "NONE"
	// for empty hits — it hallucinates content from training-data / session
	// context instead. Burning 1500+ tokens for a guaranteed no-op is also
	// wasteful. The original rationale ("haiku decides what's relevant") only
	// holds when there are actual candidates to reason over.
	if (hits.length === 0) {
		void qmdDegraded;
		void emitActiveRecallEvent(opts, { reason: "no_hits" }, "RecallSkipped");
		return RECALL_CONSIDERED_EMPTY;
	}

	// Temporal decay: down-rank stale / never-recalled candidates BEFORE the
	// curator (and before the auto-NONE threshold) sees them. Sidecar-read only;
	// mutates hit.score in the dynamic tail — never the cached prefix.
	applyDecayRanking(hits, log, now());

	// Auto-NONE short-circuit: if the highest-scoring hit is below the
	// configured threshold, the query is almost certainly ambiguous/generic
	// and no hit is relevant. Return NONE deterministically without a haiku
	// call — decouples ambiguous-NONE detection from stochastic haiku output.
	if (cfg.auto_none_threshold > 0 && !isPrimaryLookupRoute) {
		const maxScore = Math.max(
			...hits.map((h) => (typeof h.score === "number" ? h.score : 0)),
		);
		if (maxScore < cfg.auto_none_threshold) {
			log(
				`[active-recall] auto-NONE: max hit score ${maxScore.toFixed(3)} < threshold ${cfg.auto_none_threshold}`,
			);
			void emitActiveRecallEvent(opts, { reason: "auto_none_threshold", max_score: maxScore, threshold: cfg.auto_none_threshold, hits_fetched: hits.length }, "RecallSkipped");
			return RECALL_CONSIDERED_EMPTY;
		}
	}
	void qmdDegraded;

	// Workspace/docs routes are evidence lookups, not preference recall. If QMD
	// returned concrete primary hits, inject them directly instead of asking a
	// tiny selector model that may prefer topical global meta-memory. This keeps
	// lookup prompts deterministic and avoids an extra LLM call.
	if (isPrimaryLookupRoute) {
		const primaryHits = hits.filter(isPrimaryLookupHit).slice(0, primaryLookupReason === "workspace" ? 2 : 3);
		if (primaryHits.length > 0) {
			const latency = now() - recallStartedAt;
			// Recalled memories gain usage_count — this is what protects them from decay.
			recordRecallUsage(primaryHits, log);
			const { content } = await buildSelectedRecallContent(primaryHits, { nowMs: now(), logger: log });
			void emitActiveRecallEvent(opts, {
				result: "selected", model: "qmd-direct", latency_ms: latency,
				hits_fetched: hits.length, hits_used: primaryHits.length,
				permalinks: primaryHits.map((h) => h.permalink),
				bytes: Buffer.byteLength(content, "utf8"),
				tokens_in: 0, tokens_out: 0,
				qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
			}, "ActiveRecallSelected");
			const summary = content
				.replace(/^<active-recall>\n?/, "")
				.replace(/\n?<\/active-recall>$/, "")
				.replace(/\s+/g, " ")
				.trim();
			return {
				message: {
					customType: "dream-memory.active-recall",
					content,
					display: true,
					details: {
						hits: primaryHits.length,
						latency_ms: latency,
						model: "qmd-direct",
						summary: summary.length > 320 ? `${summary.slice(0, 317).trimEnd()}…` : summary,
						tokens_in: 0,
						tokens_out: 0,
					},
				},
			};
		}
	}

	// Resolve model + auth via the adapter.
	let registry: RecallRegistry;
	try {
		registry =
			opts.registry ?? ((await createPiRegistry()).registry as unknown as RecallRegistry);
	} catch (err) {
		log(`[active-recall] registry construction failed: ${(err as Error).message}`);
		return undefined;
	}
	let model;
	try {
		model = pickModel(registry, cfg.model_alias, cfg.model_override, opts.parentModel);
	} catch (err) {
		log(`[active-recall] pickModel failed: ${(err as Error).message}`);
		return undefined;
	}

	// Wire abort + budget timeout.
	const ctrl = new AbortController();
	const timeoutHandle = setTimeout(() => ctrl.abort(), budgetMs);
	const start = now();

	let _activeRecallResult: ActiveRecallOutcome | undefined;

	const { withSpan, recordLlmCall } = await getAMTel();
	await withSpan("active-memory.recall", {
		candidates_in: hits.length,
		qmd_hits: qmdHits.length,
	}, async (span) => {
		try {
			const systemPromptText = RECALL_PROMPT_VARIANTS[cfg.prompt_variant] ?? RECALL_SYSTEM_PROMPT;
			const recallPromptText = buildRecallPrompt(prompt, hits, opts.priorContext);
			const result = await callPiModel({
				registry,
				model,
				system: systemPromptText,
				prompt: recallPromptText,
				maxTokens: 200,
				// Recall prompts are per-turn and snippet-heavy; caching them creates writes
				// with no reliable future read.
				cacheRetention: "none",
				signal: ctrl.signal,
				...(opts.completeFn ? { completeFn: opts.completeFn } : {}),
			});
			clearTimeout(timeoutHandle);
			await recordBreakerOutcome(breaker, cfg, "success", now());

			const text = result.text.trim();
			const latency = now() - start;
			const modelId = `${model.provider}/${model.id}`;
			log(`[active-recall] ${modelId} ${latency}ms ${result.usage.input}+${result.usage.output} tok ${hits.length} hits`);

			const selectedHits = isNoRelevantRecall(text) ? [] : selectedHitsFromText(text, hits);

			// Opik LLM trace (100% sampling per D5).
			void recordLlmCall({
				name: "active-memory.recall",
				input: recallPromptText,
				output: text,
				model: modelId,
				tokens_in: result.usage.input,
				tokens_out: result.usage.output,
				...(result.usage.costUsd !== undefined ? { cost_usd: result.usage.costUsd } : {}),
				latency_ms: latency,
				metadata: {
					candidates_in: hits.length,
					hits_out: selectedHits.length,
					qmd_collections: activeRecallCollections().join(","),
					breaker_state: `${breaker.consecutive_timeouts}/${cfg.breaker_threshold}`,
				},
			});

			if (selectedHits.length === 0) {
				span.setAttributes({ hits_out: 0, result: "none" });
				void emitActiveRecallEvent(opts, {
					result: "none", model: modelId, latency_ms: latency,
					hits_fetched: hits.length, hits_used: 0, bytes: 0,
					tokens_in: result.usage.input, tokens_out: result.usage.output,
					qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
				}, "ActiveRecallSelected");
				_activeRecallResult = RECALL_CONSIDERED_EMPTY;
				return;
			}

			// Recalled memories gain usage_count — this is what protects them from decay.
			recordRecallUsage(selectedHits, log);
			const { content, freshness } = await buildSelectedRecallContent(selectedHits, { nowMs: now(), logger: log });
			void freshness;
			span.setAttributes({ hits_out: selectedHits.length, result: "selected", bytes: Buffer.byteLength(content, "utf8") });
			void emitActiveRecallEvent(opts, {
				result: "selected", model: modelId, latency_ms: latency,
				hits_fetched: hits.length, hits_used: selectedHits.length,
				permalinks: selectedHits.map((h) => h.permalink),
				bytes: Buffer.byteLength(content, "utf8"),
				tokens_in: result.usage.input, tokens_out: result.usage.output,
				qmd: { state: qmdDegraded ? "degraded" : "ok", hits: qmdHits.length },
			}, "ActiveRecallSelected");

			const summary = content
				.replace(/^<active-recall>\n?/, "")
				.replace(/\n?<\/active-recall>$/, "")
				.replace(/\s+/g, " ")
				.trim();

			_activeRecallResult = {
				message: {
					customType: "dream-memory.active-recall",
					content,
					display: true,
					details: {
						hits: selectedHits.length,
						latency_ms: latency,
						model: modelId,
						summary: summary.length > 320 ? `${summary.slice(0, 317).trimEnd()}…` : summary,
						tokens_in: result.usage.input,
						tokens_out: result.usage.output,
						...(result.usage.costUsd !== undefined ? { cost_usd: result.usage.costUsd } : {}),
					},
				},
			};
		} catch (err) {
			clearTimeout(timeoutHandle);
			const isTimeout = err instanceof PiModelAbortError;
			const latency = now() - start;
			if (isTimeout) {
				await recordBreakerOutcome(breaker, cfg, "timeout", now());
				void getAMTel().then(({ recordCounter }) => recordCounter("dream_memory.active_memory.breaker_opens", 1));
				log(`[active-recall] timeout @${budgetMs}ms; breaker now ${breaker.consecutive_timeouts + 1}/${cfg.breaker_threshold}`);
				span.setAttributes({ result: "timeout" });
				void emitActiveRecallEvent(opts, {
					result: "timeout", model: `${model.provider}/${model.id}`, latency_ms: latency,
					hits_fetched: hits.length, hits_used: 0, bytes: 0,
					tokens_in: 0, tokens_out: 0,
					qmd: { state: "ok", hits: qmdHits.length },
				});
			} else if (err instanceof PiModelAuthError || err instanceof PiModelError) {
				log(`[active-recall] ${err.name}: ${err.message}`);
			} else {
				log(`[active-recall] unexpected: ${(err as Error).message}`);
			}
			_activeRecallResult = undefined;
		}
	});

	return _activeRecallResult;
}

async function emitActiveRecallEvent(
	opts: Pick<ActiveRecallOptions, "sessionId" | "client" | "cwd">,
	payload: Record<string, unknown>,
	eventType: "ActiveRecallSelected" | "ActiveRecallInjected" | "RecallSkipped" = "ActiveRecallInjected",
): Promise<void> {
	if (!opts.sessionId) return;
	try {
		const slug = await resolveProjectSlug(opts.cwd);
		await appendEvent({
			sessionId: opts.sessionId,
			client: opts.client ?? "pi",
			cwd: opts.cwd,
			projectSlug: slug,
			eventType,
			payload,
		});
	} catch {
		/* never throw from instrumentation */
	}
}

