/**
 * pi-context-intelligence — Claude Code-style progressive skill loading for pi.
 *
 * Two coordinated changes:
 *
 * 1. `systemPrompt:build` filter rewrites the system prompt's
 *    <available_skills>...</available_skills> block from pi's verbose
 *    XML-with-paths format to a flat `- name: description` list (Claude
 *    Code's format), capping each description at MAX_DESC_CHARS.
 *
 * 2. `skill` tool resolves a skill name to its SKILL.md and returns the
 *    body. The model never sees skill paths in the prompt; it asks for
 *    skills by name and the tool delivers.
 *
 * Net effect: ~67% off the skills index for typical setups.
 */
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { Type } from "@sinclair/typebox";
import { keyHint, type ExtensionAPI } from "@valkyriweb/pi-coding-agent";
import { Text } from "@valkyriweb/pi-tui";
import {
  discoverSkills,
  nearestNames,
  clearSkillCache,
  listSkillReferences,
  readSkillReference,
  readProgressivePolicy,
  fuzzyScore,
  approxTokens,
  type SkillReference,
  type DiscoveredSkill,
} from "./skills.ts";

/**
 * Per-entry hard cap on description chars (CC parity: MAX_LISTING_DESC_CHARS = 250).
 * Real cap may shrink lower under budget pressure — see BUDGET_CHARS.
 */
const MAX_DESC_CHARS = 250;

/**
 * Global budget for the rendered <available_skills> block, in characters.
 *
 * CC's SkillTool uses 1% of the model's context window in tokens, with a
 * fallback DEFAULT_CHAR_BUDGET = 8_000 chars. We use the fallback unconditionally
 * here — pi's ExtensionContext doesn't expose context-window size in a stable
 * shape across providers, and the char fallback is the conservative choice anyway.
 *
 * Lifting this dynamically is a Phase 5 polish.
 */
const BUDGET_CHARS = 8_000;

/**
 * Floor for per-entry description cap. CC drops to names-only below 20 chars
 * because anything shorter is more confusing than helpful.
 */
const MIN_DESC_CHARS = 20;

const BUILTIN_COMMANDS = new Set([
  "help",
  "model",
  "settings",
  "reload",
  "new",
  "resume",
  "fork",
  "clone",
  "compact",
  "tree",
  "clear",
  "exit",
  "quit",
  "theme",
  "tools",
  "status",
  "skill-search",
]);

const SkillParams = Type.Object({
  name: Type.String({
    description: "The skill's name (matches a name shown in <available_skills>).",
  }),
  child: Type.Optional(
    Type.Union([
      Type.String({ description: "Exact child reference to load from this parent skill, e.g. progressive-disclosure or gmail/send. Feed shows it as a loaded ref." }),
      Type.Array(Type.String(), { description: "Exact child refs to load together from this parent skill." }),
    ]),
  ),
});

const SkillSearchParams = Type.Object({
  action: Type.Union([Type.Literal("list"), Type.Literal("search"), Type.Literal("get")], {
    description: "List child references for a parent skill, search refs, or load exact refs.",
  }),
  parent: Type.Optional(Type.String({ description: "Parent skill name, e.g. gws or planning." })),
  child: Type.Optional(
    Type.Union([
      Type.String({ description: "Exact child reference name/path, e.g. gws-gmail or gmail/send. Use '*' only when the user explicitly asks to load every child ref." }),
      Type.Array(Type.String(), { description: "Exact child refs to load together; do not set mode:'all' for a named list." }),
    ]),
  ),
  query: Type.Optional(Type.String({ description: "Search query for parent/ref names and descriptions." })),
  mode: Type.Optional(Type.Union([Type.Literal("choose-one"), Type.Literal("sequential"), Type.Literal("parallel"), Type.Literal("all")], { description: "How to combine refs. Omit for exact child refs. Use all only with child:'*' when explicitly asked to load every ref." })),
  recursive: Type.Optional(Type.Boolean({ description: "Include nested child refs up to the parent's max-depth (hard-capped at 3); only when explicitly requested." })),
  force: Type.Optional(Type.Boolean({ description: "Allow all/recursive broad loads only when explicitly requested." })), 
});

