import assert from "node:assert/strict";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import register from "./tokenjuice.generated.js";

const previousAgentDir = process.env.PI_CODING_AGENT_DIR;
const testAgentDir = mkdtempSync(join(tmpdir(), "tokenjuice-agent-"));
process.env.PI_CODING_AGENT_DIR = testAgentDir;

function createHost() {
  const handlers = new Map();
  register({
    on(name, handler) {
      handlers.set(name, handler);
    },
    registerCommand() {},
    appendEntry() {},
  });
  const toolResult = handlers.get("tool_result");
  assert.equal(typeof toolResult, "function");
  return toolResult;
}

function createContext({ source = "interactive", provider = "openai-codex", id = "gpt-5.5" } = {}) {
  const cwd = mkdtempSync(join(tmpdir(), "tokenjuice-cwd-"));
  return {
    cwd,
    source,
    model: { provider, id },
    hasUI: false,
    ui: { notify() {} },
    sessionManager: {
      getHeader: () => ({ cwd }),
      getCwd: () => cwd,
      getEntries: () => [],
      getBranch: () => [],
    },
  };
}

function largeOutput(label = "line") {
  return Array.from({ length: 700 }, (_, index) => `${label}-${index}: ${"x".repeat(90)}`).join("\n");
}

async function runToolResult(event, ctx) {
  const toolResult = createHost();
  return toolResult(
    {
      content: [{ type: "text", text: largeOutput(event.toolName) }],
      details: {},
      isError: false,
      ...event,
    },
    ctx,
  );
}

try {
  const execResult = await runToolResult(
    { toolName: "exec_command", input: { cmd: "rg openclaw" } },
    createContext({ id: "gpt-5.5" }),
  );
  assert.equal(execResult?.details?.tokenjuice?.compacted, true);
  assert.match(execResult.content[0].text, /tokenjuice compacted exec_command output/u);
  assert.ok(execResult.content[0].text.length < 2_500);

  const sparkResult = await runToolResult(
    { toolName: "exec_command", input: { cmd: "rg openclaw" } },
    createContext({ id: "gpt-5.3-codex-sparks" }),
  );
  assert.equal(sparkResult, undefined);

  const childSonnetResult = await runToolResult(
    { toolName: "grep", input: { pattern: "openclaw" } },
    createContext({ source: "child-agent", provider: "claude-bridge", id: "claude-sonnet-4-5" }),
  );
  assert.equal(childSonnetResult?.details?.tokenjuice?.compacted, true);
  assert.match(childSonnetResult.content[0].text, /tokenjuice compacted grep output/u);

  const childHaikuResult = await runToolResult(
    { toolName: "grep", input: { pattern: "openclaw" } },
    createContext({ source: "child-agent", provider: "claude-bridge", id: "claude-haiku-4-5" }),
  );
  assert.equal(childHaikuResult, undefined);

  const exploreAgentResult = await runToolResult(
    { toolName: "Agent", input: { subagent_type: "explore", task: "map files" } },
    createContext({ id: "gpt-5.5" }),
  );
  assert.equal(exploreAgentResult, undefined);

  const workerAgentResult = await runToolResult(
    { toolName: "Agent", input: { subagent_type: "worker", task: "fix files" } },
    createContext({ id: "gpt-5.5" }),
  );
  assert.equal(workerAgentResult?.details?.tokenjuice?.compacted, true);
  assert.match(workerAgentResult.content[0].text, /tokenjuice compacted agent output/u);

  const webResult = await runToolResult(
    { toolName: "web_fetch", input: { url: "https://example.test" } },
    createContext({ id: "gpt-5.5" }),
  );
  assert.equal(webResult, undefined);
} finally {
  if (previousAgentDir === undefined) {
    delete process.env.PI_CODING_AGENT_DIR;
  } else {
    process.env.PI_CODING_AGENT_DIR = previousAgentDir;
  }
  rmSync(testAgentDir, { recursive: true, force: true });
}

