const agg = {};
rows.forEach(r => { const k = r.role + "/" + r.kind; agg[k] = (agg[k] || 0) + r.t; });
Object.entries(agg).sort((a, b) => b[1] - a[1]).forEach(([k, v]) => console.log(String(v).padStart(8), k));

