import { readFileSync } from "node:fs";
const p = process.argv[2] || "/tmp/bridge-dump.json";
const body = JSON.parse(readFileSync(p, "utf8"));
const msgs = body.messages || [];
const est = (s) => Math.ceil((typeof s === "string" ? s.length : JSON.stringify(s).length) / 4);
const semantic = (m) => {
  const blocks = Array.isArray(m.content) ? m.content : [{ type: "text", text: m.content }];
  let t = 0;
  for (const b of blocks) {
    if (b.type === "text") t += est(b.text);
    else if (b.type === "thinking") t += est(b.thinking || "");
    else if (b.type === "tool_use") t += est(b.input || {});
    else if (b.type === "tool_result") {
      const c = b.content;
      const txt = Array.isArray(c) ? c.map(x => x.text || JSON.stringify(x)).join("") : (typeof c === "string" ? c : JSON.stringify(c));
      t += est(txt);
    } else t += est(b);
  }
  return t;
};
const rows = msgs.map((m, i) => {
  const wire = est(m);            // full serialized message
  const sem = semantic(m);        // just visible content
  return { i, role: m.role, wire, sem, hidden: wire - sem };
});
console.log("SUM wire", rows.reduce((a, r) => a + r.wire, 0), " SUM semantic", rows.reduce((a, r) => a + r.sem, 0), " SUM hidden", rows.reduce((a, r) => a + r.hidden, 0));
console.log("\n== TOP 20 by HIDDEN (wire - semantic) ==");
rows.slice().sort((a, b) => b.hidden - a.hidden).slice(0, 20).forEach(r =>
  console.log(`msg#${String(r.i).padStart(3)} ${r.role.padEnd(9)} wire=${String(r.wire).padStart(6)} sem=${String(r.sem).padStart(6)} hidden=${String(r.hidden).padStart(6)}`));
// Dump the field structure of the single most hidden-heavy message
const worst = rows.slice().sort((a, b) => b.hidden - a.hidden)[0];
console.log(`\n== STRUCTURE of worst msg#${worst.i} (${worst.role}) ==`);
const m = msgs[worst.i];
const blocks = Array.isArray(m.content) ? m.content : [{ type: "text", text: m.content }];
blocks.forEach((b, j) => {
  const keys = Object.keys(b);
  const sizes = {};
  for (const k of keys) sizes[k] = est(b[k]);
  console.log(` blk#${j} type=${b.type} keys=[${keys.join(",")}] sizes=${JSON.stringify(sizes)}`);
});

