function logValue(value) {
  return String(value).replace(/[\s|]+/g, "_").slice(0, 160);
}

// Per-section token estimate for the outgoing request. Logging-only and
// cache-safe (never mutates `params`). Splits tools into eager vs deferred so a
// burst is instantly attributable to the right slot: a jump in `toolsEager`
// means deferral was dropped (defer_loading ignored); a jump in `msgs`/`msgMax`
// means a large tool result / pasted block is sitting in live context (tokenjuice
// lag); a jump in `sys` means a prompt/memory/skill injection. `~tok` = chars/4.
function estimatePromptSections(params) {
  try {
    const tok = (v) => Math.round((typeof v === "string" ? v : JSON.stringify(v ?? "")).length / 4);
    const sys = tok(params.system);
    let toolsEager = 0;
    let toolsDefer = 0;
    for (const t of params.tools || []) {
      if (t && t.defer_loading) toolsDefer += tok(t);
      else toolsEager += tok(t);
    }
    let msgs = 0;
    let msgMax = 0;
    for (const m of params.messages || []) {
      const t = tok(m && m.content);
      msgs += t;
      if (t > msgMax) msgMax = t;
    }
    return { sys, toolsEager, toolsDefer, msgs, msgMax };
  } catch {
    return null;
  }
}

function formatRequestLog({ timestamp, requestId, model, messageCount, toolCount, isStreaming, meta, sections }) {
  const fields = [
    `[${timestamp}]`,
    `request=${requestId}`,
    model,
    `msgs=${messageCount}`,
    `tools=${toolCount}`,
    `stream=${isStreaming}`,
  ];
  if (sections) {
    fields.push(
      `sys~=${sections.sys}`,
      `toolsEager~=${sections.toolsEager}`,
      `toolsDefer~=${sections.toolsDefer}`,
      `msgs~=${sections.msgs}`,
      `msgMax~=${sections.msgMax}`,
    );
  }
  for (const key of ["source", "agent", "agentId", "sessionId", "piSessionId", "title", "cwd", "pid", "parentSession", "childAgent"]) {

