import {
  compactContinuationPromptStable,
  continuationGoalIdFromPrompt,
  continuationPromptStable,
  supersededContinuationMessage,
} from "./prompts.js";
import {
  isActiveGoalQueuedDetails,
  type QueuedGoalContextCarrier,
  type QueuedGoalContextInput,
  type QueuedGoalCustomMessage,
  type QueuedGoalTextPart,
  type QueuedGoalUserMessage,
  type QueuedGoalWorkSourceMessage,
  toQueuedGoalContextCarrier,
  toQueuedGoalWorkSource,
  userContentFromUnknown,
} from "./queued-goal-messages.js";
import { CUSTOM_ENTRY_TYPE, type GoalStatus, type ThreadGoal } from "./types.js";

interface SupersededContinuationDetails {
  kind: "superseded_continuation";
  goalId: string;
}

interface StaleContinuationDetails {
  kind: "stale_continuation";
  goalId: string;
  currentGoalId: string | null;
  currentStatus: GoalStatus | null;
}

interface SupersededQueuedGoalCustomMessage extends QueuedGoalCustomMessage {
  content: string;
  display: false;
  details: SupersededContinuationDetails;
}

interface SupersededQueuedGoalUserMessage extends QueuedGoalUserMessage {
  content: QueuedGoalTextPart[];
}

interface StaleQueuedGoalCustomMessage extends QueuedGoalCustomMessage {
  content: string;
  display: false;
  details: StaleContinuationDetails;
}

interface StaleQueuedGoalUserMessage extends QueuedGoalUserMessage {
  content: QueuedGoalTextPart[];
}

interface RefreshedActiveQueuedGoalCustomMessage extends QueuedGoalCustomMessage {
  content: string;
  display: false;
}

interface RefreshedActiveQueuedGoalUserMessage extends QueuedGoalUserMessage {
  content: QueuedGoalTextPart[];
}

type RewrittenQueuedGoalWorkMessage =
  | SupersededQueuedGoalCustomMessage
  | SupersededQueuedGoalUserMessage
  | StaleQueuedGoalCustomMessage
  | StaleQueuedGoalUserMessage
  | RefreshedActiveQueuedGoalCustomMessage
  | RefreshedActiveQueuedGoalUserMessage;

type ProviderContextRewrite<TMessage extends QueuedGoalContextInput> =
  TMessage & RewrittenQueuedGoalWorkMessage;

/** Single typed bridge from concrete queued-goal rewrites back onto provider-context messages. */
function mergeProviderContextMessage<TMessage extends QueuedGoalContextInput>(
  original: TMessage,

content.content:
75	  original: TMessage,
76	  rewritten: RewrittenQueuedGoalWorkMessage,
77	): ProviderContextRewrite<TMessage> {
78	  return {
79	    ...original,
80	    ...rewritten,
81	  };
82	}
83	
84	function isSupersededContinuationDetails(details: unknown): boolean {
85	  return details !== null && typeof details === "object" && (details as { kind?: unknown }).kind === "superseded_continuation";
86	}
87	
88	function textContentFromMessageContent(content: unknown): string | null {
89	  if (typeof content === "string") {
90	    return content;
91	  }
92	
93	  const parts = userContentFromUnknown(content);
94	  if (parts.length === 0) {
95	    return null;
96	  }
97	
98	  return parts.map((part) => part.text).join("\n");
99	}
100	
101	function continuationGoalIdFromMessageContent(content: unknown): string | null {
102	  const text = textContentFromMessageContent(content);
103	  return text === null ? null : continuationGoalIdFromPrompt(text);
104	}
105	
106	function staleGoalContinuationMessage(queuedGoalId: string, currentGoal: ThreadGoal | null): string {
107	  const currentState = currentGoal
108	    ? `Current goal id: ${currentGoal.goalId}; current status: ${currentGoal.status}.`
109	    : "There is no current goal.";
110	  return [
111	    "A queued hidden goal continuation was stale and has been cancelled before running.",
112	    `Queued goal id: ${queuedGoalId}.`,
113	    currentState,
114	    "Ignore only this stale hidden bookkeeping message; do not perform work for the queued goal id above or mention this cancellation to the user.",
115	  ].join("\n");
116	}
117	
118	export function extensionQueuedGoalWorkMessageId(message: QueuedGoalContextInput): string | null {
119	  if (message.role !== "custom" || message.customType !== CUSTOM_ENTRY_TYPE) {
120	    return null;
121	  }
122	
123	  if (isSupersededContinuationDetails(message.details)) {
124	    return null;
125	  }
126	
127	  if (isActiveGoalQueuedDetails(message.details)) {
128	    return message.details.goalId;
129	  }
130	
131	  return continuationGoalIdFromMessageContent(message.content);
132	}
133	
134	function queuedGoalWorkMessageId(message: QueuedGoalContextInput): string | null {
135	  if (message.role === "user") {
136	    return continuationGoalIdFromMessageContent(message.content);
137	  }
138	
139	  return extensionQueuedGoalWorkMessageId(message);
140	}
141	
142	function supersededContinuationContextMessage(
143	  message: QueuedGoalWorkSourceMessage,
144	  goalId: string,
145	): SupersededQueuedGoalCustomMessage | SupersededQueuedGoalUserMessage {
146	  const content = supersededContinuationMessage(goalId);
147	
148	  if (message.role === "custom") {
149	    return {
150	      ...message,
151	      content,
152	      display: false,
153	      details: {
154	        kind: "superseded_continuation" as const,
155	        goalId,
156	      },
157	    };
158	  }
159	
160	  const userContent: QueuedGoalTextPart[] = [{ type: "text", text: content }];
161	  return {
162	    ...message,
163	    content: userContent,
164	  };
165	}
166	
167	// CACHE CRITICAL: rewrite-in-place path. This function's output replaces an
168	// existing historical message's content on every onContext event so the agent
169	// sees the current continuation prompt at a stable message position. Every
170	// byte emitted here MUST be stable across turns for a given (goalId,
171	// objective); any volatile field (elapsed time, tokens used, tokens
172	// remaining) invalidates the cached prefix from this position to the tail.
173	// Use the *Stable variants only; the agent can fetch live numbers via the
174	// get_goal tool when needed. See `continuationPromptStable` in prompts.ts
175	// for the full rationale.
176	function continuationPromptForProviderContext(
177	  goal: ThreadGoal,
178	  message: Pick<QueuedGoalWorkSourceMessage, "details">,
179	): string {
180	  if (isActiveGoalQueuedDetails(message.details)) {
181	    const kind = message.details.kind;
182	    if (kind === "command_start" || kind === "command_resume") {
183	      return continuationPromptStable(goal);
184	    }
185	  }
186	
187	  return compactContinuationPromptStable(goal);
188	}
189	
190	function dedupeActiveGoalContinuations<TMessage extends QueuedGoalContextInput>(
191	  messages: readonly TMessage[],
192	  goal: ThreadGoal,
193	  resolveQueuedGoalWorkMessageId: (message: QueuedGoalContextInput) => string | null,
194	): { messages: TMessage[]; changed: boolean } {
195	  const activeGoalId = goal.goalId;
196	  const indices: number[] = [];
197	  for (let index = 0; index < messages.length; index += 1) {
198	    const message = messages[index];
199	    if (!message) {
200	      continue;
201	    }
202	    const queuedGoalId = resolveQueuedGoalWorkMessageId(message);
203	    if (queuedGoalId === activeGoalId) {
204	      indices.push(index);
205	    }
206	  }
207	
208	  const latestIndex = indices.at(-1);
209	  if (latestIndex === undefined) {
210	    return { messages: [...messages], changed: false };
211	  }
212	
213	  let changed = false;
214	  const nextMessages = [...messages];
215	
216	  // CACHE CRITICAL: do NOT rewrite earlier continuations in place. Each
217	  // continuation block already carries CONTINUATION_SUPERSEDE_NOTICE, so a later
218	  // continuation supersedes earlier ones by POSITION. Mutating an earlier
219	  // (historical) message here — e.g. into a "superseded" stub — changes its
220	  // bytes and invalidates the Anthropic prompt cache from that position to the
221	  // tail, forcing a full transcript rewrite at every continuation boundary
222	  // (cache_read collapses to the system+tools anchor, cache_write reinflates).
223	  // We only refresh the latest continuation (below), which sits at the rolling
224	  // tail where a one-time append→stable rewrite is cheap.
225	
226	  const latestMessage = nextMessages[latestIndex];
227	  if (!latestMessage) {
228	    return { messages: nextMessages, changed };
229	  }
230	  const latestCarrier = toQueuedGoalContextCarrier(latestMessage);
231	  if (!latestCarrier) {
232	    return { messages: nextMessages, changed };
233	  }
234	  const latestSource = toQueuedGoalWorkSource(latestCarrier);
235	  if (!latestSource) {
236	    return { messages: nextMessages, changed };
237	  }
238	
239	  const refreshedContent = continuationPromptForProviderContext(goal, latestSource);
240	  if (latestSource.role === "custom") {
241	    if (latestMessage.content !== refreshedContent) {
242	      const refreshed: RefreshedActiveQueuedGoalCustomMessage = {
243	        ...latestSource,
244	        content: refreshedContent,
245	        display: false,
246	      };
247	      nextMessages[latestIndex] = mergeProviderContextMessage(latestMessage, refreshed);
248	      changed = true;
249	    }
250	  } else {
251	    const refreshedUserContent: QueuedGoalTextPart[] = [{ type: "text", text: refreshedContent }];
252	    const currentContent = textContentFromMessageContent(latestMessage.content);
253	    if (currentContent !== refreshedContent) {
254	      const refreshed: RefreshedActiveQueuedGoalUserMessage = {
255	        ...latestSource,
256	        content: refreshedUserContent,
257	      };
258	      nextMessages[latestIndex] = mergeProviderContextMessage(latestMessage, refreshed);
259	      changed = true;
260	    }
261	  }
262	
263	  return { messages: nextMessages, changed };
264	}
265	
266	function staleGoalContinuationContextMessage(
267	  message: QueuedGoalWorkSourceMessage,
268	  queuedGoalId: string,
269	  currentGoal: ThreadGoal | null,
270	): StaleQueuedGoalCustomMessage | StaleQueuedGoalUserMessage {
271	  const content = staleGoalContinuationMessage(queuedGoalId, currentGoal);
272	  const staleDetails = {
273	    kind: "stale_continuation" as const,
274	    goalId: queuedGoalId,
275	    currentGoalId: currentGoal?.goalId ?? null,
276	    currentStatus: currentGoal?.status ?? null,
277	  };
278	
279	  if (message.role === "custom") {
280	    return {
281	      ...message,
282	      content,
283	      display: false,
284	      details: staleDetails,
285	    };
286	  }
287	
288	  return {
289	    ...message,
290	    content: [{ type: "text", text: content }],
291	  };
292	}
293	
294	function rewriteStaleQueuedGoalContextMessage(
295	  message: QueuedGoalContextCarrier,
296	  queuedGoalId: string,
297	  currentGoal: ThreadGoal | null,
298	): StaleQueuedGoalCustomMessage | StaleQueuedGoalUserMessage | null {
299	  const source = toQueuedGoalWorkSource(message);
300	  if (!source) {
301	    return null;
302	  }
303	  return staleGoalContinuationContextMessage(source, queuedGoalId, currentGoal);
304	}
305	
306	export function applyQueuedGoalProviderContextRewrites<TMessage extends QueuedGoalContextInput>(
307	  messages: readonly TMessage[],
308	  options: {
309	    goal: ThreadGoal | null;
310	    resolveStaleQueuedGoalWorkMessageId: (message: QueuedGoalContextInput) => string | null;
311	    resolveActiveContinuationQueuedGoalWorkMessageId: (message: QueuedGoalContextInput) => string | null;
312	  },
313	): { messages: TMessage[]; changed: boolean } {
314	  let changed = false;
315	  let nextMessages: TMessage[] = messages.map((message) => {
316	    const queuedGoalId = options.resolveStaleQueuedGoalWorkMessageId(message);
317	    if (queuedGoalId === null) {
318	      return message;
319	    }
320	
321	    if (options.goal?.goalId === queuedGoalId && options.goal.status === "active") {
322	      return message;
323	    }
324	
325	    const carrier = toQueuedGoalContextCarrier(message);
326	    if (!carrier) {
327	      return message;
328	    }
329	
330	    const rewritten = rewriteStaleQueuedGoalContextMessage(carrier, queuedGoalId, options.goal);
331	    if (!rewritten) {
332	      return message;
333	    }
334	
335	    changed = true;
336	    return mergeProviderContextMessage(message, rewritten);
337	  });
338	
339	  if (options.goal?.status === "active") {
340	    const deduped = dedupeActiveGoalContinuations(
