  const goal = withUsage(baseGoal, { tokensUsed: 0, activeSeconds: 0 });

  // Turn N: a single continuation sits at the tail and is refreshed to stable.
  const firstInput = goalCustomContextMessage({
    content: continuationPromptStable(goal),
    details: { kind: "command_start", goalId: goal.goalId },
    timestamp: 1,
  });
  const turnN = applyQueuedGoalProviderContextRewrites([firstInput], {
    goal,
    resolveStaleQueuedGoalWorkMessageId,
    resolveActiveContinuationQueuedGoalWorkMessageId,
  });
  const firstAfterTurnN = String(turnN.messages[0]?.content ?? "");

  // Turn N+1: a newer continuation appends at the tail carrying volatile,
  // drifting usage numbers (as freshly emitted). The runtime refreshes ONLY the
  // latest block; the earlier block must keep the exact bytes it had on turn N.
  const laterGoal = withUsage(baseGoal, { tokensUsed: 21_059, activeSeconds: 300 });
  const secondInput = goalCustomContextMessage({
    content: compactContinuationPrompt(laterGoal),
    details: { kind: "continuation", goalId: goal.goalId },
    timestamp: 2,
  });
  const turnNplus1 = applyQueuedGoalProviderContextRewrites([turnN.messages[0]!, secondInput], {
    goal: laterGoal,
    resolveStaleQueuedGoalWorkMessageId,
    resolveActiveContinuationQueuedGoalWorkMessageId,
  });

  // CACHE CRITICAL: the prior continuation's bytes and details are unchanged
  // across the append — no in-place supersede rewrite of a historical message.
  assert.equal(turnNplus1.changed, true);
  assert.equal(String(turnNplus1.messages[0]?.content ?? ""), firstAfterTurnN);
  assert.deepEqual(turnNplus1.messages[0]?.details, firstInput.details);

  // The latest block is refreshed to the stable variant (no volatile budget).
  const latestContent = String(turnNplus1.messages[1]?.content ?? "");
  assert.doesNotMatch(latestContent, /Tokens used:/);
  assert.doesNotMatch(latestContent, /Time spent pursuing goal:/);
  assert.equal(continuationGoalIdFromPrompt(latestContent), goal.goalId);
});

