1	#!/usr/bin/env node
2	// Analyze pi-claude-bridge [CACHE-BREAK] events ranked by cumulative cacheWrite tokens.
3	//
4	// Usage: node analyze-cache-breaks.mjs [path-to-err.log]
5	//
6	// Output (stdout, plain text):
7	//   - Event totals per cause (TTL, added, removed, schemas-changed, combos)
8	//   - Token totals per cause (cacheWrite + cacheRead-dropped)
9	//   - Per-tool attribution for added/removed/schema-changed buckets
10	//   - Top-N "tool churn" contributors ranked by tokens
11	//
12	// Methodology: each `[CACHE-BREAK]` line is followed (optionally) by a `  changes: ...`
13	// line. The absence of a changes line ⇒ TTL/server eviction. The presence of one or
14	// more change kinds (`tools added`, `tools removed`, `tool schemas changed`) ⇒ tool
15	// churn. Co-occurring change kinds are recorded in a single combined bucket plus
16	// each individual kind to allow both single-cause and combined views.
17	
18	import fs from "node:fs";
19	
20	const path = process.argv[2] ?? `${process.env.HOME}/.pi/agent/logs/claude-bridge.err.log`;
21	const raw = fs.readFileSync(path, "utf8");
22	const lines = raw.split("\n");
23	
24	const breakRe = /^\[CACHE-BREAK\]\s+(\S+):\s+cache_read\s+([\d,]+)\s+->\s+([\d,]+)\s+\(drop\s+([\d,]+),\s+write\s+([\d,]+)\)/;
25	const changesRe = /^\s+changes:\s+(.*)$/;
26	const num = (s) => Number(s.replace(/,/g, ""));
27	
28	const events = [];
29	for (let i = 0; i < lines.length; i++) {
30	  const m = lines[i].match(breakRe);
31	  if (!m) continue;
32	  const [, breakpoint, before, after, drop, write] = m;
33	  const next = lines[i + 1] ?? "";
34	  const cm = next.match(changesRe);
35	  const changes = cm ? cm[1] : "";
36	  events.push({ breakpoint, before: num(before), after: num(after), drop: num(drop), write: num(write), changes });
37	}
38	
39	// Parse a changes string into kinds + tool lists.
40	function parseChanges(s) {
41	  const out = { added: [], removed: [], schemas: [] };
42	  if (!s) return out;
43	  for (const part of s.split(";")) {
44	    const t = part.trim();
45	    let m;
46	    if ((m = t.match(/^tools added:\s*(.*)$/))) out.added = m[1].split(",").map((x) => x.trim()).filter(Boolean);
47	    else if ((m = t.match(/^tools removed:\s*(.*)$/))) out.removed = m[1].split(",").map((x) => x.trim()).filter(Boolean);
48	    else if ((m = t.match(/^tool schemas changed:\s*(.*)$/))) out.schemas = m[1].split(",").map((x) => x.trim()).filter(Boolean);
49	  }
50	  return out;
51	}
52	
53	// Bucketing.
54	const buckets = new Map(); // kindKey → { events, write, drop, toolsBlame: Map<tool,{count,write}> }
55	function add(key, ev, blameTools = []) {
56	  let b = buckets.get(key);
57	  if (!b) { b = { events: 0, write: 0, drop: 0, toolsBlame: new Map() }; buckets.set(key, b); }
58	  b.events++;
59	  b.write += ev.write;
60	  b.drop += ev.drop;
61	  for (const t of blameTools) {
62	    let r = b.toolsBlame.get(t);
63	    if (!r) { r = { count: 0, write: 0 }; b.toolsBlame.set(t, r); }
64	    r.count++;
65	    r.write += ev.write;
66	  }
67	}
68	
69	let totalWrite = 0, totalDrop = 0;
70	for (const ev of events) {
71	  totalWrite += ev.write;
72	  totalDrop += ev.drop;
73	  const c = parseChanges(ev.changes);
74	  const kinds = [];
75	  if (c.added.length) kinds.push("added");
76	  if (c.removed.length) kinds.push("removed");
77	  if (c.schemas.length) kinds.push("schemas");
78	  if (kinds.length === 0) {
79	    // Discriminate true TTL (no changes line at all) from OTHER (changes line present
80	    // but no tool churn — cache_control toggles, model swaps, beta-header changes).
81	    // Matches peer audit's split in docs/cache-break-investigation-2026-05-16.md §1.
82	    add(ev.changes ? "other" : "ttl", ev);
83	    continue;
84	  }
85	  // Add to per-kind buckets (events are counted in every kind they touch — so per-kind
86	  // event counts can exceed total event count when kinds co-occur).
87	  if (c.added.length) add("added", ev, c.added);
88	  if (c.removed.length) add("removed", ev, c.removed);
89	  if (c.schemas.length) add("schemas", ev, c.schemas);
90	  // Combined bucket (orthogonal classification).
91	  add(`combo:${kinds.sort().join("+")}`, ev);
92	}
93	
94	// Day count from log span: cheap proxy = lines / (lines per day) → use file mtime vs ctime,
95	// fall back to a CLI flag. For the local bridge per goal metadata: 18 days.
96	const days = Number(process.env.DAYS ?? 18);
97	
98	function fmt(n) { return n.toLocaleString("en-US"); }
99	function pct(part, total) { return total ? ((part / total) * 100).toFixed(1) + "%" : "0%"; }
100	
101	function header(title) { console.log("\n" + "=".repeat(78) + "\n" + title + "\n" + "=".repeat(78)); }
102	
103	header(`pi-claude-bridge cache-break analysis (${events.length} events, ${days}d window)`);
104	console.log(`Total cacheWrite tokens:   ${fmt(totalWrite)} (${fmt(Math.round(totalWrite / days))} / day)`);
105	console.log(`Total cacheRead dropped:   ${fmt(totalDrop)} (${fmt(Math.round(totalDrop / days))} / day)`);
106	console.log(`Sourcefile: ${path}`);
107	
108	header("Cause buckets (ranked by cacheWrite tokens)");
109	const ranked = [...buckets.entries()].sort((a, b) => b[1].write - a[1].write);
110	console.log("kind".padEnd(28) + "events".padStart(8) + "write tok".padStart(14) + "  share" + "    write/day");
111	for (const [k, b] of ranked) {
112	  console.log(
113	    k.padEnd(28) +
114	    String(b.events).padStart(8) +
115	    fmt(b.write).padStart(14) +
116	    "  " + pct(b.write, totalWrite).padStart(6) +
117	    "  " + fmt(Math.round(b.write / days)).padStart(12)
118	  );
119	}
120	
121	header("Per-tool attribution by bucket (top 10 each)");
122	for (const kind of ["added", "removed", "schemas"]) {
123	  const b = buckets.get(kind);
124	  if (!b) continue;
125	  console.log(`\n— ${kind} (bucket total: ${fmt(b.write)} cacheWrite tokens, ${b.events} events) —`);
126	  const tools = [...b.toolsBlame.entries()].sort((a, b) => b[1].write - a[1].write).slice(0, 10);
127	  console.log("tool".padEnd(40) + "events".padStart(8) + "write tok".padStart(14) + "  write/day");
128	  for (const [t, r] of tools) {
129	    console.log(
130	      t.padEnd(40) +
131	      String(r.count).padStart(8) +
132	      fmt(r.write).padStart(14) +
133	      "  " + fmt(Math.round(r.write / days)).padStart(10)
134	    );
135	  }
136	}
137	
138	header("Big-event tail (single events writing > 5,000 tokens)");
139	const big = events.filter((e) => e.write > 5000).sort((a, b) => b.write - a.write).slice(0, 15);
140	for (const e of big) {
141	  console.log(`write=${fmt(e.write)} drop=${fmt(e.drop)} | ${e.changes || "(TTL / no changes)"}`);
142	}
