#!/usr/bin/env node
// Analyze pi-claude-bridge [CACHE-BREAK] events ranked by cumulative cacheWrite tokens.
//
// Usage: node analyze-cache-breaks.mjs [path-to-err.log]
//
// Output (stdout, plain text):
//   - Event totals per cause (TTL, added, removed, schemas-changed, combos)
//   - Token totals per cause (cacheWrite + cacheRead-dropped)
//   - Per-tool attribution for added/removed/schema-changed buckets
//   - Top-N "tool churn" contributors ranked by tokens
//
// Methodology: each `[CACHE-BREAK]` line is followed (optionally) by a `  changes: ...`
// line. The absence of a changes line ⇒ TTL/server eviction. The presence of one or
// more change kinds (`tools added`, `tools removed`, `tool schemas changed`) ⇒ tool
// churn. Co-occurring change kinds are recorded in a single combined bucket plus
// each individual kind to allow both single-cause and combined views.

import fs from "node:fs";

const path = process.argv[2] ?? `${process.env.HOME}/.pi/agent/logs/claude-bridge.err.log`;
const raw = fs.readFileSync(path, "utf8");
const lines = raw.split("\n");

const breakRe = /^\[CACHE-BREAK\]\s+(\S+):\s+cache_read\s+([\d,]+)\s+->\s+([\d,]+)\s+\(drop\s+([\d,]+),\s+write\s+([\d,]+)\)/;
const changesRe = /^\s+changes:\s+(.*)$/;
const num = (s) => Number(s.replace(/,/g, ""));

const events = [];
for (let i = 0; i < lines.length; i++) {
  const m = lines[i].match(breakRe);
  if (!m) continue;
  const [, breakpoint, before, after, drop, write] = m;
  const next = lines[i + 1] ?? "";
  const cm = next.match(changesRe);
  const changes = cm ? cm[1] : "";
  events.push({ breakpoint, before: num(before), after: num(after), drop: num(drop), write: num(write), changes });
}

// Parse a changes string into kinds + tool lists.
function parseChanges(s) {
  const out = { added: [], removed: [], schemas: [] };
  if (!s) return out;
  for (const part of s.split(";")) {
    const t = part.trim();
    let m;
    if ((m = t.match(/^tools added:\s*(.*)$/))) out.added = m[1].split(",").map((x) => x.trim()).filter(Boolean);
    else if ((m = t.match(/^tools removed:\s*(.*)$/))) out.removed = m[1].split(",").map((x) => x.trim()).filter(Boolean);
    else if ((m = t.match(/^tool schemas changed:\s*(.*)$/))) out.schemas = m[1].split(",").map((x) => x.trim()).filter(Boolean);
  }
  return out;
}

// Bucketing.
const buckets = new Map(); // kindKey → { events, write, drop, toolsBlame: Map<tool,{count,write}> }
function add(key, ev, blameTools = []) {
  let b = buckets.get(key);
  if (!b) { b = { events: 0, write: 0, drop: 0, toolsBlame: new Map() }; buckets.set(key, b); }
  b.events++;
  b.write += ev.write;
  b.drop += ev.drop;
  for (const t of blameTools) {
    let r = b.toolsBlame.get(t);
    if (!r) { r = { count: 0, write: 0 }; b.toolsBlame.set(t, r); }
    r.count++;
    r.write += ev.write;
  }
}

let totalWrite = 0, totalDrop = 0;
for (const ev of events) {
  totalWrite += ev.write;
  totalDrop += ev.drop;
  const c = parseChanges(ev.changes);
  const kinds = [];
  if (c.added.length) kinds.push("added");
  if (c.removed.length) kinds.push("removed");
  if (c.schemas.length) kinds.push("schemas");
  if (kinds.length === 0) {
    // Discriminate true TTL (no changes line at all) from OTHER (changes line present
    // but no tool churn — cache_control toggles, model swaps, beta-header changes).
    // Matches peer audit's split in docs/cache-break-investigation-2026-05-16.md §1.
    add(ev.changes ? "other" : "ttl", ev);
    continue;
  }
  // Add to per-kind buckets (events are counted in every kind they touch — so per-kind
  // event counts can exceed total event count when kinds co-occur).
  if (c.added.length) add("added", ev, c.added);
  if (c.removed.length) add("removed", ev, c.removed);
  if (c.schemas.length) add("schemas", ev, c.schemas);
  // Combined bucket (orthogonal classification).
  add(`combo:${kinds.sort().join("+")}`, ev);
}

// Day count from log span: cheap proxy = lines / (lines per day) → use file mtime vs ctime,
// fall back to a CLI flag. For the local bridge per goal metadata: 18 days.
const days = Number(process.env.DAYS ?? 18);

function fmt(n) { return n.toLocaleString("en-US"); }
function pct(part, total) { return total ? ((part / total) * 100).toFixed(1) + "%" : "0%"; }

function header(title) { console.log("\n" + "=".repeat(78) + "\n" + title + "\n" + "=".repeat(78)); }

header(`pi-claude-bridge cache-break analysis (${events.length} events, ${days}d window)`);
console.log(`Total cacheWrite tokens:   ${fmt(totalWrite)} (${fmt(Math.round(totalWrite / days))} / day)`);
console.log(`Total cacheRead dropped:   ${fmt(totalDrop)} (${fmt(Math.round(totalDrop / days))} / day)`);
console.log(`Sourcefile: ${path}`);

header("Cause buckets (ranked by cacheWrite tokens)");
const ranked = [...buckets.entries()].sort((a, b) => b[1].write - a[1].write);
console.log("kind".padEnd(28) + "events".padStart(8) + "write tok".padStart(14) + "  share" + "    write/day");
for (const [k, b] of ranked) {
  console.log(
    k.padEnd(28) +
    String(b.events).padStart(8) +
    fmt(b.write).padStart(14) +
    "  " + pct(b.write, totalWrite).padStart(6) +
    "  " + fmt(Math.round(b.write / days)).padStart(12)
  );
}

header("Per-tool attribution by bucket (top 10 each)");
for (const kind of ["added", "removed", "schemas"]) {
  const b = buckets.get(kind);
  if (!b) continue;
  console.log(`\n— ${kind} (bucket total: ${fmt(b.write)} cacheWrite tokens, ${b.events} events) —`);
  const tools = [...b.toolsBlame.entries()].sort((a, b) => b[1].write - a[1].write).slice(0, 10);
  console.log("tool".padEnd(40) + "events".padStart(8) + "write tok".padStart(14) + "  write/day");
  for (const [t, r] of tools) {
    console.log(
      t.padEnd(40) +
      String(r.count).padStart(8) +
      fmt(r.write).padStart(14) +
      "  " + fmt(Math.round(r.write / days)).padStart(10)
    );
  }
}

header("Big-event tail (single events writing > 5,000 tokens)");
const big = events.filter((e) => e.write > 5000).sort((a, b) => b.write - a.write).slice(0, 15);
for (const e of big) {
  console.log(`write=${fmt(e.write)} drop=${fmt(e.drop)} | ${e.changes || "(TTL / no changes)"}`);
}

