header("Big-event tail (single events writing > 5,000 tokens)");
const big = events.filter((e) => e.write > 5000).sort((a, b) => b.write - a.write).slice(0, 15);
for (const e of big) {
  console.log(`write=${fmt(e.write)} drop=${fmt(e.drop)} | ${e.changes || "(TTL / no changes)"}`);
}

// ---------------------------------------------------------------------------
// Deep-message mutation analysis.
//
// A cache bust is only expensive when the *first divergent message* sits far
// from the tail: everything from that position onward must be re-written. The
// `first divergence: msg[K] of N shared, D from tail` diagnostic gives D.
//
//   - D <= TAIL (default 3)  → tail-local: the newest message(s) changed. This
//     is the normal, cheap cost of conversation growth.
//   - K === 0                → prefix-anchor: msg[0] (<system-context> /
//     <project_context>) mutated — invalidates the entire transcript.
//   - history truncated      → compaction dropped old messages — expected.
//   - otherwise (D > TAIL)   → DEEP-MESSAGE: a far-back historical message was
//     rewritten in place. This is the burst class fixed by pi-goal's positional
//     continuation supersession (queued-goal-work.ts dedupeActiveGoalContinuations).
//     A healthy post-fix log should show ~0 deep-message busts from goal
//     continuations; a regression makes this bucket reappear.
const TAIL = Number(process.env.TAIL ?? 3);
const posBuckets = {
  "tail-local": { events: 0, write: 0 },
  "prefix-anchor (msg[0])": { events: 0, write: 0 },
  "history-truncated": { events: 0, write: 0 },
  "DEEP-MESSAGE (far-back rewrite)": { events: 0, write: 0 },
  "unattributed (no divergence line)": { events: 0, write: 0 },
};
const deepEvents = [];
for (const e of events) {
  let key;
  if (!e.divergence) key = "unattributed (no divergence line)";
  else if (e.truncated) key = "history-truncated";
  else if (e.divergence.pos === 0) key = "prefix-anchor (msg[0])";
  else if (e.divergence.fromTail <= TAIL) key = "tail-local";
  else { key = "DEEP-MESSAGE (far-back rewrite)"; deepEvents.push(e); }
  posBuckets[key].events += 1;
  posBuckets[key].write += e.write;
}

header(`Cache-break cost by divergence position (TAIL<=${TAIL} = cheap)`);
console.log("class".padEnd(36) + "events".padStart(8) + "write tok".padStart(14) + "  share" + "    write/day");
for (const [k, b] of Object.entries(posBuckets).sort((a, b2) => b2[1].write - a[1].write)) {
  console.log(
    k.padEnd(36) +
    String(b.events).padStart(8) +
    fmt(b.write).padStart(14) +
    "  " + pct(b.write, totalWrite).padStart(6) +
    "  " + fmt(Math.round(b.write / days)).padStart(12)
  );
}

header("Worst DEEP-MESSAGE busts (far-back rewrites — the goal-continuation burst class)");
if (deepEvents.length === 0) {
  console.log("none — healthy: no far-back message rewrites detected.");
} else {
  console.log("breakpoint".padEnd(46) + "msg[pos]".padStart(9) + "fromTail".padStart(9) + "write tok".padStart(12));
  for (const e of deepEvents.sort((a, b) => b.write - a.write).slice(0, 20)) {
    console.log(
      e.breakpoint.slice(0, 44).padEnd(46) +
      String(e.divergence.pos).padStart(9) +
      String(e.divergence.fromTail).padStart(9) +
      fmt(e.write).padStart(12)
    );
  }
}

