const fs=require("fs");
const body=JSON.parse(fs.readFileSync("/tmp/bridge-dump.json","utf8"));
const est=(s)=>Math.ceil((typeof s==="string"?s:JSON.stringify(s??"")).length/4);
const msgs=body.messages||[];
const cat={text:0,thinking_text:0,thinking_sig:0,redacted:0,tool_use:0,tool_result:0,other:0};
let thinkBlocks=0, sigChars=0, biggest=[];
for(let i=0;i<msgs.length;i++){
  const m=msgs[i];
  const blocks=Array.isArray(m.content)?m.content:[{type:"_string",text:m.content}];
  for(const b of blocks){
    let t=0, label="";
    if(b.type==="text"||b.type==="_string"){ t=est(b.text); cat.text+=t; label="text"; }
    else if(b.type==="thinking"){ const tt=est(b.thinking||""); const st=est(b.signature||""); cat.thinking_text+=tt; cat.thinking_sig+=st; thinkBlocks++; sigChars+=(b.signature||"").length; t=tt+st; label="thinking"; }
    else if(b.type==="redacted_thinking"){ t=est(b.data); cat.redacted+=t; label="redacted"; }
    else if(b.type==="tool_use"){ t=est(b.input); cat.tool_use+=t; label="tool_use:"+b.name; }
    else if(b.type==="tool_result"){ const c=b.content; const txt=Array.isArray(c)?c.map(x=>x.text||JSON.stringify(x)).join(""):(typeof c==="string"?c:JSON.stringify(c)); t=est(txt); cat.tool_result+=t; label="tool_result"; }
    else { t=est(b); cat.other+=t; label=b.type||"?"; }
    biggest.push({i,label,t,role:m.role});
  }
}
const sysT=est(body.system), toolsT=est(body.tools);
const msgTotal=Object.values(cat).reduce((a,b)=>a+b,0);
const grand=sysT+toolsT+msgTotal;
let out="";
out+=`messages: ${msgs.length}\n`;
out+=`GRAND TOTAL ~${grand.toLocaleString()} tok (system ${sysT.toLocaleString()} + tools ${toolsT.toLocaleString()} + messages ${msgTotal.toLocaleString()})\n\n`;
