for(const [k,v] of rows){ out+=k.padEnd(16)+v.toLocaleString().padStart(12)+"  "+((v/grand*100).toFixed(1)+"%").padStart(7)+" of total\n"; }
out+=`\nthinking blocks: ${thinkBlocks} | avg sig chars: ${Math.round(sigChars/Math.max(1,thinkBlocks))} | total sig ~${cat.thinking_sig.toLocaleString()} tok (${(cat.thinking_sig/grand*100).toFixed(1)}% of total)\n`;
out+=`thinking (text+sig) combined: ~${(cat.thinking_text+cat.thinking_sig).toLocaleString()} tok (${((cat.thinking_text+cat.thinking_sig)/grand*100).toFixed(1)}% of total)\n\n`;
out+="=== top 12 single blocks ===\n";
for(const b of biggest.sort((a,b)=>b.t-a.t).slice(0,12)){ out+=`msg#${String(b.i).padStart(3)} ${b.role.padEnd(10)} ${b.label.slice(0,28).padEnd(28)} ~${b.t.toLocaleString()} tok\n`; }
fs.writeFileSync("/tmp/payload-composition.txt", out);
console.log(out);
'

