function scan(dir,depth=0){ if(depth>3||!fs.existsSync(dir))return; for(const e of fs.readdirSync(dir,{withFileTypes:true})){ if(["node_modules"].includes(e.name)&&depth>0)continue; const p=path.join(dir,e.name); if(e.isDirectory())scan(p,depth+1); else if(/^cli\.js$|claude-code.*\.js$/.test(e.name)) cands.push(p); } }
out+="\n=== candidate bundles (exists / size) ===\n";
for(const c of [...new Set(cands)]){ if(fs.existsSync(c)){ const s=fs.statSync(c); out+=`${(s.size/1024/1024).toFixed(1)}MB  ${c}\n`; } else out+=`(missing) ${c}\n`; }
fs.writeFileSync("/tmp/cc-locate.txt", out);
console.log(out);
'

