/**
 * Build upstream request headers based on auth mode.
 * Merges any beta headers from the incoming request to preserve
 * pi-ai transport's beta requirements.
 *
 * In keychain mode, fetches a fresh token (from cache or keychain).
 * Throws if no valid token is available.
 */
async function buildUpstreamHeaders(incomingHeaders) {
  const headers = {
    "content-type": "application/json",
    "anthropic-version": ANTHROPIC_VERSION,
  };

  // Merge incoming anthropic-beta with our own. The proxy sets
  // `x-bridge-context-1m: 1` on requests for models in CONTEXT_1M_MODELS.
  let incomingBeta = incomingHeaders?.["anthropic-beta"] || "";
  if (incomingHeaders?.["x-bridge-context-1m"] === "1") {
    incomingBeta = incomingBeta
      ? `${incomingBeta},context-1m-2025-08-07`
      : "context-1m-2025-08-07";
  }

  if (authMode !== "apikey") {
    const token = await getAccessToken();
    if (!token) {
      throw new Error(
        "No valid OAuth token available. Run: claude auth login"
      );
    }
    headers["authorization"] = `Bearer ${token}`;
    // Merge OAuth betas with incoming betas
    const oauthBetas = ["claude-code-20250219", "oauth-2025-04-20"];
    if (EXTENDED_CACHE) oauthBetas.push("extended-cache-ttl-2025-04-11");
    // Cache-diagnosis beta: Anthropic returns a `diagnostics` field on the
    // response telling us *why* the cache missed (system_changed, tools_changed,
    // messages_changed, etc). Best-effort even without previous_message_id.
    if (CACHE_DIAGNOSIS) oauthBetas.push("cache-diagnosis-2026-04-07");
    const incomingBetaList = incomingBeta
      ? incomingBeta.split(",").map((b) => b.trim())
      : [];
    const allBetas = [...new Set([...oauthBetas, ...incomingBetaList])];
    headers["anthropic-beta"] = allBetas.join(",");
    headers["user-agent"] = `claude-cli/${CLAUDE_CLI_VERSION}`;
    headers["x-app"] = "cli";
  } else {
    headers["x-api-key"] = ANTHROPIC_API_KEY;
    const apiKeyBetas = incomingBeta ? incomingBeta.split(",").map((b) => b.trim()) : [];
    if (EXTENDED_CACHE && !apiKeyBetas.includes("extended-cache-ttl-2025-04-11")) {
      apiKeyBetas.push("extended-cache-ttl-2025-04-11");
    }
    if (CACHE_DIAGNOSIS && !apiKeyBetas.includes("cache-diagnosis-2026-04-07")) {
      apiKeyBetas.push("cache-diagnosis-2026-04-07");
    }
    if (apiKeyBetas.length) headers["anthropic-beta"] = apiKeyBetas.join(",");
  }

