318	    (Array.isArray(fwd?.system) && fwd.system.some((b) => b?.cache_control)) ||
319	    (Array.isArray(fwd?.tools) && fwd.tools.some((t) => t?.cache_control)) ||
320	    (Array.isArray(fwd?.messages) &&
321	      fwd.messages.some(
322	        (m) => Array.isArray(m.content) && m.content.some((b) => b?.cache_control),
323	      ));
324	  assert(anyMarker, "A cache breakpoint was still placed (on tools/system/user turn)");
325	
