/**
 * Test the bridge against a mock Anthropic server.
 * Verifies request structure, header injection, and response forwarding.
 */
import http from "node:http";

const MOCK_PORT = Number(process.env.MOCK_PORT || 9200);
const BRIDGE_PORT = Number(process.env.BRIDGE_TEST_PORT || 19100);

// --- Mock Anthropic Server ---
let mockRequests = [];

const mockServer = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => (body += c));
  req.on("end", () => {
    const parsed = JSON.parse(body);
    const record = {
      method: req.method,
      url: req.url,
      headers: {
        "content-type": req.headers["content-type"],
        "anthropic-version": req.headers["anthropic-version"],
        "anthropic-beta": req.headers["anthropic-beta"],
        "x-api-key": req.headers["x-api-key"] ? "[present]" : undefined,
        authorization: req.headers["authorization"]
          ? req.headers["authorization"].substring(0, 25) + "..."
          : undefined,
        "user-agent": req.headers["user-agent"],
        "x-app": req.headers["x-app"],
      },
      bodyKeys: Object.keys(parsed),
      model: parsed.model,
      stream: parsed.stream,
      maxTokens: parsed.max_tokens,
      hasTools: !!parsed.tools,
      toolCount: parsed.tools?.length || 0,
      hasThinking: !!parsed.thinking,
      messages: parsed.messages,
      system: parsed.system,
      tools: parsed.tools,
    };
    mockRequests.push(record);

    if (parsed.stream) {
      // Return SSE stream
      res.writeHead(200, { "Content-Type": "text/event-stream" });
      res.write(
        `event: message_start\ndata: ${JSON.stringify({
          type: "message_start",
          message: {
            id: "msg_test",
            type: "message",
            role: "assistant",
            content: [],
            model: parsed.model,
            stop_reason: null,
            usage: { input_tokens: 10, output_tokens: 0 },
          },
        })}\n\n`
      );
      res.write(
        `event: content_block_start\ndata: ${JSON.stringify({
          type: "content_block_start",
          index: 0,
          content_block: { type: "text", text: "" },
        })}\n\n`
      );
      res.write(
        `event: content_block_delta\ndata: ${JSON.stringify({
          type: "content_block_delta",
          index: 0,
          delta: { type: "text_delta", text: "Hello from mock!" },
        })}\n\n`
      );
      res.write(
        `event: content_block_stop\ndata: ${JSON.stringify({
          type: "content_block_stop",
          index: 0,
        })}\n\n`
      );
      res.write(
        `event: message_delta\ndata: ${JSON.stringify({
          type: "message_delta",
          delta: { stop_reason: "end_turn" },
          usage: { output_tokens: 5 },
        })}\n\n`
      );
      res.write(
        `event: message_stop\ndata: ${JSON.stringify({
          type: "message_stop",
        })}\n\n`
      );
      res.end();
    } else {
      // Return JSON response
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(
        JSON.stringify({
          id: "msg_test",
          type: "message",
          role: "assistant",
          content: [{ type: "text", text: "Mock response" }],
          model: parsed.model,
          stop_reason: "end_turn",
          usage: { input_tokens: 10, output_tokens: 5 },
        })
      );
    }
  });
});

// --- Test Runner ---
async function fetchJSON(url, body, headers = {}) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: await res.text(), headers: res.headers };
}

async function fetchWithBeta(url, body, beta) {
  const res = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "anthropic-beta": beta,
    },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: await res.text(), headers: res.headers };
}

function assert(condition, message) {
  if (!condition) {
    console.error(`  FAIL: ${message}`);
    process.exitCode = 1;
  } else {
    console.log(`  PASS: ${message}`);
  }
}

async function runTests() {
  console.log("\n=== Test 1: Non-streaming, API key mode ===");
  mockRequests = [];
  const r1 = await fetchJSON(`http://127.0.0.1:${BRIDGE_PORT}/v1/messages`, {
    model: "claude-sonnet-4-6",
    max_tokens: 100,
    messages: [{ role: "user", content: "test" }],
  });
  assert(r1.status === 200, `HTTP 200 (got ${r1.status})`);
  const r1body = JSON.parse(r1.body);
  assert(r1body.content?.[0]?.text === "Mock response", "Response text");
  assert(r1body.model === "claude-sonnet-4-6", "Model passed through");

  const req1 = mockRequests[0];
  assert(req1.method === "POST", "Upstream POST");
  assert(req1.url === "/v1/messages", "Upstream URL");
  assert(req1.headers["anthropic-version"] === "2023-06-01", "anthropic-version header");
  assert(req1.headers["x-api-key"] === "[present]", "x-api-key present");
  assert(!req1.headers["authorization"], "No authorization header in apikey mode");
  assert(!req1.headers["x-app"], "No x-app in apikey mode");

  console.log("\n=== Test 2: Streaming ===");
  mockRequests = [];
  const r2 = await fetchJSON(`http://127.0.0.1:${BRIDGE_PORT}/v1/messages`, {
    model: "claude-sonnet-4-6",
    max_tokens: 100,
    stream: true,
    messages: [{ role: "user", content: "test" }],
  });
  assert(r2.status === 200, `HTTP 200 (got ${r2.status})`);
  assert(
    r2.headers.get("content-type").includes("text/event-stream"),
    "SSE content type"
  );
  assert(r2.body.includes("message_start"), "SSE has message_start");
  assert(r2.body.includes("Hello from mock!"), "SSE has text delta");
  assert(r2.body.includes("message_stop"), "SSE has message_stop");

  console.log("\n=== Test 3: Tools forwarded ===");
  mockRequests = [];
  const r3 = await fetchJSON(`http://127.0.0.1:${BRIDGE_PORT}/v1/messages`, {
    model: "claude-sonnet-4-6",
    max_tokens: 100,
    tools: [
      {
        name: "get_weather",
        description: "Get weather",
        input_schema: {
          type: "object",
          properties: { location: { type: "string" } },
          required: ["location"],
        },
      },
    ],
    messages: [{ role: "user", content: "Weather?" }],
  });
  const req3 = mockRequests[0];
  assert(req3.hasTools, "Tools forwarded to upstream");
  assert(req3.toolCount === 1, `Tool count = 1 (got ${req3.toolCount})`);

  console.log("\n=== Test 4: Thinking forwarded ===");
  mockRequests = [];
  const r4 = await fetchJSON(`http://127.0.0.1:${BRIDGE_PORT}/v1/messages`, {
    model: "claude-sonnet-4-6",
    max_tokens: 8000,
    thinking: { type: "enabled", budget_tokens: 4000 },
    messages: [{ role: "user", content: "Think about this" }],
  });
  const req4 = mockRequests[0];
  assert(req4.hasThinking, "Thinking params forwarded");

  console.log("\n=== Test 5: Beta headers merged ===");
  mockRequests = [];
  const r5 = await fetchWithBeta(
    `http://127.0.0.1:${BRIDGE_PORT}/v1/messages`,
    {
      model: "claude-sonnet-4-6",
      max_tokens: 100,
      messages: [{ role: "user", content: "test" }],
    },
    "fine-grained-tool-streaming-2025-05-14"
  );
  const req5 = mockRequests[0];
  assert(
    req5.headers["anthropic-beta"]?.includes(
      "fine-grained-tool-streaming-2025-05-14"
    ),
    "Incoming beta header forwarded"
  );

  console.log("\n=== Test 6: Health endpoint ===");
  const r6 = await fetch(`http://127.0.0.1:${BRIDGE_PORT}/health`).then((r) =>
    r.json()
  );
  assert(r6.status === "ok", "Health ok");
  assert(r6.auth === "apikey", "Auth mode reported");

  console.log("\n=== Test 7: Status endpoint ===");
  const r7 = await fetch(`http://127.0.0.1:${BRIDGE_PORT}/status`).then((r) =>
    r.json()
  );
  assert(r7.requests >= 5, `Request count >= 5 (got ${r7.requests})`);
  assert(r7.errors === 0, `Error count = 0 (got ${r7.errors})`);

  console.log("\n=== Test 8: Top callers endpoint ===");
  const r8 = await fetchJSON(
    `http://127.0.0.1:${BRIDGE_PORT}/v1/messages`,
    {
      model: "claude-sonnet-4-6",
      max_tokens: 100,
      messages: [{ role: "user", content: "telemetry" }],
    },
    {
      "x-pi-session-id": "session-test-1",
      "x-pi-session-title": "Telemetry Test",
      "x-pi-cwd": "/tmp/pi-test",
      "x-pi-pid": "12345",
      "x-pi-child-agent": "false",
    },
  );
  assert(r8.headers.get("x-bridge-request-id"), "Bridge request id response header");
  const topCallers = await fetch(`http://127.0.0.1:${BRIDGE_PORT}/top-callers`).then((r) => r.json());
  const caller = topCallers.windows["5m"].find((entry) => entry.id === "session-test-1");
  assert(caller, "Top caller includes pi session id");
  assert(caller?.input >= 10, `Top caller input tracked (got ${caller?.input})`);
  assert(caller?.meta?.title === "Telemetry Test", "Top caller title tracked");

  console.log("\n=== Test 9: Error passthrough (404 from mock) ===");
  // Test with a POST to wrong endpoint — bridge sends to /v1/messages which exists
  // Instead test invalid JSON
  const r9 = await fetch(`http://127.0.0.1:${BRIDGE_PORT}/v1/messages`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: "not-json",
  });
  assert(r9.status === 400, `Invalid JSON returns 400 (got ${r9.status})`);

  console.log("\n=== Test 10: cache breakpoints skip assistant turns with thinking ===");
  // Regression: the bridge used to place a rolling cache_control marker inside
  // the latest assistant turn. When that turn carries interleaved thinking,
  // Anthropic rejects ANY modification of it with 400 "thinking ... blocks in
  // the latest assistant message cannot be modified". The marker must land on a
  // user/tool_result turn instead.
  mockRequests = [];
  const pad = "x".repeat(6000); // push prefix over the 4KB cacheable floor
  const r10 = await fetchJSON(
    `http://127.0.0.1:${BRIDGE_PORT}/v1/messages`,
    {
      model: "claude-sonnet-4-6",
      max_tokens: 100,
      // tools present → bridge adds rolling breakpoints
      tools: [{ name: "Bash", description: pad, input_schema: { type: "object" } }],
      messages: [
        { role: "user", content: [{ type: "text", text: `start ${pad}` }] },
        {
          role: "assistant",
          content: [
            { type: "thinking", thinking: "reasoning...", signature: "sig-abc" },
            { type: "tool_use", id: "tu_1", name: "Bash", input: { command: "ls" } },
          ],
        },
        { role: "user", content: [{ type: "tool_result", tool_use_id: "tu_1", content: "ok" }] },
      ],
    },
    { "x-pi-session-id": "test-thinking-cache" },
  );
  assert(r10.status === 200, `HTTP 200 (got ${r10.status})`);
  const fwd = mockRequests[0];
  const asst = fwd?.messages?.find((m) => m.role === "assistant");
  const asstMarked = Array.isArray(asst?.content) && asst.content.some((b) => b?.cache_control);
  assert(asst && !asstMarked, "No cache_control inside the assistant turn with thinking");
  const thinkBlock = asst?.content?.find((b) => b.type === "thinking");
  assert(thinkBlock && !thinkBlock.cache_control, "Thinking block left unmodified");
  const anyMarker =
    (Array.isArray(fwd?.system) && fwd.system.some((b) => b?.cache_control)) ||
    (Array.isArray(fwd?.tools) && fwd.tools.some((t) => t?.cache_control)) ||
    (Array.isArray(fwd?.messages) &&
      fwd.messages.some(
        (m) => Array.isArray(m.content) && m.content.some((b) => b?.cache_control),
      ));
  assert(anyMarker, "A cache breakpoint was still placed (on tools/system/user turn)");

  console.log("\n=== DONE ===");
}

// Start mock server, then bridge, then run tests
mockServer.listen(MOCK_PORT, "127.0.0.1", () => {
  console.log(`Mock server on :${MOCK_PORT}`);

  // Import and start bridge
  process.env.ANTHROPIC_API_KEY = "test-key-123";
  process.env.ANTHROPIC_BASE_URL = `http://127.0.0.1:${MOCK_PORT}`;
  process.env.PORT = String(BRIDGE_PORT);

  import("./index.js").then(() => {
    setTimeout(async () => {
      try {
        await runTests();
      } catch (e) {
        console.error("Test error:", e);
        process.exitCode = 1;
      }
      process.exit(process.exitCode || 0);
    }, 500);
  });
});

