function paramsHaveThinking(params) {
  return Array.isArray(params?.messages) && params.messages.some((m) => messageHasThinking(m?.content));
}

// The clear_thinking_20251015 strategy is ONLY valid when the request itself has
// extended thinking enabled or adaptive — Anthropic returns 400
// "`clear_thinking_20251015` strategy requires `thinking` to be enabled or
// adaptive" otherwise. That mismatch is real: when thinking is toggled OFF
// mid-session, prior thinking blocks still sit in history (paramsHaveThinking is
// true) while params.thinking is "disabled"/absent. Attaching the edit there
// would break the whole request. So gate on the thinking param, and only bother
// when there are prior blocks to clear.
function thinkingClearEligible(params) {
  const type = params?.thinking?.type;
  return (type === "enabled" || type === "adaptive") && paramsHaveThinking(params);
}

