function hashAny(value) {
  if (value === undefined || value === null) return "_";
  return sha(typeof value === "string" ? value : JSON.stringify(value));
}

function fingerprint(params, headers = {}) {
  const tools = Array.isArray(params.tools) ? params.tools : [];
  const toolNames = tools.map((t) => t.name).sort();
  const perToolHash = Object.fromEntries(
    tools.map((t) => [
      t.name,
      hashAny({ d: t.description, s: t.input_schema, c: t.cache_control ?? null }),
    ]),
  );
  // When capture is on, also stash raw serialized schemas keyed by name so
  // diffFingerprints can dump prev-vs-curr for changed tools.
  const perToolRaw = CAPTURE_SCHEMA_DIFFS
    ? Object.fromEntries(
        tools.map((t) => [
          t.name,
          JSON.stringify({ description: t.description, input_schema: t.input_schema }),
        ]),
      )
    : undefined;

  const systemBlocks = Array.isArray(params.system)
    ? params.system
    : typeof params.system === "string"
      ? [{ type: "text", text: params.system }]
      : [];

  const betas = (headers["anthropic-beta"] || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)
    .sort();

  const messages = Array.isArray(params.messages) ? params.messages : [];
  const lastMsg = messages[messages.length - 1];
  const firstMsg = messages[0];

  // Per-position message hash so a mutation inside any prior message (e.g. an
  // extension's onContext rewriting an earlier turn) shows up as a position-N
  // divergence rather than the misleading "no field changes" verdict.
  // We hash content only (role+content) and skip the last block's
  // cache_control flag since marker placement is bridge-controlled.
  const perMessageHash = messages.map((m, i) => {
    const content = Array.isArray(m?.content)
      ? m.content.map((b) => {
          if (!b || typeof b !== "object") return b;
          if (b.type === "text") return { type: "text", text: b.text };
          if (b.type === "tool_use") return { type: "tool_use", id: b.id, name: b.name, input: b.input };
          if (b.type === "tool_result") return { type: "tool_result", tool_use_id: b.tool_use_id, content: b.content, is_error: b.is_error };
          if (b.type === "thinking" || b.type === "redacted_thinking") return { type: b.type };
          const { cache_control: _cc, ...rest } = b;
          return rest;
        })
      : m?.content;
    return hashAny({ r: m?.role, c: content });
  });
  const messageCount = messages.length;

  return {
    systemHash: hashAny(systemBlocks),
    toolCount: tools.length,
    toolNames,
    perToolHash,
    model: params.model || "",
    betas,
    messageCount,
    perMessageHash,
    cacheMarkers: {
      system: systemBlocks.some((b) => b?.cache_control),
      toolsLast: !!tools[tools.length - 1]?.cache_control,
      messageFirst: Array.isArray(firstMsg?.content)

