export const meta = {
  name: 'msg0-prefix-anchor-rootcause',
  description: 'Find what dynamic field mutates msg[0] (the <system-context> prefix anchor) and busts the Anthropic prompt cache from position 0, then verify the root cause adversarially',
  phases: [
    { title: 'Map', detail: 'parallel readers: fork construction, bridge rewrite, err.log evidence, stability contract' },
    { title: 'Synthesize', detail: 'pin root cause file:line + introducing change + minimal byte-stable fix' },
    { title: 'Verify', detail: 'adversarial skeptics try to refute the named root cause' },
  ],
}

const MAP_SCHEMA = {
  type: 'object',
  required: ['summary', 'findings'],
  properties: {
    summary: { type: 'string', description: 'Tight prose summary of what you found' },
