export function buildCatalog(
  pi: ExtensionAPI,
  deferNames: ReadonlySet<string>,
  alwaysActive: ReadonlySet<string>,
  deferByDefault = false,
): CatalogEntry[] {
  const all = getRegisteredTools(pi);
  const availableNames = new Set(all.map((tool) => tool.name));
  const normalizedDefer = normalizeToolNames(deferNames);
  const normalizedAlwaysActive = normalizeToolNames(alwaysActive);
  const out: CatalogEntry[] = [];
  for (const tool of all) {
    if (!isPreferredVariant(tool, availableNames)) continue;
    if (hasToolName(normalizedAlwaysActive, tool.name)) continue;
    if (!deferByDefault && !hasToolName(normalizedDefer, tool.name)) continue;
    out.push({
      name: tool.name,
      description: tool.description ?? "",
      deferLoading: tool.deferLoading === true,
      searchBlob: `${tool.name} ${tool.description ?? ""}`.toLowerCase(),
    });
  }
  return out;
}

/**
 * Compute the active-tool list for the current session.
 *
 * Final active set = (every registered tool) − (deferred set ∩ catalog) + previouslyDiscovered.
 *
 * `alwaysActive` overrides `defer` — anything in alwaysActive stays even if
 * also listed in defer (defensive: protects load-bearing tools from a
 * config typo).
 */
export type DeferredToolMode = "none" | "anthropic_tool_reference" | "openai_codex_defer_loading";

function keepsDeferredSchemasActive(mode: boolean | DeferredToolMode): boolean {
  return mode === true || mode === "anthropic_tool_reference" || mode === "openai_codex_defer_loading";
}

