// CACHE CRITICAL: this block is part of the system prompt, which the claude
// bridge moves verbatim into `messages[0]` as <system-context> — i.e. the cached
// conversation prefix. Its bytes MUST NOT vary turn-to-turn, or every change
// busts the entire conversation cache from position 0 (msg[0]). So it is rendered
// purely from the session-stable catalog: no live "N deferred tools" count (which
// shrinks as tools are discovered) and the web hint is derived from the full
// catalog (stable all session) rather than the still-deferred subset (which
// flips when web tools are activated). `catalog` is the full deferrable set.
// Exported for the byte-stability regression test.
export function renderDeferredBlock(catalog: readonly CatalogEntry[]): string {
  const webTools = catalog
    .map((entry) => entry.name)
    .filter((name) => name === "web_search" || name === "web_fetch")
    .sort();
  const webHint = webTools.length
    ? `- Native web tools available: ${webTools.join(", ")}. For user requests to search/fetch the web, call tool_search({"query":"select:<ExactName>"}) and then call the discovered tool; do not load web-search/web-fetch skill refs as a substitute.\n`
    : "";
  return `\n\n${DEFERRED_BLOCK_OPEN}\n- Additional tools are available on demand. Use tool_search({"query":"<capability>"}) or tool_search({"query":"select:<ExactName>"}) to discover/load exact tools.\n${webHint}${DEFERRED_BLOCK_CLOSE}`;
}

