/**
 * Byte-stability regression test for the <deferred-tools> system-prompt block.
 *
 * The block is (re)injected into params.system every turn by before_agent_start,
 * and the claude bridge moves params.system verbatim into messages[0] as
 * <system-context> — i.e. the cached conversation prefix. If the block's bytes
 * change turn-to-turn, the ENTIRE conversation cache busts from position 0
 * (msg[0]). That was the single biggest fleet-wide cache-bust vector.
 *
 * This guards the two historical variance sources, both now removed:
 *   1. a live "${count} deferred tools available" count that shrank as tools
 *      were discovered (dominant vector), and
 *   2. a web hint derived from the still-deferred subset, which flipped present/
 *      absent once web tools were activated.
 * The block is now a pure function of the session-stable catalog.
 *
 * Run: node test-deferred-block-stability.mjs
 */
import assert from "node:assert/strict";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const { renderDeferredBlock } = await jiti.import("./src/index.ts");

const entry = (name) => ({ name, description: `${name} desc`, deferLoading: true, searchBlob: name });

// A catalog is fixed for a session. Discovery shrinks the active/deferred sets,
// never the catalog — so the block must be a pure function of catalog membership.
const catalogFull = ["web_search", "web_fetch", "Find", "Ls", "Grep", "monitor_start"].map(entry);
const block = renderDeferredBlock(catalogFull);

// 1. No live count: the block must not embed any "<N> deferred tools" number.
assert.doesNotMatch(block, /\d+\s+deferred tools/i, "block must not embed a live deferred-tools count");

// 2. Order-independent: the catalog is rebuilt every turn and may come back in a
//    different registration order; the block must still render identical bytes.
const reordered = ["monitor_start", "Grep", "web_fetch", "Ls", "web_search", "Find"].map(entry);
assert.equal(renderDeferredBlock(reordered), block, "block must be byte-identical under catalog reordering");

// 3. Discovery-independent: on a later turn most tools are already discovered, but
//    the catalog membership is unchanged, so the SAME catalog renders the SAME
//    bytes. (Pre-fix this differed because the count was derived from the
//    still-deferred subset.)
assert.equal(renderDeferredBlock(catalogFull), block, "block must be byte-stable across turns for a fixed catalog");

// 4. Web hint preserved, present, and deterministically ordered (sorted).
assert.match(
  block,
  /Native web tools available: web_fetch, web_search/,
  "web hint present and deterministically ordered",
);

// 5. Web hint absent when the catalog has no web tools (feature preserved, not faked).
const noWeb = ["Find", "Ls", "Grep"].map(entry);
assert.doesNotMatch(
  renderDeferredBlock(noWeb),
  /Native web tools available/,
  "no web hint when catalog has no web tools",
);

console.log("ok — <deferred-tools> block is byte-stable (no live count, order-independent, web hint session-stable)");

