if (authMode !== "apikey") {
  const billingBlock = {
    type: "text",
    text: `x-anthropic-billing-header: cc_version=${CLAUDE_CLI_VERSION}; cc_entrypoint=cli; cch=00000;`,
  };
  const ccPrefix = {
    type: "text",
    text: "You are Claude Code, Anthropic's official CLI for Claude.",
  };

  // Collect existing system blocks to move into messages
  let existingSystem = [];
  if (Array.isArray(params.system)) {
    existingSystem = params.system;
  } else if (typeof params.system === "string" && params.system) {
    existingSystem = [{ type: "text", text: params.system }];
  }

  // Keep system prompt short: just billing + CC prefix
  const newSystem = [billingBlock, ccPrefix];

  // Move the rest into a user message prepended to the conversation.
  //
  // CRITICAL (cross-session cache): preserve pi-ai's stable/dynamic block
  // split and its cache_control markers instead of flattening into one block.
  // For OAuth, pi-ai (anthropic.ts splitSystemPromptForCache) hands us:
  //   [CC identity, stable-core(+marker), dynamic-tail]
  // The stable-core is byte-identical across sessions and cwds, so keeping a
  // marker at the end of it makes the base prefix a SHARED Anthropic cache
  // entry every session can read. We also mark the end of the dynamic tail so
  // within-session / same-cwd turns still hit the full prefix. The old
  // behavior joined every block into one string with a single marker at the
  // very end, so the whole block (incl. cwd-specific project context + date)
  // was the only cache segment and nothing was shared across sessions.
  let newMessages = params.messages || [];
  // Drop pi-ai's CC-identity block (re-added to system as ccPrefix above) so
  // it is not duplicated inside the moved context.
  const movedBlocks = existingSystem.filter(
    (b) => b && b.text && b.text !== ccPrefix.text,
  );
  // BASE CACHE HEARTBEAT byte-match: pi's base heartbeat sends only the
  // stable base (no dynamic boundary) → a single moved block. The real
  // session request's stable block is `<system-context>\n${base}` with the
  // CLOSING tag living on the dynamic block. To make the heartbeat warm the
  // SAME Anthropic cache entry, its single block must omit the closing tag so
  // it is byte-identical to the real block[0]. Detect the heartbeat by its
  // reminder marker and suppress the closing tag only for that single-block
  // case. Session heartbeats carry the boundary (2 blocks) and already match.
  const isHeartbeat = Array.isArray(params.messages) && params.messages.some((m) => {
    const c = m && m.content;
    if (typeof c === "string") return c.includes(HEARTBEAT_REMINDER_MARKER);
    if (Array.isArray(c)) return c.some((b) => typeof (b && b.text) === "string" && b.text.includes(HEARTBEAT_REMINDER_MARKER));
    return false;
  });
  const suppressClose = isHeartbeat && movedBlocks.length === 1;
  const hasConversationHistory = Array.isArray(params.messages) && params.messages.length > 1 && !isHeartbeat;
  if (movedBlocks.length > 0) {
    const lastIdx = movedBlocks.length - 1;
    const contentBlocks = movedBlocks.map((b, i) => {
      let text = b.text;
      if (i === 0) text = `<system-context>\n${text}`;
