      // conversation requests, do NOT spend a second marker on the dynamic
      // system tail: the rolling transcript markers cover that prefix while
      // leaving enough of Anthropic's 4-marker budget for both previous and
      // latest cacheable message blocks. Without those two rolling markers,
      // long edit-loop sessions pin cache reads at the system/tools anchor
      // and rewrite the growing transcript tail every turn.
      const mark = Boolean(b.cache_control) || (i === lastIdx && !hasConversationHistory);
      return { type: "text", text, ...(mark ? { cache_control: EPHEMERAL } : {}) };
    });
    const contextMsg = { role: "user", content: contentBlocks };
    const ack = { role: "assistant", content: "Understood." };
    newMessages = [contextMsg, ack, ...newMessages];
  }

