  // Prefix non-Claude-Code tool names via the shared prefixToolName helper
  // (module scope), the single source of truth shared with the
  // tool_reference rewrite below so the two sets can never drift.
  let newTools = params.tools;
  if (Array.isArray(newTools)) {
    newTools = newTools.map((t) => {
      const prefixed = prefixToolName(t.name);
      return prefixed === t.name ? t : { ...t, name: prefixed };
    });
  }

  // Rewrite tool_reference block names in message content with the same
  // transform. tool_reference is request-only; the response strip at the
  //  replaceAll handles tool_use responses. MUST run before the
  // params={} assignment so cache breakpoints/sizing see transformed bytes.
  rewriteToolReferenceNames(newMessages);

  params = {
    ...params,
    system: newSystem,
    messages: newMessages,
    tools: newTools,
  };
