// Mid-conversation system messages: rewrite an extension-injected sentinel
// tail message into a real {role:"system"} entry (runs for both auth paths so
// the sentinel never leaks to the model).
if (Array.isArray(params.messages)) {
  params.messages = rewriteMidConversationSystemMessages(params.messages);
