				selectedCount: recall.hits.length,
				selectedPaths: recall.hits.map((hit) => hit.path).filter((path): path is string => Boolean(path)),
				latencyMs: recallLatencyMs,
			});
		}
		if (recall.text) {
			recordObservation("assistant_summary", recall.text, { kind: "recall", selected: recall.hits.length, omitted: recall.omitted });
			// Slice 3: deliver recall as a single trailing custom message after the
			// user turn (deliverAs:"nextTurn"), NOT a user-text transform. The old
			// transform rewrote the user's typed message → polluted up-arrow editor
			// history (the post-transform text was persisted and replayed on ↑) and
			// baked the recall blob into the prompt. A nextTurn custom message:
			//   (a) is appended right after the user message in THIS turn,
			//   (b) reaches the model exactly once via convertToLlm (custom→user),
			//   (c) renders the collapsible recall block (display:true) through the
			//       registered renderer, and
			//   (d) lands in the dynamic tail past the cache breakpoint, leaving the
			//       system-prompt prefix cache untouched.
			// content = model-facing recall; details drives the collapsed header.
			(ctx as unknown as ExtensionContext).sendMessage?.({
				customType: "pi_memory_recall",
				content: recall.text,
				display: true,
				details: recallTranscriptDetails(recall, recallLatencyMs),
			}, { deliverAs: "nextTurn" });

