1	import type { Api, Model, ToolReferenceContent } from "@valkyriweb/pi-ai";
2	import { type DeferredToolCapabilities, getDeferredToolCapabilities } from "./deferred-tool-capabilities.ts";
3	import type { ToolDefinition } from "./extensions/types.ts";
4	
5	export type DeferredToolReferenceBlock = ToolReferenceContent;
6	
7	export interface DeferredToolDiscoveryResult {
8		matches: ToolDefinition[];
9		missing: string[];
10		discoveredToolNames: string[];
11		referenceBlocks: DeferredToolReferenceBlock[];
12	}
13	
14	export const DEFERRED_TOOL_STATE_CUSTOM_TYPE = "pi.deferred_tools.state";
15	
16	export interface DeferredToolStateSnapshot {
17		discoveredToolNames: string[];
18	}
19	
20	interface DeferredToolStateEntryLike {
21		customType?: string;
22		data?: unknown;
23		details?: unknown;
24	}
25	
26	export interface DeferredToolSearchPlan {
27		mode: "native" | "fallback";
28		message: string;
29		matchedToolNames: string[];
30		missingToolNames: string[];
31		discoveredToolNames: string[];
32		referenceBlocks: DeferredToolReferenceBlock[];
33		activateToolNames: string[];
34		cacheMayBust: boolean;
35		capabilities?: DeferredToolCapabilities;
36	}
37	
38	export interface DeferredToolSearchRuntimeActions {
39		getActiveToolNames(): string[];
40		setActiveTools(toolNames: string[]): void;
41	}
42	
43	interface MessageLike {
44		content?: unknown;
45		deferredToolState?: DeferredToolStateSnapshot;
46	}
47	
48	export function isDeferredTool(definition: ToolDefinition): boolean {
49		return definition.deferLoading === true && definition.alwaysLoad !== true;
50	}
51	
52	export function searchDeferredTools(definitions: Iterable<ToolDefinition>, query: string): ToolDefinition[] {
53		const terms = query
54			.toLowerCase()
55			.split(/\s+/)
56			.map((term) => term.trim())
57			.filter(Boolean);
58		if (terms.length === 0) return [];
59	
60		return Array.from(definitions).filter((definition) => {
61			if (!isDeferredTool(definition)) return false;
62			const haystack = [definition.name, definition.description, definition.searchHint]
63				.filter(Boolean)
64				.join(" ")
65				.toLowerCase();
66			return terms.some((term) => haystack.includes(term));
67		});
68	}
69	
70	export function discoverDeferredTools(
71		definitions: Iterable<ToolDefinition>,
72		toolNames: Iterable<string>,
73		previouslyDiscovered: Iterable<string> = [],
74	): DeferredToolDiscoveryResult {
75		const byName = new Map(Array.from(definitions).map((definition) => [definition.name, definition]));
76		const discovered = new Set(filterAvailableDeferredToolNames(previouslyDiscovered, byName));
77		const matches: ToolDefinition[] = [];
78		const missing: string[] = [];
79	
80		for (const name of toolNames) {
81			const definition = byName.get(name);
82			if (!definition || !isDeferredTool(definition)) {
83				missing.push(name);
84				continue;
85			}
86			if (!discovered.has(name)) {
87				discovered.add(name);
88				matches.push(definition);
89			}
90		}
91	
92		const discoveredToolNames = Array.from(discovered);
93		return {
94			matches,
95			missing,
96			discoveredToolNames,
97			referenceBlocks: matches.map((definition) => ({ type: "tool_reference", name: definition.name })),
98		};
99	}
100	
101	export function planDeferredToolSearchResult(
102		definitions: Iterable<ToolDefinition>,
103		toolNames: Iterable<string>,
104		options: { nativeDeferredTools: boolean; previouslyDiscovered?: Iterable<string> },
105	): DeferredToolSearchPlan {
106		const discovery = discoverDeferredTools(definitions, toolNames, options.previouslyDiscovered);
107		const matchedToolNames = discovery.matches.map((tool) => tool.name);
108		const mode = options.nativeDeferredTools ? "native" : "fallback";
109	
110		return {
111			mode,
112			message: formatDeferredToolSearchMessage(matchedToolNames, discovery.missing, mode),
113			matchedToolNames,
114			missingToolNames: discovery.missing,
115			discoveredToolNames: discovery.discoveredToolNames,
116			referenceBlocks: options.nativeDeferredTools ? discovery.referenceBlocks : [],
117			activateToolNames: options.nativeDeferredTools ? [] : matchedToolNames,
118			cacheMayBust: !options.nativeDeferredTools && matchedToolNames.length > 0,
119		};
120	}
121	
122	export function planDeferredToolSearchForModel(
123		definitions: Iterable<ToolDefinition>,
124		toolNames: Iterable<string>,
125		model: Model<Api> | undefined,
126		previouslyDiscovered: Iterable<string> = [],
127	): DeferredToolSearchPlan {
128		const capabilities = getDeferredToolCapabilities(model);
129		const plan = planDeferredToolSearchResult(definitions, toolNames, {
130			nativeDeferredTools: capabilities.nativeDeferredTools && capabilities.toolReferenceResults,
131			previouslyDiscovered,
132		});
133		return {
134			...plan,
135			capabilities,
136			message: capabilities.fallbackReason ? `${plan.message} ${capabilities.fallbackReason}` : plan.message,
137		};
138	}
139	
140	export function executeDeferredToolSearchForModel(
141		definitions: Iterable<ToolDefinition>,
142		toolNames: Iterable<string>,
143		model: Model<Api> | undefined,
144		actions: DeferredToolSearchRuntimeActions,
145		previouslyDiscovered: Iterable<string> = [],
146	): DeferredToolSearchPlan {
147		const plan = planDeferredToolSearchForModel(definitions, toolNames, model, previouslyDiscovered);
148		if (plan.activateToolNames.length > 0) {
149			actions.setActiveTools(mergeFallbackActiveToolNames(actions.getActiveToolNames(), plan.activateToolNames));
150		}
151		return plan;
152	}
153	
154	export function mergeFallbackActiveToolNames(
155		currentActiveToolNames: Iterable<string>,
156		activateToolNames: Iterable<string>,
157	): string[] {
158		return Array.from(new Set([...currentActiveToolNames, ...activateToolNames]));
159	}
160	
161	export function filterAvailableDeferredToolNames(
162		discoveredToolNames: Iterable<string>,
163		definitions: Iterable<ToolDefinition> | Map<string, ToolDefinition>,
164	): string[] {
165		const byName =
166			definitions instanceof Map
167				? definitions
168				: new Map(Array.from(definitions).map((definition) => [definition.name, definition]));
169		return Array.from(new Set(discoveredToolNames)).filter((name) => {
170			const definition = byName.get(name);
171			return definition ? isDeferredTool(definition) : false;
172		});
173	}
174	
175	export function snapshotDeferredToolState(discoveredToolNames: Iterable<string>): DeferredToolStateSnapshot {
176		return { discoveredToolNames: Array.from(new Set(discoveredToolNames)) };
177	}
178	
179	export function createDeferredToolStateEntryData(discoveredToolNames: Iterable<string>): DeferredToolStateSnapshot {
180		return snapshotDeferredToolState(discoveredToolNames);
181	}
182	
183	export function scanDeferredToolStateEntries(entries: Iterable<unknown>): string[] {
184		const discovered = new Set<string>();
185		for (const rawEntry of entries) {
186			const entry = rawEntry as DeferredToolStateEntryLike;
187			if (entry.customType !== DEFERRED_TOOL_STATE_CUSTOM_TYPE) continue;
188			const snapshot = parseDeferredToolStateSnapshot(entry.data ?? entry.details);
189			for (const name of snapshot?.discoveredToolNames ?? []) discovered.add(name);
190		}
191		return Array.from(discovered);
192	}
193	
194	export function scanDiscoveredDeferredToolNames(messages: Iterable<MessageLike>): string[] {
195		const discovered = new Set<string>();
196		for (const name of scanDeferredToolStateEntries(messages)) discovered.add(name);
197		for (const message of messages) {
198			for (const name of message.deferredToolState?.discoveredToolNames ?? []) discovered.add(name);
199			for (const block of contentBlocks(message.content)) {
200				if (isDeferredToolReferenceBlock(block)) discovered.add(block.name);
201			}
202		}
203		return Array.from(discovered);
204	}
205	
206	function formatDeferredToolSearchMessage(matched: string[], missing: string[], mode: "native" | "fallback"): string {
207		const parts: string[] = [];
208		if (matched.length > 0) {
209			parts.push(
210				mode === "native"
211					? `Loaded deferred tool reference${matched.length === 1 ? "" : "s"}: ${matched.join(", ")}.`
212					: `Activated deferred tool${matched.length === 1 ? "" : "s"}: ${matched.join(", ")}. Cache may bust once on fallback providers.`,
213			);
214		}
215		if (missing.length > 0)
216			parts.push(`Unavailable deferred tool${missing.length === 1 ? "" : "s"}: ${missing.join(", ")}.`);
217		return parts.join(" ") || "No deferred tools matched.";
218	}
219	
220	function parseDeferredToolStateSnapshot(value: unknown): DeferredToolStateSnapshot | undefined {
221		if (
