export const meta = {
  name: 'verify-400k-thinking-causation',
  description: 'Prove (or refute) that accumulated extended-thinking is what drives pi sessions to 400k, and reverse-engineer exactly what Claude Code CLI does about it (local + on-wire)',
  phases: [
    { title: 'Investigate', detail: 'decompose real payload, reverse-engineer CC binary, trace pi local accounting' },
    { title: 'Synthesize', detail: 'answer: is thinking the cause + what CC does + reconciled recommendation' },
    { title: 'Verify', detail: 'adversarial check of the causation claim' },
  ],
}

const DECOMP_SCHEMA = {
  type: 'object',
  required: ['verdict', 'evidence', 'breakdown'],
  properties: {
    verdict: { type: 'string', enum: ['thinking-dominant', 'thinking-significant-not-dominant', 'thinking-minor', 'inconclusive'] },
    peak_total_tokens: { type: 'number', description: 'largest single-request context total found (tokens)' },
    breakdown: {
      type: 'array',
      description: 'token breakdown of the peak payload by component, descending',
      items: {
        type: 'object',
        required: ['component', 'tokens', 'pct'],
        properties: {
          component: { type: 'string', description: 'e.g. thinking-signatures, thinking-text, tool_result, tool_use, assistant-text, user-text, system-prompt, tool-schemas' },
          tokens: { type: 'number' },
          pct: { type: 'number' },
        },
      },
    },
    evidence: { type: 'string', description: 'how measured — file paths, counting method, exact numbers. Cite the session file(s).' },
    caveats: { type: 'array', items: { type: 'string' } },
  },
}

const CC_SCHEMA = {
  type: 'object',
  required: ['onwire_thinking', 'local_accounting', 'context_management', 'evidence'],
  properties: {
    onwire_thinking: { type: 'string', description: 'Does CC send ALL historical thinking blocks each turn, latest-only, or strip on tool-result boundaries? State the rule.' },
    local_accounting: { type: 'string', description: 'Does CC count thinking toward its local context-window / auto-compact threshold, or exclude/strip it locally? How does CC avoid runaway local context from thinking?' },
    context_management: { type: 'string', description: 'The clear_thinking / context_management behavior (the nY4-style handler): when attached, what edit, keep value.' },
    keeps_in_transcript: { type: 'string', description: 'Does CC retain full thinking in its local transcript/history file even if it trims the on-wire request?' },
    evidence: { type: 'string', description: 'binary strings/symbol/snippet evidence with the search terms used' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
  },
}

const PI_SCHEMA = {
  type: 'object',
  required: ['fork_sends_all_thinking', 'pi_counts_thinking_locally', 'where_400k_lives', 'evidence'],
  properties: {
    fork_sends_all_thinking: { type: 'boolean', description: 'Does anthropic.ts round-trip ALL historical signed thinking on the outbound request (no latest-only gate)?' },
    pi_counts_thinking_locally: { type: 'boolean', description: 'Does pi context-usage / compaction count thinking blocks toward the local budget that triggers compaction?' },
    where_400k_lives: { type: 'string', description: 'file:line of the compaction/context threshold and what token count it compares against (stored transcript vs sent payload vs usage-reported)' },
    keeping_local_still_hits_400k: { type: 'boolean', description: 'If thinking stays in the transcript, does pi still climb to the local 400k trigger?' },
    evidence: { type: 'string', description: 'file:line citations' },
  },
}

phase('Investigate')

const SESS_DIR = '/Users/luke/.pi/agent/sessions/--Users-luke-Projects-personal-my-pi--'

const investigators = [
  {
    label: 'decompose-payload',
    schema: DECOMP_SCHEMA,
    prompt: `Read-only forensic measurement, zero prior context. CLAIM UNDER TEST: "accumulated extended-thinking blocks are what drive long pi (opus-4.5+/sonnet-4.6+) sessions to ~400k tokens and trigger compaction." Your job is to PROVE or REFUTE this with a real payload decomposition — do not assume it.

Pi stores session transcripts as JSONL under ${SESS_DIR}/ (and sibling cwd dirs under /Users/luke/.pi/agent/sessions/). Each line is a message; assistant turns contain content blocks including extended-thinking blocks (type "thinking" with a large base64 "signature", plus "text"), tool_use, and tool_result.

DO THIS:
1. Find the LARGEST session transcripts (by file size) under ${SESS_DIR}/ — these are the long/bursting sessions. ls -S, pick the top few.
2. For the largest, reconstruct the context at its PEAK (the final or largest assistant request — the full message array as it would be sent). Decompose total tokens by component: thinking-signatures (the base64 blobs), thinking-text, tool_result content, tool_use, assistant-text, user-text, system-prompt, and tool-schemas if present. Approximate tokens as chars/4 (state your method) OR use the tokenizer at /Users/luke/Projects/personal/my-pi/extensions/context-usage/src/tokenizer.ts if practical.
3. Report the peak total and the descending breakdown with percentages. Is thinking (sig+text) the single largest component at the peak? By how much?
4. Cross-check against the bridge cache log /Users/luke/.pi/agent/logs/claude-bridge.err.log: grep the largest cache_write / cache_read numbers (these are real billed context sizes) to corroborate the peak total.

Be quantitative and honest. If thinking is NOT dominant, say what is. Use Bash (jq/grep/wc/node), Read. Cite exact file paths and numbers. Do NOT edit.`,
  },
  {
    label: 'cc-binary',
    schema: CC_SCHEMA,
    prompt: `Read-only reverse-engineering, zero prior context. Reverse-engineer how Claude Code CLI handles accumulated extended-thinking, BOTH on-wire and in local context accounting.

Binary: /Users/luke/.local/share/claude/versions/2.1.168 (Mach-O arm64, ~220MB, minified JS bundle inside). Use strings + grep on it (e.g. \`strings -n 6 <bin> | grep -i ...\`, or \`grep -a\`). Known anchor: a handler \`function nY4(H){let{hasThinking:_=!1}=H??{};if(_)return{edits:[{type:"clear_thinking_20251015",keep:"all"}]};return}\` and a beta map \`ID("context_management","context-management-2025-06-27")\`.

ANSWER THESE with binary evidence (search terms + matched snippets):
1. ON-WIRE: When CC builds the request, does it include ALL prior-turn thinking blocks, or only the latest, or strip thinking from completed turns (e.g. on tool_result boundaries / when not the last assistant message)? Search for thinking/redacted_thinking handling in message conversion, signature round-tripping, "keep" logic.
2. LOCAL ACCOUNTING: Does CC count thinking tokens toward its context-window usage / auto-compact threshold, or exclude them? How does CC keep local context from ballooning from thinking? Search for auto-compact, context window %, token counting, "thinking" exclusions.
3. context_management: confirm the clear_thinking edit shape + when it is attached (the nY4 path), and the keep value.
4. TRANSCRIPT: does CC keep full thinking in its local session/history file even when trimming the request?

Be precise. If a behavior can't be determined from the binary, say so. Cite the strings/grep you ran. Do NOT edit.`,
  },
  {
    label: 'pi-accounting',
    schema: PI_SCHEMA,
    prompt: `Read-only source trace, zero prior context. Determine whether pi's LOCAL context accounting (the thing that triggers compaction near 400k) counts extended-thinking blocks — i.e. whether keeping thinking in the transcript means pi still climbs to 400k even after the bridge clears it on Anthropic's side.

READ:
1. Fork outbound thinking round-trip: /Users/luke/Projects/personal/pi-mono-fork/packages/ai/src/providers/anthropic.ts around lines 1290-1340 (convertMessages / thinking handling). Does it emit ALL historical signed thinking blocks, or latest-only? Quote the gate.
2. Pi local context accounting: /Users/luke/Projects/personal/my-pi/extensions/context-usage/src/index.ts and tokenizer.ts — what does it count toward the context budget? Does it include thinking blocks?
3. The compaction / 400k trigger: grep the fork coding-agent for auto-compact / context-window threshold / token budget (e.g. packages/coding-agent/src/core/agent-session.ts, context-usage.ts). Find file:line of the threshold and WHAT token total it compares against — the stored transcript, the converted outbound payload, or a usage-reported number from the provider response.

ANSWER: does the fork send all thinking on-wire? does pi count thinking toward the local 400k trigger? if thinking stays in the transcript, does pi still hit 400k? Cite file:line. Do NOT edit.`,
  },
]

const findings = (await parallel(
  investigators.map((inv) => () => agent(inv.prompt, { label: inv.label, phase: 'Investigate', schema: inv.schema })),
)).filter(Boolean)

log(`Investigate: ${findings.length}/3 returned`)

phase('Synthesize')

const synth = await agent(
  `You are the synthesis lead. The user asked two pointed questions and is skeptical: (1) "Are you sure accumulated thinking is what caused the 400k tokens?" and (2) "What does Claude Code CLI do to handle this?" Answer both with the evidence below — do not overclaim.

Context: a bridge fix (clear_thinking_20251015 via context-management beta) already reduces ANTHROPIC-side billing/context. The open question is whether pi LOCALLY still climbs to 400k (its compaction trigger) because it keeps + counts thinking, and whether a fork-side change is warranted. The user wants thinking KEPT in the local transcript.

PAYLOAD DECOMPOSITION:
${findings[0] ? JSON.stringify(findings[0], null, 1) : '(none)'}

CLAUDE CODE BEHAVIOR:
${findings[1] ? JSON.stringify(findings[1], null, 1) : '(none)'}

PI LOCAL ACCOUNTING:
${findings[2] ? JSON.stringify(findings[2], null, 1) : '(none)'}

Produce a crisp answer:
1. CAUSATION VERDICT: Is accumulated thinking the proven dominant driver of the 400k, or not? Give the number (peak total + thinking %). If it's a co-factor with something else (tool_results, cache-bust re-bills), say so honestly.
2. WHAT CC DOES: on-wire (all/latest-only/strip-on-boundary), local accounting (counts thinking or not), context_management, transcript retention — the concrete CC playbook.
3. RECONCILED RECOMMENDATION: given CC's playbook and the user's "keep thinking in the transcript" constraint, what (if anything) should the fork do? Be specific: if CC trims on-wire but keeps transcript, that's the model to copy. If CC's local accounting already excludes thinking, maybe pi just needs to match that. Name the exact fork change (file:line) OR state that no fork change is needed and why.`,
  { label: 'synthesize', phase: 'Synthesize' },
)

phase('Verify')

const verdict = await agent(
  `Adversarially verify this causation + CC-behavior synthesis. Default to skeptical.

SYNTHESIS:
${synth}

Check, with your own read-only tools (binary at /Users/luke/.local/share/claude/versions/2.1.168, sessions under /Users/luke/.pi/agent/sessions/, fork at /Users/luke/Projects/personal/pi-mono-fork, /Users/luke/.pi/agent/logs/claude-bridge.err.log):
1. Is the "thinking is the dominant 400k driver" claim actually supported by the decomposition numbers, or is it overstated? Could the 400k be driven more by cache-bust re-bills, tool_results, or transcript growth?
2. Is the CC on-wire/local-accounting claim correct, or did the investigator over-read the binary? Spot-check one claim against the binary.
3. Does the recommendation actually follow, given the user keeps thinking in the transcript?
Return a short verdict: is the synthesis trustworthy enough to act on, what (if anything) is overstated, and the corrected bottom line.`,
  { label: 'verify', phase: 'Verify' },
)

return { synthesis: synth, adversarial_check: verdict }

